window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc04"]={"id":"bc04","title":"4. 蛋白质的生物学功能","sub":"朱圣庚《生物化学》第4版 · 第4章","sub2":"第4章 · AI统一版→AI精讲→过程→老师细节→单图→附录；网页题独立","modules":[{"i":0,"name":"第4章 蛋白质的生物学功能（老师PPT精讲+AI补充）","slides":[{"i":0,"sec":"老师PPT逐页","title":"第4章 蛋白质的生物学功能","notes":"本章从蛋白质三维结构转向“蛋白质怎样与其他分子相互作用”：Mb（肌红蛋白）/Hb（血红蛋白）、分子病、免疫球蛋白、肌肉收缩、结构-功能进化。","points":["目标：理解结构-功能关系。","主线：Mb（肌红蛋白）/Hb（血红蛋白）→分子病→免疫→肌肉→进化。","重点：氧合曲线、P50（半饱和氧分压）/Hill、Bohr/BPG（2,3-二磷酸甘油酸）、HbS（镰状血红蛋白）、IgG（免疫球蛋白G）、横桥。","方法：看图→记要点→做网页题。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-hb-v2.png","imageExplain":"读图顺序：先看标题「第4章 蛋白质的生物学功能」，再在图中找：这是AI统一版封面：用Mb（肌红蛋白）/Hb（血红蛋白）结构图提示本章主线——氧结合蛋白如何通过结构变化实现储氧、运输和别构调节。；把图中结构/曲线与要点对应；本页结论：本章从蛋白质三维结构转向“蛋白质怎样与其他分子相互作用”：Mb/Hb、分子病、免疫球蛋白、肌肉收缩、结构-功能进化。","source":"AI统一版封面·原书图4-6","srcType":"老师PPT","role":"查阅"},{"i":1,"sec":"老师PPT逐页","title":"本章导览：六大主题","notes":"学习顺序：AI统一版→AI考点/精讲→过程版→AI进化→老师细节→原书单图→网页题；原书页附录只查阅，不要求通读。","points":["第一步：AI统一版（Mb/Hb（血红蛋白））","第二步：AI考点/精讲/过程版","第三步：老师细节页（补老师重点）","第四步：原书单图+网页题","原书页附录只作查阅"],"fig":"","page":null,"anim":null,"cards":null,"imageExplain":"读图顺序：先看标题「本章导览：六大主题」，再在图中找：Mb（肌红蛋白）结构。；把图中结构/曲线与要点对应；本页结论：学习顺序：AI统一版→AI考点/精讲→过程版→AI进化→老师细节→原书单图→网页题。","source":"AI统一版导览","img":"assets/img/bc04book/fig-mb-v2.png","srcType":"老师PPT","role":"查阅"},{"title":"AI导学：Mb（肌红蛋白）/Hb（血红蛋白）到底在讲什么？","img":"assets/img/bc04book/fig-hb-v2.png","source":"AI统一版·原书图4-6｜对照老师第6章","notes":"先别急着背结构。这一章要回答三个问题：① O₂在血液里溶解度低，蛋白质怎样可逆结合并运输O₂？② 怎样调节亲和力，让肺里装氧、组织里卸氧？③ 一个氨基酸突变为什么会造成分子病？","imageExplain":"这张图先告诉你Mb（肌红蛋白）和Hb（血红蛋白）都是“珠蛋白折叠+血红素”，但Mb是单体、Hb是四聚体；先记住这个差别，后面曲线、协同、别构就都能串起来。","points":["Mb（肌红蛋白） = myoglobin（肌红蛋白）；Hb（血红蛋白） = hemoglobin（血红蛋白）。","一句话：Mb（肌红蛋白）是肌肉里的“氧气瓶”，Hb（血红蛋白）是血液里的“氧气出租车”。","Mb（肌红蛋白）：单体、1个O₂位点、高亲和、无协同；适合储氧。","Hb（血红蛋白）：α₂β₂四聚体、4个O₂位点、低亲和、有正协同；适合运输。","Hb（血红蛋白）的“协同”像出租车：第一个乘客上车后，后面乘客更容易上车；所以曲线是S形。","后面所有内容都围绕：结构→怎样结合O₂→怎样调节（P50/Hill/T→R/Bohr/BPG（2,3-二磷酸甘油酸））→突变怎样致病（HbS）。","S形曲线=正协同，详细在第10页“协同与Hill”展开。"],"i":2,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_2","kind":"fill","q":"后面所有内容都围绕：结构→怎样结合O₂→怎样调节（P50/Hill/T→R/Bohr/BPG（2,3-二磷酸甘油酸））→______怎样致病（HbS）。","a":"突变","e":"PPT原文：后面所有内容都围绕：结构→怎样结合O₂→怎样调节（P50/Hill/T→R/Bohr/BPG（2,3-二磷酸甘油酸））→突变怎样致病（HbS）。。正确答案：突变。","src":"PPT原文题"}},{"title":"AI统一版2：Mb（肌红蛋白）结构","img":"assets/img/bc04book/fig-mb-v2.png","source":"AI统一版·原书图4-3｜对照老师第6章","notes":"Mb（myoglobin，肌红蛋白）=1条153 aa肽链+1个血红素，8段α螺旋，中央疏水口袋；单体单位点，无协同。","imageExplain":"读图顺序：先看标题「AI统一版2：Mb结构」，再在图中找：先看8段α螺旋和血红素口袋；单体单位点决定双曲线。；把图中结构/曲线与要点对应；本页结论：Mb（myoglobin，肌红蛋白）=1条153 aa肽链+1个血红素，8段α螺旋，中央疏水口袋。","points":["1条链+1个血红素。","8段α螺旋，无β折叠。","疏水口袋保护Fe²⁺。","无协同，双曲线。"],"i":3,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_3","kind":"fill","q":"Mb（myoglobin，肌红蛋白）=1条153 aa肽链+1个血红素，8段______，中央疏水口袋","a":"α螺旋","e":"PPT原文：Mb（myoglobin，肌红蛋白）=1条153 aa肽链+1个血红素，8段α螺旋，中央疏水口袋。正确答案：α螺旋。","src":"PPT原文题"}},{"title":"AI统一版3：血红素/Fe配位","img":"assets/img/bc04book/mb.png","source":"AI统一版·原书Mb页｜对照老师第6章","notes":"血红素=原卟啉IX+Fe。Fe²⁺六配位：4个吡咯N、近侧His F8、O₂；远侧His E7限制CO。","imageExplain":"读图顺序：先看标题「AI统一版3：血红素/Fe配位」，再在图中找：看Fe的六个配体：4N、His F8、O₂；E7在O₂旁边提供位阻。；把图中结构/曲线与要点对应；本页结论：血红素=原卟啉IX+Fe。","points":["Fe²⁺六配位。","第5位His F8；第6位O₂。","远侧His E7限制CO。","Fe³⁺不能可逆结合O₂。"],"i":4,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版4：O₂结合与Fe位移","img":"assets/img/bc04book/fig-mb-v2.png","source":"AI统一版·原书图4-3｜对照老师第6章","notes":"O₂结合Fe²⁺后Fe入平面，牵动His F8/F螺旋；远侧His E7提供位阻并稳定O₂。","imageExplain":"读图顺序：先看标题「AI统一版4：O₂结合与Fe位移」，再在图中找：先看O₂占第6位，再看Fe入平面牵动F8/F螺旋。；把图中结构/曲线与要点对应；本页结论：O₂结合Fe²⁺后Fe入平面，牵动His F8/F螺旋。","points":["O₂占第6位。","Fe入平面→F8/F螺旋移动。","His E7提供位阻。","CO亲和力被降低。"],"i":5,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版5：Mb（肌红蛋白）定量与曲线","img":"assets/img/bc04book/fig-curves.png","source":"AI统一版·原书图4-4｜对照老师第6章","notes":"K=[Mb（肌红蛋白）][O₂]/[MbO₂]；Y=[O₂]/(K+[O₂])；Henry定律[O₂]=A pO₂；Y=pO₂/(P50（半饱和氧分压）+pO₂)，P50=K/A。","imageExplain":"读图顺序：先看标题「AI统一版5：Mb（肌红蛋白）定量与曲线」，再在图中找：这张图把Y与pO₂连起来：Y=0.5时pO₂=P50（半饱和氧分压）；Mb P50≈2 torr，双曲线。；把图中结构/曲线与要点对应；本页结论：K=[Mb][O₂]/[MbO₂]。","points":["K=[Mb（肌红蛋白）][O₂]/[MbO₂]。","Y=[O₂]/(K+[O₂])。","Henry: [O₂]=A pO₂。","Y=pO₂/(P50（半饱和氧分压）+pO₂)。"],"i":6,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版6：Hb（血红蛋白）四聚体","img":"assets/img/bc04book/fig-hb-v2.png","source":"AI统一版·原书图4-6｜对照老师第6章","notes":"Hb（hemoglobin，血红蛋白）=α₂β₂四聚体，4个血红素；亚基界面可动，协同/别构来自四级结构重排。","imageExplain":"读图顺序：先看标题「AI统一版6：Hb四聚体」，再在图中找：先看四个亚基和四个血红素，再看界面；Hb靠构象变化通信。；把图中结构/曲线与要点对应；本页结论：Hb（hemoglobin，血红蛋白）=α₂β₂四聚体，4个血红素。","points":["α₂β₂，4个O₂位点。","亚基界面可动。","协同来自四级结构。","S形曲线。"],"i":7,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_7","kind":"fill","q":"亚基界面可动，协同/别构来自______重排","a":"四级结构","e":"PPT原文：亚基界面可动，协同/别构来自四级结构重排。正确答案：四级结构。","src":"PPT原文题"}},{"title":"AI统一版7：T→R","img":"assets/img/bc04book/fig-tr.png","source":"AI统一版·原书图4-9｜对照老师第6章","notes":"O₂→Fe入平面→His F8/F螺旋→α1β2界面旋转→盐桥断裂→T→R；T低亲和，R高亲和。","imageExplain":"看图顺序：O₂→Fe→F8→界面→盐桥；T→R提高亲和力。","points":["T低亲和，R高亲和。","Fe入平面→F8/F螺旋。","界面旋转约15°。","盐桥断裂。"],"i":8,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版8：协同与Hill","img":"assets/img/bc04book/fig-curves.png","source":"AI统一版·原书图4-4｜对照老师第6章","notes":"Hb（血红蛋白） S形；Hill方程Y=pO₂ⁿ/(P50（半饱和氧分压）ⁿ+pO₂ⁿ)，n≈2.8；n=1无协同，n=4完全协同。","imageExplain":"读图顺序：先看标题「AI统一版8：协同与Hill」，再在图中找：对比Mb（肌红蛋白）双曲线和Hb（血红蛋白） S形；Hill图斜率=nH（Hill系数）。；把图中结构/曲线与要点对应；本页结论：Hb S形。","points":["Hb（血红蛋白） S形，Mb（肌红蛋白）双曲线。","nH（Hill系数）≈2.8正协同。","n=1无协同。","Hb（血红蛋白） P50（半饱和氧分压）≈26 torr。"],"i":9,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版9：Bohr/BPG（2,3-二磷酸甘油酸）","img":"assets/img/bc04book/fig-bpg.png","source":"AI统一版·原书图4-17｜对照老师第6章","notes":"H⁺/CO₂/BPG（2,3-二磷酸甘油酸）稳定T态→曲线右移→P50（半饱和氧分压）增大→组织卸氧；HbF（胎儿血红蛋白）结合BPG弱→左移。","imageExplain":"读图顺序：先看标题「AI统一版9：Bohr/BPG（2,3-二磷酸甘油酸）」，再在图中找：比较不同BPG/pH曲线：右移=亲和力下降/卸氧增加；BPG越高越右移。；把图中结构/曲线与要点对应；本页结论：H⁺/CO₂/BPG稳定T态→曲线右移→P50（半饱和氧分压）增大→组织卸氧。","points":["H⁺/CO₂/BPG（2,3-二磷酸甘油酸）→右移。","BPG（2,3-二磷酸甘油酸）结合β链中央空腔。","P50（半饱和氧分压）增大，卸氧增加。","HbF（胎儿血红蛋白）结合BPG（2,3-二磷酸甘油酸）弱→左移。"],"i":10,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅"},{"title":"AI统一版10：Mb（肌红蛋白） vs Hb（血红蛋白）总结","img":"assets/img/bc04book/fig-curves.png","source":"AI统一版·原书图4-4｜对照老师第6章","notes":"Mb（肌红蛋白）：单体/双曲线/P50（半饱和氧分压）≈2/储氧；Hb（血红蛋白）：四聚体/S形/P50≈26/运输；Hb受H⁺/CO₂/BPG（2,3-二磷酸甘油酸）调节，Mb基本不受。","imageExplain":"读图顺序：先看标题「AI统一版10：Mb（肌红蛋白） vs Hb（血红蛋白）总结」，再在图中找：同一张图对比两者：一个高亲和双曲线，一个低亲和S形；P50（半饱和氧分压）和曲线形状是核心区别。；把图中结构/曲线与要点对应；本页结论：Mb：单体/双曲线/P50≈2/储氧。","points":["Mb（肌红蛋白）：单体/双曲线/高亲和/储氧。","Hb（血红蛋白）：四聚体/S形/协同/运输。","Mb（肌红蛋白） P50（半饱和氧分压）≈2，Hb（血红蛋白） P50≈26。","Hb（血红蛋白）有别构调节。"],"i":11,"sec":"第4章 · AI统一版样板（Mb/Hb）","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_11","kind":"fill","q":"Hb（血红蛋白）有______调节。","a":"别构","e":"PPT原文：Hb（血红蛋白）有别构调节。。正确答案：别构。","src":"PPT原文题"}},{"sec":"第4章 · AI考点串讲","title":"AI串讲1：Mb（肌红蛋白） vs Hb（血红蛋白） 一张表","notes":"蛋白质结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰；同源蛋白保守残基常位于结构/功能关键位点。","points":["突变→序列变异→功能差异。","有利/中性保留，不利淘汰。","保守残基提示关键位点。"],"table":[["符号","中文"],["Mb","肌红蛋白"],["Hb","血红蛋白"],["HbA","成人血红蛋白"],["HbS","镰状血红蛋白"],["HbF","胎儿血红蛋白"],["P50","半饱和氧分压"],["Y","氧饱和度"],["nH","Hill系数"],["BPG","2,3-二磷酸甘油酸"]],"tableTitle":"Mb/Hb常用符号","i":12,"img":"assets/img/bc04/full29.jpg","imageExplain":"这张图在讲：蛋白质结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰；同源蛋白保守残基常位于结构/功能关键位点。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第29页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_12","kind":"fill","q":"______结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰","a":"蛋白质","e":"PPT原文：蛋白质结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰。正确答案：蛋白质。","src":"PPT原文题"}},{"sec":"第4章 · AI考点串讲","title":"AI串讲2：T→R与别构效应链","notes":"【图源】AI考点串讲配图/老师原图。O₂结合血红素后，Fe²⁺进入卟啉环平面，牵动His F8和F螺旋，经α1β2界面放大，T态盐桥断裂，四聚体转向R态。","points":["T态=去氧、低亲和；R态=氧合、高亲和。","O₂→Fe²⁺入平面→His F8/F螺旋移动→α1β2界面旋转→T→R。","H⁺（Bohr）和CO₂稳定T态，曲线右移，促进卸氧。","BPG（2,3-二磷酸甘油酸）结合β链中央空腔，稳定T态；BPG升高→右移。","CO与Fe²⁺高亲和，竞争O₂；CO中毒既占位又改变亲和力。"],"table":[["效应物","作用","曲线","生理意义"],["H⁺↑（pH↓）","稳定T","右移","组织卸氧"],["CO₂↑","形成氨基甲酸酯，稳定T","右移","组织卸氧"],["BPG（2,3-二磷酸甘油酸）↑","交联β链，稳定T","右移","高原/贫血代偿"],["BPG（2,3-二磷酸甘油酸）↓/HbF（胎儿血红蛋白）","稳定R倾向","左移","胎儿取氧"],["温度↑","稳定T","右移","运动组织卸氧"]],"tableTitle":"别构效应速查","i":13,"img":"assets/img/bc04/full33.jpg","imageExplain":"这张图讲Hb（血红蛋白）氧合时T→R：O₂结合Fe后，Fe进入卟啉环平面，牵动His F8/F螺旋，经α1β2界面放大，T态盐桥断裂，四聚体转向R态。","source":"老师第6章PPT 第33页","srcType":"白话辅助","role":"查阅"},{"sec":"第4章 · AI考点串讲","title":"AI串讲3：IgG（免疫球蛋白G）与免疫检测","notes":"【图源】AI考点串讲配图/老师原图。IgG（免疫球蛋白G）是Y形四链分子；Fab（抗原结合片段）负责结合抗原，Fc（可结晶片段）负责效应功能。ELISA（酶联免疫吸附测定）和Western（蛋白印迹） blot都利用抗体特异性。","points":["IgG（免疫球蛋白G）=2条重链γ+2条轻链κ/λ，二硫键连接。","Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区），含CDR（互补决定区），结合抗原。","Fc（可结晶片段）=CH2+CH3，结合补体/Fc受体，介导效应。","木瓜蛋白酶→2 Fab（抗原结合片段）+Fc（可结晶片段）；胃蛋白酶→F(ab′)₂+小片段。","ELISA（酶联免疫吸附测定）：抗原/抗体包被→酶标抗体→底物显色；Western（蛋白印迹） blot：SDS-PAGE→转膜→抗体检测。"],"table":[["片段/方法","组成/原理","用途"],["Fab（抗原结合片段）","VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区）","抗原结合"],["Fc（可结晶片段）","CH2+CH3","补体/Fc（可结晶片段）受体效应"],["ELISA（酶联免疫吸附测定）","抗体-酶偶联+底物显色","定量/筛查"],["Western（蛋白印迹） blot","电泳+转膜+抗体","鉴定特定蛋白"],["单克隆抗体","B细胞+骨髓瘤融合→杂交瘤","特异试剂"]],"tableTitle":"IgG与免疫检测","i":14,"img":"assets/img/bc04/full65.jpg","imageExplain":"这张IgG（免疫球蛋白G）图是Y形四链：Fab（抗原结合片段）负责结合抗原，Fc（可结晶片段）负责补体/Fc受体效应；木瓜蛋白酶切出2个Fab+Fc，胃蛋白酶切出F(ab′)₂。","source":"老师第6章PPT 第65页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_14","kind":"fill","q":"IgG（免疫球蛋白G）=2条重链γ+2条轻链κ/λ，______连接。","a":"二硫键","e":"PPT原文：IgG（免疫球蛋白G）=2条重链γ+2条轻链κ/λ，二硫键连接。。正确答案：二硫键。","src":"PPT原文题"}},{"sec":"第4章 · AI考点串讲","title":"AI串讲4：肌肉收缩与肌丝滑行","notes":"【图源】AI考点串讲配图/老师原图。肌肉收缩时粗细肌丝本身不缩短，而是细丝在粗丝上滑行；Ca²⁺和ATP（三磷酸腺苷）是核心。","points":["肌节：Z线到Z线；A带=粗丝长度，I带/H带在收缩时变窄。","细丝：F-肌动蛋白+原肌球蛋白+肌钙蛋白；粗丝：肌球蛋白。","Ca²⁺结合肌钙蛋白→原肌球蛋白移位→暴露肌动蛋白结合位点。","肌球蛋白横桥结合肌动蛋白，水解ATP（三磷酸腺苷）驱动摆动；反复循环拉细丝。","松弛：Ca²⁺被钙泵回收，ATP（三磷酸腺苷）使肌球蛋白与肌动蛋白解离。"],"table":[["结构","组成/变化"],["A带","粗丝全长，收缩时不变"],["I带/H带","收缩时变窄"],["细丝","肌动蛋白+原肌球蛋白+肌钙蛋白"],["粗丝","肌球蛋白"],["触发","Ca²⁺结合肌钙蛋白"],["能量","ATP（三磷酸腺苷）水解驱动横桥循环"]],"tableTitle":"肌丝滑行要点","i":15,"img":"assets/img/bc04/full90.jpg","imageExplain":"这张肌丝滑行图说明：收缩时粗细肌丝本身不缩短，细丝在粗丝上滑动，I带/H带变窄，A带不变；Ca²⁺和ATP（三磷酸腺苷）驱动横桥循环。","source":"老师第6章PPT 第90页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_15","kind":"fill","q":"肌球蛋白横桥结合肌动蛋白，水解______（三磷酸腺苷）驱动摆动；反复循环拉细丝。","a":"ATP","e":"PPT原文：肌球蛋白横桥结合肌动蛋白，水解ATP（三磷酸腺苷）驱动摆动；反复循环拉细丝。。正确答案：ATP。","src":"PPT原文题"}},{"sec":"第4章 · AI精讲","title":"AI精讲1：Hb（血红蛋白）的T→R构象变化","img":"assets/img/bc04/full33.jpg","notes":"O₂结合Fe²⁺后，Fe进入卟啉环平面，牵动His F8和F螺旋，经α1β2界面放大，T态盐桥断裂，四聚体转向R态。","imageExplain":"这张图讲Hb（血红蛋白）从T态到R态：先看O₂结合血红素，Fe被拉入平面；再看His F8/F螺旋移动；最后看α1β1与α2β2相对旋转、盐桥断裂。结果是Hb从低亲和T态变成高亲和R态。","points":["T态=去氧低亲和；R态=氧合高亲和。","O₂→Fe入平面→His F8/F螺旋→α1β2界面旋转。","T态盐桥断裂，中央空腔缩小，BPG（2,3-二磷酸甘油酸）释放。","协同来自四级结构重排，不是血红素直接传O₂。"],"i":16,"source":"老师第6章PPT 第33页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_16","kind":"fill","q":"协同来自______重排，不是血红素直接传O₂。","a":"四级结构","e":"PPT原文：协同来自四级结构重排，不是血红素直接传O₂。。正确答案：四级结构。","src":"PPT原文题"}},{"sec":"第4章 · AI精讲","title":"AI精讲2：Bohr/BPG（2,3-二磷酸甘油酸）与曲线左右移","img":"assets/img/bc04/full50.jpg","notes":"H⁺、CO₂、BPG（2,3-二磷酸甘油酸）升高都稳定T态，使Hb（血红蛋白）氧合曲线右移、P50（半饱和氧分压）增大、促进卸氧；BPG结合β链中央空腔。","imageExplain":"这张图讲别构效应物怎样让Hb（血红蛋白）更容易“放氧”。先认横轴pO₂、纵轴Y；曲线右移表示同样pO₂下Y更低、亲和力下降。H⁺/CO₂/BPG（2,3-二磷酸甘油酸）都稳定T态，所以右移；HbF（胎儿血红蛋白）结合BPG弱，曲线相对左移。","points":["H⁺↑/pH↓、CO₂↑、BPG（2,3-二磷酸甘油酸）↑→稳定T→右移→卸氧。","BPG（2,3-二磷酸甘油酸）带负电，结合β链中央空腔，形成盐桥。","BPG（2,3-二磷酸甘油酸）↑（高原/贫血）→P50（半饱和氧分压）增大，组织卸氧增加。","HbF（胎儿血红蛋白）对BPG（2,3-二磷酸甘油酸）亲和弱→曲线左移，利于胎儿取氧。"],"i":17,"source":"老师第6章PPT 第50页","srcType":"白话辅助","role":"查阅"},{"sec":"第4章 · AI精讲","title":"AI精讲3：HbS（镰状血红蛋白）聚集与电泳","img":"assets/img/bc04/full61.jpg","notes":"HbS（镰状血红蛋白）为β6 Glu→Val，脱氧后疏水补丁暴露，分子间聚集成长纤维，红细胞镰变；pH8.6电泳HbS比HbA（成人血红蛋白）慢。","imageExplain":"这张图讲HbS（镰状血红蛋白）为什么会把红细胞拉成镰刀：先看β6 Glu→Val少一个负电荷；再看脱氧HbS的疏水补丁互相粘住，聚成纤维；最后纤维把红细胞膜撑变形。电泳时HbS负电荷少，向正极跑得慢。","points":["HbS（镰状血红蛋白）：β6 Glu→Val，负电荷减少。","脱氧HbS（镰状血红蛋白）疏水补丁暴露→分子间聚集→纤维。","低氧促进脱氧HbS（镰状血红蛋白）聚集，镰变加重。","pH8.6电泳：HbA（成人血红蛋白）快，HbS（镰状血红蛋白）慢；HbAS（镰状细胞特质血红蛋白）两条带。"],"i":18,"source":"老师第6章PPT 第61页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_18","kind":"fill","q":"pH8.6______：HbA（成人血红蛋白）快，HbS（镰状血红蛋白）慢；HbAS（镰状细胞特质血红蛋白）两条带。","a":"电泳","e":"PPT原文：pH8.6电泳：HbA（成人血红蛋白）快，HbS（镰状血红蛋白）慢；HbAS（镰状细胞特质血红蛋白）两条带。。正确答案：电泳。","src":"PPT原文题"}},{"sec":"第4章 · AI精讲","title":"AI精讲4：IgG（免疫球蛋白G）的Fab（抗原结合片段）/Fc（可结晶片段）与酶切","img":"assets/img/bc04/full65.jpg","notes":"IgG（免疫球蛋白G）为Y形四链；Fab（抗原结合片段）结合抗原，Fc（可结晶片段）介导补体/Fc受体；木瓜蛋白酶切出2 Fab+Fc，胃蛋白酶切出F(ab′)₂。","imageExplain":"这张图讲IgG（免疫球蛋白G）“哪里抓抗原、哪里叫免疫系统”。先看Y形：两个臂的Fab（抗原结合片段）含VH（重链可变区）+VL（轻链可变区），是抓抗原的手；柄的Fc（可结晶片段）含CH2+CH3，负责补体/Fc受体。木瓜蛋白酶在铰链处切，得到2个Fab+1个Fc；胃蛋白酶切出双价F(ab′)₂。","points":["IgG（免疫球蛋白G）=2重链γ+2轻链κ/λ。","Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区），含CDR（互补决定区），结合抗原。","Fc（可结晶片段）=CH2+CH3，结合补体/Fc受体。","木瓜蛋白酶→2 Fab（抗原结合片段）+Fc（可结晶片段）；胃蛋白酶→F(ab′)₂+小片段。"],"i":19,"source":"老师第6章PPT 第65页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_19","kind":"fill","q":"Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区），含CDR（互补决定区），结合______。","a":"抗原","e":"PPT原文：Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区），含CDR（互补决定区），结合抗原。。正确答案：抗原。","src":"PPT原文题"}},{"sec":"第4章 · AI精讲","title":"AI精讲5：ELISA（酶联免疫吸附测定）与Western（蛋白印迹） blot","img":"assets/img/bc04/full73.jpg","notes":"ELISA（酶联免疫吸附测定）用抗原-抗体特异结合+酶标显色定量；Western（蛋白印迹） blot先电泳、转膜，再用抗体检测目标蛋白。","imageExplain":"这张图讲ELISA（酶联免疫吸附测定）怎么“用颜色告诉你有没有抗原/抗体”。先看孔板包被抗原或抗体；再加样品和酶标抗体；最后加底物显色，颜色深浅反映含量。Western（蛋白印迹） blot则是先电泳分开蛋白、转膜，再用抗体找目标条带。","points":["ELISA（酶联免疫吸附测定）：包被→加样品→酶标抗体→底物显色。","颜色深浅与目标物含量相关。","Western（蛋白印迹） blot：SDS-PAGE→转膜→抗体孵育→显色/发光。","两者都依赖抗原-抗体特异结合；Western（蛋白印迹）还能看分子量。"],"i":20,"source":"老师第6章PPT 第73页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_20","kind":"fill","q":"ELISA（酶联免疫吸附测定）：包被→加样品→酶标______→底物显色。","a":"抗体","e":"PPT原文：ELISA（酶联免疫吸附测定）：包被→加样品→酶标抗体→底物显色。。正确答案：抗体。","src":"PPT原文题"}},{"sec":"第4章 · AI精讲","title":"AI精讲6：肌肉收缩横桥循环","img":"assets/img/bc04/full90.jpg","notes":"Ca²⁺结合肌钙蛋白→原肌球蛋白移位→暴露肌动蛋白位点；肌球蛋白横桥结合并水解ATP（三磷酸腺苷），摆动拉细丝。","imageExplain":"这张图讲肌肉收缩的“拉绳子”过程：先看Ca²⁺结合肌钙蛋白，原肌球蛋白让开；再看肌球蛋白头抓住肌动蛋白；ATP（三磷酸腺苷）水解让头摆动，把细丝往中央拉；ATP结合使头松开，循环重复。A带不变，I/H带变窄。","points":["Ca²⁺结合肌钙蛋白→原肌球蛋白移位→暴露位点。","肌球蛋白横桥结合肌动蛋白。","ATP（三磷酸腺苷）水解驱动头部摆动，拉细丝。","ATP（三磷酸腺苷）结合使横桥解离；Ca²⁺回收后松弛。"],"i":21,"source":"老师第6章PPT 第90页","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_21","kind":"fill","q":"______（三磷酸腺苷）水解驱动头部摆动，拉细丝。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）水解驱动头部摆动，拉细丝。。正确答案：ATP。","src":"PPT原文题"}},{"sec":"第4章 · 过程版","title":"过程版1：Hill方程与P50（半饱和氧分压）计算","notes":"先判断Mb（肌红蛋白）还是Hb（血红蛋白），再选公式；Mb用双曲线，Hb用Hill方程。计算时先算比值，再取n次方。","points":["Mb（肌红蛋白）：Y=pO₂/(pO₂+P50（半饱和氧分压）)。","Hb（血红蛋白）：Y=pO₂ⁿ/(P50（半饱和氧分压）ⁿ+pO₂ⁿ)，n=nH（Hill系数）。","Y=0.5时pO₂=P50（半饱和氧分压）。","Hill图：log(Y/(1−Y))对log pO₂作图，斜率=nH（Hill系数）。"],"table":[["对象","公式/示例"],["Mb（肌红蛋白）","P50（半饱和氧分压）=2 torr，pO₂=10 → Y=10/(10+2)=0.833"],["Hb（血红蛋白）","P50（半饱和氧分压）=26 torr，n=2.8，pO₂=100 → (100/26)^2.8≈43.4 → Y≈0.977"],["Hb（血红蛋白）","pO₂=10 → (10/26)^2.8≈0.069 → Y≈0.064"],["Hill图","斜率=nH（Hill系数）；x轴截距=logP50"]],"tableTitle":"Hill方程计算","i":22,"img":"assets/img/bc04book/fig-curves.png","source":"AI整理（依据老师PPT/原书）","imageExplain":"读图顺序：先看标题「过程版1：Hill方程与P50（半饱和氧分压）计算」，再在图中找：看Hill/氧合曲线。；把图中结构/曲线与要点对应；本页结论：先判断Mb（肌红蛋白）还是Hb（血红蛋白），再选公式。","srcType":"白话辅助","role":"练习"},{"sec":"第4章 · 过程版","title":"过程版2：判断氧合曲线左移/右移","notes":"先找效应物，再判断它稳定T态还是R态，最后判断曲线方向和生理意义。","points":["稳定T态→右移（P50↑，亲和力↓，卸氧增加）。","稳定R态→左移（P50↓，亲和力↑，结合氧增加）。","H⁺↑、CO₂↑、BPG（2,3-二磷酸甘油酸）↑、温度↑→右移。","HbF（胎儿血红蛋白）对BPG（2,3-二磷酸甘油酸）亲和弱→左移，利于胎儿取氧。"],"table":[["变化","稳定状态","曲线","结果"],["pH↓/H⁺↑","T","右移","组织卸氧"],["BPG（2,3-二磷酸甘油酸）↑","T","右移","高原/贫血代偿"],["HbF（胎儿血红蛋白）","R倾向","左移","胎儿取氧"],["CO","占位/改变亲和","复杂","中毒"]],"tableTitle":"左移/右移判断","i":23,"img":"assets/img/bc04book/fig-curves.png","source":"AI整理（依据老师PPT/原书）","imageExplain":"读图顺序：先看标题「过程版2：判断氧合曲线左移/右移」，再在图中找：看曲线左移/右移。；把图中结构/曲线与要点对应；本页结论：先找效应物，再判断它稳定T态还是R态，最后判断曲线方向和生理意义。","srcType":"白话辅助","role":"练习"},{"sec":"第4章 · 过程版","title":"过程版3：HbA（成人血红蛋白）/HbS（镰状血红蛋白）电泳判读","notes":"HbS（镰状血红蛋白）是β链Glu6→Val突变，少一个负电荷；pH 8.6电泳时HbS向正极迁移较慢。","points":["HbA（成人血红蛋白）：β链第6位Glu（负电）。","HbS（镰状血红蛋白）：β链第6位Val（中性），负电荷减少。","pH 8.6：HbA（成人血红蛋白）更负，向正极移动更快；HbS（镰状血红蛋白）较慢。","HbAS（镰状细胞特质血红蛋白）杂合子两条带；HbSS（镰状细胞贫血血红蛋白）一条慢带；正常HbA（成人血红蛋白）一条快带。","电泳后可用染色/密度扫描定量。"],"table":[["样品","条带","解释"],["正常HbA（成人血红蛋白）","一条快带","β6 Glu"],["HbAS（镰状细胞特质血红蛋白）","快+慢两条","杂合子"],["HbSS（镰状细胞贫血血红蛋白）","一条慢带","β6 Val"],["电泳方向","正极","HbA（成人血红蛋白）更快"]],"tableTitle":"HbA/HbS电泳","i":24,"img":"assets/img/bc04book/fig-sickle-v2.png","source":"AI整理（依据老师PPT/原书）","imageExplain":"读图顺序：先看标题「过程版3：HbA（成人血红蛋白）/HbS（镰状血红蛋白）电泳判读」，再在图中找：看HbA/HbS电泳/指纹。；把图中结构/曲线与要点对应；本页结论：HbS是β链Glu6→Val突变，少一个负电荷。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_24","kind":"fill","q":"______后可用染色/密度扫描定量。","a":"电泳","e":"PPT原文：电泳后可用染色/密度扫描定量。。正确答案：电泳。","src":"PPT原文题"}},{"sec":"第4章 · 过程版","title":"过程版4：测Hb（血红蛋白）氧亲和力实验设计","notes":"用分光光度法测不同pO₂下的Y，作氧合曲线，拟合Hill方程求P50（半饱和氧分压）和nH（Hill系数）；加BPG（2,3-二磷酸甘油酸）/H⁺比较曲线位移。","points":["样品：纯化Hb（血红蛋白），控制温度、pH、离子强度。","测Y：不同pO₂平衡后测吸收光谱，计算氧饱和度。","作图：Y对pO₂；拟合Hill方程求P50（半饱和氧分压）、nH（Hill系数）。","对照：无BPG（2,3-二磷酸甘油酸） vs +BPG；pH 7.4 vs 7.2；空白/还原/氧化对照。","结论：右移=P50（半饱和氧分压）增大、亲和力下降。"],"table":[["步骤","操作"],["1","配制Hb（血红蛋白）缓冲液，控制pH/温度"],["2","不同pO₂平衡，测吸收光谱"],["3","计算Y，作氧合曲线"],["4","拟合Hill方程，求P50（半饱和氧分压）/nH（Hill系数）"],["5","±BPG（2,3-二磷酸甘油酸）/±H⁺重复，比较曲线"]],"tableTitle":"氧亲和力实验设计","i":25,"img":null,"source":"AI整理（依据老师PPT/原书）","imageExplain":null,"srcType":"白话辅助","role":"练习"},{"title":"AI进化1：同源蛋白与保守残基","img":"assets/img/bc04/full31.jpg","source":"AI进化专题·老师第6章PPT页｜对照原书同源序列","notes":"同源蛋白由共同祖先基因演化，序列/结构相似；不同物种Hb（血红蛋白）序列比较发现9个高度保守残基，常位于血红素结合/亚基界面等关键位点。","imageExplain":"读图顺序：先看标题「AI进化1：同源蛋白与保守残基」，再在图中找：这张图比较不同物种Hb（血红蛋白）序列：先看保守残基位置，再看它们多在血红素口袋/亚基界面；说明这些位置受选择压力。；把图中结构/曲线与要点对应；本页结论：同源蛋白由共同祖先基因演化，序列/结构相似。","points":["同源=共同祖先起源。","保守残基常位于结构/功能关键位点。","非极性内部残基可互换，功能不变。","序列相似≠功能一定相同。"],"i":26,"sec":"第4章 · AI进化专题","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_26","kind":"fill","q":"同源蛋白由共同祖先______演化，序列/结构相似","a":"基因","e":"PPT原文：同源蛋白由共同祖先基因演化，序列/结构相似。正确答案：基因。","src":"PPT原文题"}},{"title":"AI进化2：一个突变怎样改变功能","img":"assets/img/bc04/full60.jpg","source":"AI进化专题·老师第6章PPT页｜对照HbA/HbS","notes":"HbA（成人血红蛋白） β6=Glu（负电），HbS（镰状血红蛋白） β6=Val（中性）；一个氨基酸替换改变电荷/溶解度，脱氧时聚集，导致镰状细胞贫血。","imageExplain":"读图顺序：先看标题「AI进化2：一个突变怎样改变功能」，再在图中找：这张图对比HbA（成人血红蛋白）/HbS（镰状血红蛋白） β链前几个残基：第6位Glu→Val；先看差异位点，再看它如何改变电荷和聚集。；把图中结构/曲线与要点对应；本页结论：HbA β6=Glu（负电），HbS β6=Val（中性）。","points":["HbA（成人血红蛋白） β6=Glu；HbS（镰状血红蛋白） β6=Val。","一个突变可改变电荷/溶解度/功能。","HbS（镰状血红蛋白）脱氧聚集→镰变。","结构-功能关系：局部改变可放大为疾病。"],"i":27,"sec":"第4章 · AI进化专题","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_27","kind":"fill","q":"一个______可改变电荷/溶解度/功能。","a":"突变","e":"PPT原文：一个突变可改变电荷/溶解度/功能。。正确答案：突变。","src":"PPT原文题"}},{"title":"AI进化3：基因复制、突变与选择","img":"assets/img/bc04/full98.jpg","source":"AI进化专题·老师第6章PPT页","notes":"基因复制产生冗余拷贝，突变积累后可分化出新功能；有利/中性突变被保留，不利/致死突变被淘汰，形成蛋白质家族和物种差异。","imageExplain":"读图顺序：先看标题「AI进化3：基因复制、突变与选择」，再在图中找：这张图讲进化的三个环节：基因复制→突变→选择；先看复制产生新拷贝，再看突变和选择如何保留有利变异。；把图中结构/曲线与要点对应；本页结论：基因复制产生冗余拷贝，突变积累后可分化出新功能。","points":["基因复制→冗余拷贝。","突变积累→序列/功能分化。","选择保留有利/中性，淘汰不利。","结果：蛋白质家族/物种差异。"],"i":28,"sec":"第4章 · AI进化专题","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_28","kind":"fill","q":"结果：______家族/物种差异。","a":"蛋白质","e":"PPT原文：结果：蛋白质家族/物种差异。。正确答案：蛋白质。","src":"PPT原文题"}},{"title":"AI进化4：结构-功能进化总结","img":"assets/img/bc04book/fig-hb-v2.png","source":"AI进化专题·原书图4-6｜老师第6章","notes":"Mb（肌红蛋白）/Hb（血红蛋白）同源但功能不同：序列差异+基因复制/突变+选择，形成储氧/运输/协同等差异；保守残基维持共同结构框架。","imageExplain":"这张总结图把Mb（肌红蛋白）/Hb（血红蛋白）放一起：先看共同珠蛋白折叠，再看序列差异和功能分化；结论是“共同框架+可变细节”产生功能多样性。","points":["Mb（肌红蛋白）/Hb（血红蛋白）共享珠蛋白折叠。","序列差异+复制/突变→功能分化。","保守残基维持关键结构。","进化题先找同源、保守、功能差异。"],"i":29,"sec":"第4章 · AI进化专题","srcType":"白话辅助","role":"查阅","check":{"id":"bc04_ck_29","kind":"fill","q":"序列差异+复制/______→功能分化。","a":"突变","e":"PPT原文：序列差异+复制/突变→功能分化。。正确答案：突变。","src":"PPT原文题"}},{"i":30,"sec":"老师PPT逐页","title":"一、肌红蛋白的结构与功能（章节标题）","notes":"【图源】老师第6章PPT原页。本页仅为“一、肌红蛋白（myoglobin，Mb（肌红蛋白））的结构与功能”的章节标题，没有结构图或数据；后续页从肌红蛋白三维结构开始。","points":["章节标题页"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full3.jpg","imageExplain":"读图顺序：先看标题「一、肌红蛋白的结构与功能（章节标题）」，再在图中找：这张图在讲：后续页从肌红蛋白三维结构开始。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：章节标题页。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第3页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_30","kind":"fill","q":"后续页从______三维结构开始","a":"肌红蛋白","e":"PPT原文：后续页从肌红蛋白三维结构开始。正确答案：肌红蛋白。","src":"PPT原文题"}},{"i":31,"sec":"老师PPT逐页","title":"肌红蛋白","notes":"Mb（肌红蛋白）存在于肌肉，由1条153 aa肽链+1个血红素组成，Mr（相对分子质量）≈16700；去掉血红素后的肽链称珠蛋白，与Hb（血红蛋白）的α/β亚基同源。Mb负责储氧和细胞内氧转运。","points":["Mb（肌红蛋白）=1条肽链+1个血红素。","153 aa，Mr（相对分子质量）≈16700。","珠蛋白与Hb（血红蛋白） α/β亚基同源。","功能：肌肉储氧/转运。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full4.jpg","imageExplain":"这张图在讲：Mb（肌红蛋白）存在于肌肉，由1条153 aa肽链+1个血红素组成，Mr（相对分子质量）≈16700；去掉血红素后的肽链称珠蛋白，与Hb（血红蛋白）的α/β亚基同源。Mb负责储氧和细胞内氧转运。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第4页","srcType":"老师PPT","role":"查阅"},{"i":32,"sec":"老师PPT逐页","title":"肌红蛋白的结构：珠蛋白折叠与血红素口袋","notes":"【图源】原书图。这是肌红蛋白的缎带模型。肌红蛋白是单体蛋白，一条约153个氨基酸的肽链折叠成8段α-螺旋（A—H），螺旋之间由短环连接，整体形成紧凑的球状“珠蛋白折叠”，图中没有β折叠。中央橙色的血红素辅基嵌在由疏水残基围成的口袋中，而不是露在表面；近端组氨酸His F8的咪唑氮从下方与Fe²⁺配位。疏水口袋可保护Fe²⁺不被氧化为Fe³⁺，并使O₂能可逆结合。肌红蛋白只有一个亚基、一个血红素、一个O₂结合位点，因此氧结合曲线是双曲线，没有协同性。","points":["肌红蛋白=单体+1个血红素+1个O₂位点","二级结构以8段α-螺旋为主，无β折叠","血红素在疏水口袋中，His F8配位Fe²⁺","单体单位点→无协同，氧合曲线为双曲线"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-mb-v2.png","imageExplain":"原书图4-3：Mb（肌红蛋白）由一条多肽链折叠成8段α螺旋的珠蛋白折叠，中央疏水口袋结合血红素；这是单体、单位点、无协同的结构基础。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_32","kind":"fill","q":"______=单体+1个血红素+1个O₂位点","a":"肌红蛋白","e":"PPT原文：肌红蛋白=单体+1个血红素+1个O₂位点。正确答案：肌红蛋白。","src":"PPT原文题"}},{"i":33,"sec":"老师PPT逐页","title":"辅基血红素","notes":"血红素=原卟啉IX+Fe。原卟啉IX由4个吡咯环通过甲叉桥连成平面大环；Fe通常六配位，4个N来自吡咯环，另两个配位位置在环上下。Fe²⁺为亚铁血红素，Fe³⁺为高铁血红素；只有Fe²⁺态Mb（肌红蛋白）能可逆结合O₂。","points":["血红素=原卟啉IX+Fe。","4个吡咯N配位Fe；上下各一个配位位点。","Fe²⁺可结合O₂；Fe³⁺不能。","Mb（肌红蛋白）疏水口袋保护Fe²⁺。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full6.jpg","imageExplain":"这张图在讲：血红素=原卟啉IX+Fe。原卟啉IX由4个吡咯环通过甲叉桥连成平面大环；Fe通常六配位，4个N来自吡咯环，另两个配位位置在环上下。Fe²⁺为亚铁血红素，Fe³⁺为高铁血红素；只有Fe²⁺态Mb（肌红蛋白）能可逆结合O₂。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第6页","srcType":"老师PPT","role":"查阅"},{"i":34,"sec":"老师PPT逐页","title":"血红素辅基：原卟啉IX螯合Fe²⁺","notes":"【图源】老师第6章PPT原页。血红素由原卟啉IX与Fe²⁺组成。原卟啉IX是四个吡咯环通过次甲基桥连成的平面共轭大环；环上两个丙酸根带负电、朝外起锚定作用，四个甲基和两个乙烯基疏水、朝向蛋白内部。Fe²⁺插入环中心时取代两个吡咯氮上的质子，释放2H⁺；Fe²⁺与四个吡咯氮配位，第5轴向位置由近端His F8占据，第6位留给O₂。只有Fe²⁺能可逆结合O₂，Fe³⁺不能，所以疏水口袋保护Fe²⁺很重要。","points":["血红素=原卟啉IX+Fe²⁺","四个吡咯环+次甲基桥，平面共轭","Fe²⁺与4个N配位，第5位His F8，第6位O₂","Fe²⁺可逆结合O₂；Fe³⁺不能"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full7.jpg","imageExplain":"这张图在讲：血红素由原卟啉IX与Fe²⁺组成。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红素=原卟啉IX+Fe²⁺；四个吡咯环+次甲基桥，平面共轭。","source":"老师第6章PPT 第7页","srcType":"老师PPT","role":"查阅"},{"i":35,"sec":"老师PPT逐页","title":"O2 与肌红蛋白的结合","notes":"Mb（肌红蛋白）中Fe第5配位键与近侧His F8的咪唑N结合；第6位在未结合O₂时为空，结合O₂时由O₂占据。远侧His E7在O₂一侧提供空间位阻，使CO亲和力降低。","points":["第5配体=近侧His F8。","第6配体=O₂（未结合时为空）。","远侧His E7提供空间位阻。","Fe³⁺不能结合O₂，H₂O可占第6位。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full8.jpg","imageExplain":"这张图在讲：Mb（肌红蛋白）中Fe第5配位键与近侧His F8的咪唑N结合；第6位在未结合O₂时为空，结合O₂时由O₂占据。远侧His E7在O₂一侧提供空间位阻，使CO亲和力降低。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第8页","srcType":"老师PPT","role":"查阅"},{"i":36,"sec":"老师PPT逐页","title":"氧合肌红蛋白中Fe的6个配体","notes":"Mb（肌红蛋白）血红素Fe²⁺为八面体配位：4个N来自卟啉环，第5个配体是近侧His F8的咪唑N，第6个配体是O₂；远侧His E7位于O₂一侧，提供空间位阻/稳定。","points":["Fe²⁺六配位：4个卟啉N。","第5配体=近侧His F8。","第6配体=O₂；远侧His E7辅助。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full9.jpg","imageExplain":"这张图在讲：Mb（肌红蛋白）血红素Fe²⁺为八面体配位：4个N来自卟啉环，第5个配体是近侧His F8的咪唑N，第6个配体是O₂。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Fe²⁺六配位：4个卟啉N。；第5配体=近侧His F8。。","source":"老师第6章PPT 第9页","srcType":"老师PPT","role":"查阅"},{"i":37,"sec":"老师PPT逐页","title":"CO 的毒性作用","notes":"CO与游离血红素Fe²⁺的亲和力比O₂高约25000倍；但在Mb（肌红蛋白）中，远侧His/空间位阻把CO优势降到约250倍，仍足以中毒。CO占据O₂位点，导致组织缺氧。","points":["游离血红素：CO亲和力约25000×O₂。","Mb（肌红蛋白）中：CO仅约250×O₂。","远侧His/空间位阻降低CO亲和力。","CO占位→组织缺氧。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full10.jpg","imageExplain":"这张图在讲：CO与游离血红素Fe²⁺的亲和力比O₂高约25000倍；但在Mb（肌红蛋白）中，远侧His/空间位阻把CO优势降到约250倍，仍足以中毒。CO占据O₂位点，导致组织缺氧。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第10页","srcType":"老师PPT","role":"查阅"},{"i":38,"sec":"老师PPT逐页","title":"O2和CO 与肌红蛋白血红","notes":"O₂与CO都能结合血红素Fe²⁺：O₂可逆结合，CO亲和力更高并占据O₂位点；游离血红素易氧化，Mb（肌红蛋白）疏水口袋保护Fe²⁺。","points":["游离血红素Fe²⁺容易被氧化；Mb（肌红蛋白）疏水口袋保护Fe²⁺。","O₂与Fe²⁺可逆结合；CO与Fe²⁺亲和力更高。","CO占据O₂位点，导致中毒。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full11.jpg","imageExplain":"这张图在讲：O₂与CO都能结合血红素Fe²⁺：O₂可逆结合，CO亲和力更高并占据O₂位点。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：游离血红素Fe²⁺容易被氧化；Mb（肌红蛋白）疏水口袋保护Fe²⁺。；O₂与Fe²⁺可逆结合；CO与Fe²⁺亲和力更高。。","source":"老师第6章PPT 第11页","srcType":"老师PPT","role":"查阅"},{"i":39,"sec":"老师PPT逐页","title":"疏水环境保护Fe²⁺不被氧化","notes":"游离血红素Fe²⁺容易被O₂氧化成Fe³⁺；Mb（肌红蛋白）把血红素包在疏水口袋中，减少水/氧化剂接触，保护Fe²⁺，使O₂可逆结合。","points":["游离血红素Fe²⁺易氧化。","Mb（肌红蛋白）疏水口袋保护Fe²⁺。","Fe³⁺不能可逆结合O₂。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full12.jpg","imageExplain":"这张图在讲：游离血红素Fe²⁺容易被O₂氧化成Fe³⁺；Mb（肌红蛋白）把血红素包在疏水口袋中，减少水/氧化剂接触，保护Fe²⁺，使O₂可逆结合。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第12页","srcType":"老师PPT","role":"查阅"},{"i":40,"sec":"老师PPT逐页","title":"肌红蛋白血红素","notes":"脱氧Mb（肌红蛋白）中Fe²⁺略向近侧His F8方向凸出；结合O₂后Fe被拉入卟啉环平面，牵动His F8/F螺旋。这个微小位移是Mb/Hb（血红蛋白）构象变化的起点。","points":["脱氧：Fe偏向近侧His。","氧合：Fe入卟啉环平面。","Fe位移牵动His F8/F螺旋。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full13.jpg","imageExplain":"这张图在讲：脱氧Mb（肌红蛋白）中Fe²⁺略向近侧His F8方向凸出；结合O₂后Fe被拉入卟啉环平面，牵动His F8/F螺旋。这个微小位移是Mb/Hb（血红蛋白）构象变化的起点。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第13页","srcType":"老师PPT","role":"查阅"},{"i":41,"sec":"老师PPT逐页","title":"肌红蛋白血红素Fe原子的位移","notes":"氧合时Fe²⁺被拉入卟啉环平面，牵动近侧His F8和F螺旋；脱氧时Fe略向近侧His方向凸出。这个位移是Mb（肌红蛋白）/Hb（血红蛋白）构象变化的起点。","points":["氧合：Fe入平面。","脱氧：Fe偏向近侧His。","Fe位移牵动His F8/F螺旋。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full14.jpg","imageExplain":"这张图在讲：氧合时Fe²⁺被拉入卟啉环平面，牵动近侧His F8和F螺旋。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：氧合：Fe入平面。；脱氧：Fe偏向近侧His。。","source":"老师第6章PPT 第14页","srcType":"老师PPT","role":"查阅"},{"i":42,"sec":"老师PPT逐页","title":"肌红蛋白结合氧的定量分析","notes":"Mb（肌红蛋白） + O₂ ⇌ MbO₂。解离常数 K=[Mb][O₂]/[MbO₂]；氧饱和度 Y=[MbO₂]/([Mb]+[MbO₂])。","points":["反应：Mb（肌红蛋白）+O₂⇌MbO₂。","K=[Mb（肌红蛋白）][O₂]/[MbO₂]。","Y=[MbO₂]/([Mb（肌红蛋白）]+[MbO₂])。","K越小，Mb（肌红蛋白）对O₂亲和力越高。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full15.jpg","imageExplain":"这张图从反应式出发定义K和Y：先看Mb（肌红蛋白）+O₂⇌MbO₂，再写K，最后写Y；目的是把“结合了多少氧”变成可测的Y。","source":"老师第6章PPT 第15页","srcType":"老师PPT","role":"查阅"},{"i":43,"sec":"老师PPT逐页","title":"肌红蛋白结合氧的定量分析","notes":"把K=[Mb（肌红蛋白）][O₂]/[MbO₂]代入Y，消去[MbO₂]，得 Y=[O₂]/(K+[O₂])。当[O₂]=K时，Y=0.5。","points":["由K表达式代入Y。","化简得Y=[O₂]/(K+[O₂])。","[O₂]=K时Y=0.5。","K是半饱和时的配体浓度（浓度单位）。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full16.jpg","imageExplain":"这张图是代数化简：先把K代入Y，消去[MbO₂]，得到Y=[O₂]/(K+[O₂])；看图抓住“Y只由[O₂]和K决定”。","source":"老师第6章PPT 第16页","srcType":"老师PPT","role":"查阅"},{"i":44,"sec":"老师PPT逐页","title":"肌红蛋白结合氧的定量分析","notes":"Henry定律：[O₂]=A·p(O₂)。代入Y=[O₂]/(K+[O₂])，得 Y=p(O₂)/(K/A+p(O₂))。令P50（半饱和氧分压）=K/A，则 Y=p(O₂)/(P50+p(O₂))。","points":["Henry定律：[O₂]=A·p(O₂)。","代入后Y=p(O₂)/(K/A+p(O₂))。","令P50（半饱和氧分压）=K/A，则Y=p(O₂)/(P50+p(O₂))。","Y=0.5时p(O₂)=P50（半饱和氧分压）；P50越小亲和力越高。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full17.jpg","imageExplain":"这张图用Henry定律把浓度[O₂]换成可测的氧分压p(O₂)：Y=p(O₂)/(P50（半饱和氧分压）+p(O₂))；P50越小，Mb（肌红蛋白）亲和力越高。","source":"老师第6章PPT 第17页","srcType":"老师PPT","role":"查阅"},{"i":45,"sec":"老师PPT逐页","title":"肌红蛋白的氧结合曲线","notes":"【图源】原书图。肌红蛋白的氧结合曲线 实验中 p (O2) 可以测得，氧分压常用Torr 为 单位。Y 值可用分光光度法测定，因为肌红蛋白 结合了O2 时会引起吸收光谱的改变。Y 对 p (O2) 作图所得的曲线称为氧结合曲线。 1 Torr = 133 Pa = 1 mmHg（毫米汞柱）","points":["肌红蛋白的氧结合曲线 实验中 p (O2) 可以测得，氧分压常用Torr 为 单位","Y 值可用分光光度法测定，因为肌红蛋白 结合了O2 时会引起吸收光谱的改变","Y 对 p (O2) 作图所得的曲线称为氧结合曲线"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"原书图4-4：Mb（肌红蛋白）的氧合曲线是双曲线，低pO₂迅速饱和；Y=0.5时P50（半饱和氧分压）≈2 torr，说明Mb亲和力高、适合储氧。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_45","kind":"fill","q":"______的氧结合曲线 实验中 p (O2) 可以测得，氧分压常用Torr 为 单位","a":"肌红蛋白","e":"PPT原文：肌红蛋白的氧结合曲线 实验中 p (O2) 可以测得，氧分压常用Torr 为 单位。正确答案：肌红蛋白。","src":"PPT原文题"}},{"i":46,"sec":"老师PPT逐页","title":"肌红蛋白的氧结合曲线：双曲线与P50（半饱和氧分压）","notes":"【图源】原书图。纵轴是氧分数饱和度Y，横轴是氧分压p(O₂)。肌红蛋白的曲线是双曲线：低氧时分压稍升高，Y就迅速上升，说明亲和力高，适合肌肉储氧；随后很快趋于平台。Y=0.5时对应的p(O₂)称为K′或P50（半饱和氧分压），是亲和力的指标：K′越小，亲和力越高。方程Y=p(O₂)/[p(O₂)+K′]是单位点、无协同结合的质量作用表达式；肌红蛋白只有一个O₂位点，所以没有S形协同曲线。","points":["纵轴Y=氧饱和度，横轴p(O₂)","双曲线：低氧迅速上升，高氧饱和","Y=0.5时的p(O₂)=K′/P50（半饱和氧分压），越小亲和力越高","单位点无协同→双曲线，不是S形"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"原书图4-4：Mb（肌红蛋白）的氧合曲线是双曲线，低pO₂迅速饱和；Y=0.5时P50（半饱和氧分压）≈2 torr，说明Mb亲和力高、适合储氧。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_46","kind":"fill","q":"______的曲线是双曲线：低氧时分压稍升高，Y就迅速上升，说明亲和力高，适合肌肉储氧","a":"肌红蛋白","e":"PPT原文：肌红蛋白的曲线是双曲线：低氧时分压稍升高，Y就迅速上升，说明亲和力高，适合肌肉储氧。正确答案：肌红蛋白。","src":"PPT原文题"}},{"i":47,"sec":"老师PPT逐页","title":"Hill 作图","notes":"Hill作图：横轴 log[p(O₂)]，纵轴 log[Y/(1−Y)]。Mb（肌红蛋白）为单体单位点：斜率=1，无协同；直线与y=0交点给log P50（半饱和氧分压）。","points":["Hill变换：log[Y/(1−Y)]对log pO₂作图。","斜率=nH（Hill系数）。","Mb（肌红蛋白） nH（Hill系数）=1，无协同。","y=0处横坐标=log P50（半饱和氧分压）。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full20.jpg","imageExplain":"读图顺序：先看标题「Hill 作图」，再在图中找：这张Hill图把双曲线变成直线：看斜率判断协同性，斜率1=无协同；直线与y=0交点给P50（半饱和氧分压）。；把图中结构/曲线与要点对应；本页结论：Hill作图：横轴 log[p(O₂)]，纵轴 log[Y/(1−Y)]。","source":"老师第6章PPT 第20页","srcType":"老师PPT","role":"查阅"},{"i":48,"sec":"老师PPT逐页","title":"Hill 作图","notes":"Hill系数 nH（Hill系数） 是Hill图斜率：nH=1无协同；nH>1正协同；nH<1负协同。Mb（肌红蛋白） nH=1；Hb（血红蛋白） nH≈2.8。","points":["nH（Hill系数）=Hill图斜率。","nH（Hill系数）=1无协同。","nH（Hill系数）>1正协同；nH<1负协同。","Mb（肌红蛋白） nH（Hill系数）=1；Hb（血红蛋白） nH≈2.8。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full21.jpg","imageExplain":"读图顺序：先看标题「Hill 作图」，再在图中找：这张图用斜率读协同性：Mb（肌红蛋白）斜率1；Hb（血红蛋白）斜率>1说明正协同，所以曲线S形。；把图中结构/曲线与要点对应；本页结论：Hill系数 nH（Hill系数） 是Hill图斜率：nH=1无协同。","source":"老师第6章PPT 第21页","srcType":"老师PPT","role":"查阅"},{"i":49,"sec":"老师PPT逐页","title":"肌红蛋白氧结合的Hill图","notes":"【图源】老师第6章PPT原页。纵轴log(Y/(1−Y))、横轴log pO2（氧分压），红色直线斜率=1.0；直线与Y=0水平线交点横坐标为log P50（半饱和氧分压），代表半饱和氧分压。斜率1说明肌红蛋白只有一个O2结合位点、无协同性，结合服从简单双分子平衡。","points":["纵轴log(Y/(1-Y))，横轴log pO2（氧分压）","斜率=1.0=nH（Hill系数）","无协同","y=0处横坐标=logP50"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full22.jpg","imageExplain":"这张Hill图看Mb（肌红蛋白）的协同性：横轴log pO₂、纵轴log(Y/(1−Y))；斜率=1，说明单位点、无协同；直线与y=0交点给log P50（半饱和氧分压）。","source":"老师第6章PPT 第22页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_49","kind":"fill","q":"斜率1说明______只有一个O2结合位点、无协同性，结合服从简单双分子平衡","a":"肌红蛋白","e":"PPT原文：斜率1说明肌红蛋白只有一个O2结合位点、无协同性，结合服从简单双分子平衡。正确答案：肌红蛋白。","src":"PPT原文题"}},{"i":50,"sec":"老师PPT逐页","title":"肌红蛋白P50（半饱和氧分压）与储氧功能","notes":"【图源】老师第6章PPT原页。肌红 线粒体中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些。肌红蛋白的P 50 为2 torr ，所以 在大多数情况下，肌红蛋白是高度氧合的，是氧的 贮存库。如果由于肌肉收缩使线粒体中氧含量下降， 它就可以立即供应氧。","points":["肌红 线粒体中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些","肌红蛋白的P 50 为2 torr ，所以 在大多数情况下，肌红蛋白是高度氧合的，是氧的 贮存库","如果由于肌肉收缩使线粒体中氧含量下降， 它就可以立即供应氧"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full23.jpg","imageExplain":"这张图在讲：肌红 线粒体中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌红 线粒体中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些；肌红蛋白的P 50 为2 torr ，所以 在大多数情况下，肌红蛋白是高度氧合的，是氧的 贮存库。","source":"老师第6章PPT 第23页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_50","kind":"fill","q":"肌红 ______中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些","a":"线粒体","e":"PPT原文：肌红 线粒体中氧浓度为0 ～10 torr ，静脉血氧浓度为 15 torr 或更高些。正确答案：线粒体。","src":"PPT原文题"}},{"i":51,"sec":"老师PPT逐页","title":"肌红蛋白辅助细胞内氧转运","notes":"【图源】老师第6章PPT原页。肌红 肌红蛋白也有利于细胞内氧从细胞的内表面向线 粒体转运，因为这种运转是顺浓度梯度的，细胞内 表面的氧浓度约为10 torr （肌红蛋白的氧饱和度约 为80% ），而线粒体内的氧浓度约为1 torr （肌红 蛋白的氧饱和度约为25% ），肌红蛋白可以从细胞 内表面结合氧，而运到线粒体中释放氧。","points":["Mb（肌红蛋白）在细胞内促进O₂从膜向线粒体扩散。","Mb（肌红蛋白） P50（半饱和氧分压）约2 torr，高亲和，肌肉内多处于高饱和。","线粒体低氧时Mb（肌红蛋白）释放O₂。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full24.jpg","imageExplain":"这张图在讲：肌红 肌红蛋白也有利于细胞内氧从细胞的内表面向线 粒体转运，因为这种运转是顺浓度梯度的，细胞内 表面的氧浓度约为10 torr （肌红蛋白的氧饱和度约 为80% ），而线粒体内的氧浓度约为1 torr （肌红 蛋白的氧饱和度约为25% ），肌红蛋白可以从细胞 内表面结合氧，而运到线粒体中释放氧。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Mb（肌红蛋白）在细胞内促进O₂从膜向线粒体扩散。；Mb P50（半饱和氧分压）约2 torr，高亲和，肌肉内多处于高饱和。。","source":"老师第6章PPT 第24页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_51","kind":"fill","q":"Mb（肌红蛋白）在细胞内促进O₂从膜向______扩散。","a":"线粒体","e":"PPT原文：Mb（肌红蛋白）在细胞内促进O₂从膜向线粒体扩散。。正确答案：线粒体。","src":"PPT原文题"}},{"i":52,"sec":"老师PPT逐页","title":"二、血红蛋白的结构与功能（章节标题）","notes":"【图源】老师第6章PPT原页。本页仅为“二、血红蛋白（hemoglobin，Hb（血红蛋白））的结构与功能”的章节标题，没有结构图或数据；后续页进入血红蛋白四聚体结构。","points":["章节标题页"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full25.jpg","imageExplain":"读图顺序：先看标题「二、血红蛋白的结构与功能（章节标题）」，再在图中找：这张图在讲：后续页进入血红蛋白四聚体结构。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：章节标题页。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第25页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_52","kind":"fill","q":"后续页进入______四聚体结构","a":"血红蛋白","e":"PPT原文：后续页进入血红蛋白四聚体结构。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":53,"sec":"老师PPT逐页","title":"血红蛋白","notes":"Hb（血红蛋白）存在于红细胞，负责运输O₂：肺中结合、组织中释放。Hb为α₂β₂四聚体，4个血红素/4个O₂位点；受H⁺、CO₂、BPG（2,3-二磷酸甘油酸）别构调节。","points":["Hb（血红蛋白）=α₂β₂四聚体，4个血红素。","肺结合O₂，组织释放O₂。","H⁺/CO₂/BPG（2,3-二磷酸甘油酸）调节亲和力。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full26.jpg","imageExplain":"这张图在讲：Hb（血红蛋白）存在于红细胞，负责运输O₂：肺中结合、组织中释放。Hb为α₂β₂四聚体，4个血红素/4个O₂位点；受H⁺、CO₂、BPG（2,3-二磷酸甘油酸）别构调节。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第26页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_53","kind":"fill","q":"受H⁺、CO₂、BPG（2,3-二磷酸甘油酸）______调节","a":"别构","e":"PPT原文：受H⁺、CO₂、BPG（2,3-二磷酸甘油酸）别构调节。正确答案：别构。","src":"PPT原文题"}},{"i":54,"sec":"老师PPT逐页","title":"人体内有正常功能的血红蛋白","notes":"人不同发育阶段Hb（血红蛋白）亚基组成不同：胚胎、胎儿HbF（α₂γ₂）、成人HbA（α₂β₂）。HbF对O₂亲和力高于HbA，利于胎儿从母体取氧。","points":["胚胎Hb（血红蛋白）→胎儿HbF（胎儿血红蛋白）→成人HbA（成人血红蛋白）。","HbF（胎儿血红蛋白）=α₂γ₂；HbA（成人血红蛋白）=α₂β₂。","HbF（胎儿血红蛋白）亲和力高，利于胎儿取氧。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full27.jpg","imageExplain":"这张图在讲：人不同发育阶段Hb（血红蛋白）亚基组成不同：胚胎、胎儿HbF（α₂γ₂）、成人HbA（α₂β₂）。HbF对O₂亲和力高于HbA，利于胎儿从母体取氧。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第27页","srcType":"老师PPT","role":"查阅"},{"i":55,"sec":"老师PPT逐页","title":"血红蛋白的氨基酸组成","notes":"【图源】老师第6章PPT原页。血红蛋白的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白。同一类型不同希腊字母代表的链有个 别氨基酸残基不同。","points":["血红蛋白的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白","同一类型不同希腊字母代表的链有个 别氨基酸残基不同"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full28.jpg","imageExplain":"这张图在讲：血红蛋白的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白；同一类型不同希腊字母代表的链有个 别氨基酸残基不同。","source":"老师第6章PPT 第28页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_55","kind":"fill","q":"______的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白","a":"血红蛋白","e":"PPT原文：血红蛋白的氨基酸组成 α 链或α 样链由141 个氨基酸残基组成，β 链 或β 样链由146 个氨基酸残基组成，而肌红蛋 白的肽链由153 个氨基酸残基组成，它们都叫 珠蛋白。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":56,"sec":"老师PPT逐页","title":"血红蛋白的四级结构：α₂β₂与四个血红素","notes":"【图源】老师第6章PPT原页。血红蛋白是α₂β₂四聚体：2条α链（141 aa）和2条β链（146 aa），共4个血红素、4个O₂结合位点。每个亚基的三级结构类似肌红蛋白，都是珠蛋白折叠加一个疏水血红素口袋；但四个亚基装配后，α1β1和α2β2形成紧密二聚体，α1β2/α2β1界面可相对滑动。四个血红素相距较远，不能直接传递配体，只能通过Fe—His F8—F螺旋—亚基界面的构象变化间接“通信”，这是协同效应和S形曲线的结构基础。","points":["血红蛋白=α₂β₂四聚体，4个血红素/4个O₂位点","每个亚基类似肌红蛋白的三级结构","α1β1、α2β2紧密；α1β2/α2β1可滑动","血红素间不能直接传递，靠构象变化协同"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full29.jpg","imageExplain":"这张图在讲：血红蛋白是α₂β₂四聚体：2条α链（141 aa）和2条β链（146 aa），共4个血红素、4个O₂结合位点。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白=α₂β₂四聚体，4个血红素/4个O₂位点；每个亚基类似肌红蛋白的三级结构。","source":"老师第6章PPT 第29页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_56","kind":"fill","q":"______=α₂β₂四聚体，4个血红素/4个O₂位点","a":"血红蛋白","e":"PPT原文：血红蛋白=α₂β₂四聚体，4个血红素/4个O₂位点。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":57,"sec":"老师PPT逐页","title":"Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白）","notes":"【图源】原书图。Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白） 链构象的相似性 血红蛋白α 链、β 链及肌红蛋白链的三级结构 非常相似，但这三种肽链的氨基酸序列有很大不 同，141 个氨基酸残基位置中只有27 个位置的残 基在这三种肽链中是相同的。 Mb Hbα Hbβ","points":["Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白） 链构象的相似性 血红蛋白α 链、β 链及肌红蛋白链的三级结构 非常相似，但这三种肽链的氨基酸序列有很大不 同，141 个氨基酸残基位置中只有27 个位置的残 基在这三种肽链中是相同的","Mb（肌红蛋白） Hb（血红蛋白）α Hbβ"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-hb-v2.png","imageExplain":"读图顺序：先看标题「Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白）」，再在图中找：原书图4-6：Mb与Hb的α/β亚基三级结构相似，都是珠蛋白折叠+血红素口袋；Hb靠四聚体组装产生协同。；把图中结构/曲线与要点对应；本页结论：【图源】原书图。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_57","kind":"fill","q":"Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白） 链构象的相似性 ______α 链、β 链及肌红蛋白链的三级结构 非常相似，但这三种肽链的氨基酸序列有很大不 同，141 个氨基酸残基位置中只有27 个位置的残 基在这三种肽链中是相同的","a":"血红蛋白","e":"PPT原文：Hb（血红蛋白） 的α 链、β 链和Mb（肌红蛋白） 链构象的相似性 血红蛋白α 链、β 链及肌红蛋白链的三级结构 非常相似，但这三种肽链的氨基酸序列有很大不 同，141 个氨基酸残基位置中只有27 个位置的残 基在这三种肽链中是相同的。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":58,"sec":"老师PPT逐页","title":"不同物种血红蛋白氨基酸","notes":"【图源】老师第6章PPT原页。不同物种血红蛋白氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基。 血红蛋白内部的非极性残基可以换成另一种非 极性残基而功能不变。","points":["不同物种血红蛋白氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基","血红蛋白内部的非极性残基可以换成另一种非 极性残基而功能不变"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full31.jpg","imageExplain":"这张图在讲：不同物种血红蛋白氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：不同物种血红蛋白氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基；血红蛋白内部的非极性残基可以换成另一种非 极性残基而功能不变。","source":"老师第6章PPT 第31页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_58","kind":"fill","q":"不同物种______氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基","a":"血红蛋白","e":"PPT原文：不同物种血红蛋白氨基酸 序列的比较 比较了多种（从七腮鳗到人）不同的血红蛋白 的氨基酸序列，证明序列中有9 个位置的残基是 所有研究过的血红蛋白所共有的，这些称为高度 保守的残基。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":59,"sec":"老师PPT逐页","title":"血红蛋白氧合时亚基的移动","notes":"【图源】老师第6章PPT原页。血红蛋白氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触； 另一类是α1β2 接触和α2β1 接触，这类接触称为滑 动接触。氧合时，每个αβ 二聚体半分子作为一个 刚体移动，这两个二聚体彼此滑动。我们将其中一 个二聚体看作不动，另一个二聚体将绕一个设想的 偏心轴旋转15° ，并平移0.08nm 。","points":["血红蛋白氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触","另一类是α1β2 接触和α2β1 接触，这类接触称为滑 动接触","氧合时，每个αβ 二聚体半分子作为一个 刚体移动，这两个二聚体彼此滑动"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full32.jpg","imageExplain":"这张图在讲：血红蛋白氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触；另一类是α1β2 接触和α2β1 接触，这类接触称为滑 动接触。","source":"老师第6章PPT 第32页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_59","kind":"fill","q":"______氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触","a":"血红蛋白","e":"PPT原文：血红蛋白氧合时亚基的移动 血红蛋白分子中，αβ 亚基的接触有两类，一类 是α1β1 接触和α2β2 接触，这类接触称为装配接触。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":60,"sec":"老师PPT逐页","title":"血红蛋白氧合时的T→R构象转变","notes":"【图源】原书图。去氧血红蛋白处于T态（低亲和力），氧合后转为R态（高亲和力）。O₂结合到血红素后，Fe²⁺被拉入卟啉环平面，牵动近端His F8和F螺旋，通过α1β2/α2β1界面放大：一个αβ二聚体相对另一个二聚体绕中心轴旋转约15°。旋转使T态盐桥断裂、中央空腔缩小，BPG（2,3-二磷酸甘油酸）被挤出，四聚体转向R态。四个亚基的三级结构变化不大，主要是四级结构（亚基相对位置）重排；这就是正协同效应和S形曲线的结构来源。","points":["T态=去氧低亲和，R态=氧合高亲和","O₂→Fe²⁺入平面→His F8/F螺旋移动","α1β1相对α2β2旋转约15°","T态盐桥断裂、空腔缩小、BPG（2,3-二磷酸甘油酸）释放","协同来自四级结构重排"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-tr.png","imageExplain":"原书图4-9：Hb（血红蛋白）从T态到R态时，αβ二聚体相对旋转约15°；先看O₂结合Fe，再看His F8/F螺旋和亚基界面，最后看盐桥断裂。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_60","kind":"fill","q":"去氧______处于T态（低亲和力），氧合后转为R态（高亲和力）","a":"血红蛋白","e":"PPT原文：去氧血红蛋白处于T态（低亲和力），氧合后转为R态（高亲和力）。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":61,"sec":"老师PPT逐页","title":"去氧/氧合血红蛋白中铁原子的移动","notes":"【图源】老师第6章PPT原页。血 在去氧血红蛋白中，铁原子向近侧His 方向凸 起约0.06nm 。氧合时，铁原子的体积缩小，向卟 啉环平面靠近约0.039nm ，并牵拉近侧His 往血 红素平面移动，这些移动，传递到亚基的界面，使 得亚基间的相互位置发生变化。","points":["血 在去氧血红蛋白中，铁原子向近侧His 方向凸 起约0.06nm","氧合时，铁原子的体积缩小，向卟 啉环平面靠近约0.039nm ，并牵拉近侧His 往血 红素平面移动，这些移动，传递到亚基的界面，使 得亚基间的相互位置发生变化"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full34.jpg","imageExplain":"这张图在讲：血 在去氧血红蛋白中，铁原子向近侧His 方向凸 起约0.06nm。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血 在去氧血红蛋白中，铁原子向近侧His 方向凸 起约0.06nm；氧合时，铁原子的体积缩小，向卟 啉环平面靠近约0.039nm ，并牵拉近侧His 往血 红素平面移动，这些移动，传递到亚基的界面，使 得亚基间的相互位置发生变化。","source":"老师第6章PPT 第34页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_61","kind":"fill","q":"血 在去氧______中，铁原子向近侧His 方向凸 起约0.06nm","a":"血红蛋白","e":"PPT原文：血 在去氧血红蛋白中，铁原子向近侧His 方向凸 起约0.06nm。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":62,"sec":"老师PPT逐页","title":"血红蛋白氧合时铁原子的移动","notes":"Hb（血红蛋白）氧合时Fe²⁺进入卟啉环平面，牵动His F8/F螺旋；这一微小移动经亚基界面放大，导致T→R。","points":["Fe入平面→His F8/F螺旋移动。","界面放大→T→R。","协同来自四级结构。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full35.jpg","imageExplain":"这张图在讲：Hb（血红蛋白）氧合时Fe²⁺进入卟啉环平面，牵动His F8/F螺旋。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Fe入平面→His F8/F螺旋移动。；界面放大→T→R。。","source":"老师第6章PPT 第35页","srcType":"老师PPT","role":"查阅"},{"i":63,"sec":"老师PPT逐页","title":"血红蛋白的两种构象态","notes":"【图源】老师第6章PPT原页。血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）。O2 对R 态的亲和力明显地高于 对T 态的亲和力，并且O2 的结合更稳定了R 态。 缺氧时T 态更加稳定，因此T 态是去氧血红蛋白的 主要构象，R 态是氧合血红蛋白的主要构象。T 态 血红蛋白结合O2 后转变成R 态，并使得分子内一些 盐桥断裂。","points":["血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）","O2 对R 态的亲和力明显地高于 对T 态的亲和力，并且O2 的结合更稳定了R 态","缺氧时T 态更加稳定，因此T 态是去氧血红蛋白的 主要构象，R 态是氧合血红蛋白的主要构象"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full36.jpg","imageExplain":"这张图在讲：血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）；O2 对R 态的亲和力明显地高于 对T 态的亲和力，并且O2 的结合更稳定了R 态。","source":"老师第6章PPT 第36页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_63","kind":"fill","q":"______的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）","a":"血红蛋白","e":"PPT原文：血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":64,"sec":"老师PPT逐页","title":"去氧血红蛋白的盐桥网络","notes":"【图源】老师第6章PPT原页。图示去氧血红蛋白T态四亚基（β2、α1、α2、β1），标出Lys40、His146、Asp94、Arg141、Asp126等残基，并用彩色连线表示亚基间盐桥。去氧时这些离子键约束亚基，稳定T态（低氧亲和力）；氧合转R态时盐桥断裂。","points":["T态盐桥网络","βHis146/αLys40","βAsp94/αArg141","稳定低亲和力T态"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full37.jpg","imageExplain":"这张图在讲：图示去氧血红蛋白T态四亚基（β2、α1、α2、β1），标出Lys40、His146、Asp94、Arg141、Asp126等残基，并用彩色连线表示亚基间盐桥。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：T态盐桥网络；βHis146/αLys40。","source":"老师第6章PPT 第37页","srcType":"老师PPT","role":"查阅"},{"i":65,"sec":"老师PPT逐页","title":"血红蛋白的别构效应","notes":"【图源】老师第6章PPT原页。血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质。血红蛋白的氧合具有 正协同同促效应，即一个O2 的结合促进同一分子 其它亚基与O2 的结合。具有这种性质的蛋白质称 为别构蛋白（其它蛋白质也有负协同效应的）。","points":["血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质","血红蛋白的氧合具有 正协同同促效应，即一个O2 的结合促进同一分子 其它亚基与O2 的结合","具有这种性质的蛋白质称 为别构蛋白（其它蛋白质也有负协同效应的）"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full38.jpg","imageExplain":"这张图在讲：血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质；血红蛋白的氧合具有 正协同同促效应，即一个O2 的结合促进同一分子 其它亚基与O2 的结合。","source":"老师第6章PPT 第38页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_65","kind":"fill","q":"______的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质","a":"血红蛋白","e":"PPT原文：血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":66,"sec":"老师PPT逐页","title":"血红蛋白的协同性氧结合","notes":"Hb（血红蛋白）有4个O₂位点，协同结合可用Hill方程描述：Y=p(O₂)ⁿ/(P50（半饱和氧分压）ⁿ+p(O₂)ⁿ)，n≈2.8。n=1无协同；n=4完全协同。","points":["Hb（血红蛋白）四聚体有4个O₂位点。","Hill方程：Y=pO₂ⁿ/(P50（半饱和氧分压）ⁿ+pO₂ⁿ)。","实际n≈2.8，正协同但不完全。","n越大曲线越陡。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full39.jpg","imageExplain":"这张图讲Hb（血红蛋白）的S形氧合曲线：横轴pO₂、纵轴Y；一个O₂结合促进后续结合，所以曲线中段陡；nH（Hill系数）>1表示正协同。","source":"老师第6章PPT 第39页","srcType":"老师PPT","role":"查阅"},{"i":67,"sec":"老师PPT逐页","title":"血红蛋白与肌红蛋白","notes":"Mb（肌红蛋白）是单体、单位点、双曲线，P50（半饱和氧分压）≈2 torr，适合储氧；Hb（血红蛋白）是四聚体、S形、P50≈26 torr，适合运输/卸氧。","points":["Mb（肌红蛋白）双曲线，Hb（血红蛋白） S形。","Mb（肌红蛋白）高亲和，Hb（血红蛋白）低亲和。","Hb（血红蛋白）有协同/别构。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full40.jpg","imageExplain":"这张图在讲：Mb（肌红蛋白）是单体、单位点、双曲线，P50（半饱和氧分压）≈2 torr，适合储氧。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Mb双曲线，Hb（血红蛋白） S形。；Mb高亲和，Hb低亲和。。","source":"老师第6章PPT 第40页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_67","kind":"fill","q":"Hb（血红蛋白）有协同/______。","a":"别构","e":"PPT原文：Hb（血红蛋白）有协同/别构。。正确答案：别构。","src":"PPT原文题"}},{"i":68,"sec":"老师PPT逐页","title":"血红蛋白的实际氧合曲线与Hill系数","notes":"【图源】老师第6章PPT原页。纵轴Y是血红蛋白氧饱和度（0—1），横轴是氧分压pO₂。红色曲线n=4.0是按四个亚基完全协同推导的理论曲线，最陡；蓝色曲线n=2.8是实际氧合曲线，仍有S形但更平缓，说明真实血红蛋白的协同不完全，存在结合1—3个O₂的中间态；紫色n=1.0是无协同的双曲线（类似肌红蛋白）。三条曲线在Y=0.5处交于同一点，对应P50（半饱和氧分压）≈26 torr。Hill系数越大，曲线越陡、协同越强；S形使血红蛋白在肺高氧区易饱和、在组织低氧区易卸载氧。","points":["纵轴Y=氧饱和度，横轴pO₂","n=4.0理论曲线最陡；n=2.8实际曲线较平缓","n=1.0无协同，双曲线","三线交于Y=0.5，P50（半饱和氧分压）≈26 torr","S形=正协同，利肺装载/组织卸氧"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full41.jpg","imageExplain":"这张图比较Mb（n=1，双曲线）和Hb（n≈2.8，S形）。先看曲线形状，再看Y=0.5对应P50（半饱和氧分压）：Mb≈2 torr，Hb≈26 torr。","source":"老师第6章PPT 第41页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_68","kind":"fill","q":"纵轴Y是______氧饱和度（0—1），横轴是氧分压pO₂","a":"血红蛋白","e":"PPT原文：纵轴Y是血红蛋白氧饱和度（0—1），横轴是氧分压pO₂。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":69,"sec":"老师PPT逐页","title":"血红蛋白推导氧合曲线","notes":"【图源】老师第6章PPT原页。血红蛋白推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用。实际测定的 n=2.8 ，若n=1 ，则无协同作用，若n >1 则有正协 同作用。对于血红蛋白来说，当 n=4 时正协同作用 最大，即当1 个O2 与1 个亚基结合后，另外3 个亚 基也同时与O2 结合。实际情况是n=2.8 。这 样，Hb（血红蛋白） 对第4 个O2 的亲和力约为与第1 个O2 亲 和力的300 倍。","points":["血红蛋白推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用","实际测定的 n=2.8 ，若n=1 ，则无协同作用，若n >1 则有正协 同作用","对于血红蛋白来说，当 n=4 时正协同作用 最大，即当1 个O2 与1 个亚基结合后，另外3 个亚 基也同时与O2 结合"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full42.jpg","imageExplain":"这张图在讲：血红蛋白推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用；实际测定的 n=2.8 ，若n=1 ，则无协同作用，若n >1 则有正协 同作用。","source":"老师第6章PPT 第42页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_69","kind":"fill","q":"______推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用","a":"血红蛋白","e":"PPT原文：血红蛋白推导氧合曲线 误差的原因 血红蛋白结合O2 并不是“全或无”的，各个亚 基结合O2 是依次进行的，并且前面亚基结合了O2 对后面亚基与O2 的结合有促进作用。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":70,"sec":"老师PPT逐页","title":"血红蛋白运输氧的效率","notes":"【图源】老师第6章PPT原页。血红蛋白运输氧的效率 在肺泡中，氧分压为100 torr ，工作肌肉的毛 细血管中约为20 torr ，血红蛋白在肺泡中Y 是 0.97 ，在肌肉毛细血管中Y 是0.25 ，释放的O2 是 两个Y 值之差，即ΔY=0.72 。这个差值越大，运 输O2 的效率就越高。肌红蛋白不能担当此项工作。","points":["血红蛋白运输氧的效率 在肺泡中，氧分压为100 torr ，工作肌肉的毛 细血管中约为20 torr ，血红蛋白在肺泡中Y 是 0.97 ，在肌肉毛细血管中Y 是0.25 ，释放的O2 是 两个Y 值之差，即ΔY=0.72","这个差值越大，运 输O2 的效率就越高","肌红蛋白不能担当此项工作"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full43.jpg","imageExplain":"读图顺序：先看标题「血红蛋白运输氧的效率」，再在图中找：这张图讲Hb（血红蛋白）在肺和组织之间怎么“装氧/卸氧”：肺pO₂高Y高，组织pO₂低Y低；两者Y差就是运输效率。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第43页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_70","kind":"fill","q":"______运输氧的效率 在肺泡中，氧分压为100 torr ，工作肌肉的毛 细血管中约为20 torr ，血红蛋白在肺泡中Y 是 0.97 ，在肌肉毛细血管中Y 是0.25 ，释放的O2 是 两个Y 值之差，即ΔY=0.72","a":"血红蛋白","e":"PPT原文：血红蛋白运输氧的效率 在肺泡中，氧分压为100 torr ，工作肌肉的毛 细血管中约为20 torr ，血红蛋白在肺泡中Y 是 0.97 ，在肌肉毛细血管中Y 是0.25 ，释放的O2 是 两个Y 值之差，即ΔY=0.72。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":71,"sec":"老师PPT逐页","title":"血红蛋白别构的异种效应","notes":"【图源】老师第6章PPT原页。血红蛋白别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG（2,3-二磷酸甘油酸） ）等。虽然它们 在蛋白质分子上的结合部位离血红素很远，但 这些分子极大地影响Hb（血红蛋白） 的氧合性质，这是别 构效应中的异种效应。","points":["血红蛋白别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG（2,3-二磷酸甘油酸） ）等","虽然它们 在蛋白质分子上的结合部位离血红素很远，但 这些分子极大地影响Hb（血红蛋白） 的氧合性质，这是别 构效应中的异种效应"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full44.jpg","imageExplain":"这张图在讲：血红蛋白别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG（2,3-二磷酸甘油酸） ）等。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：血红蛋白别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG ）等；虽然它们 在蛋白质分子上的结合部位离血红素很远，但 这些分子极大地影响Hb（血红蛋白） 的氧合性质，这是别 构效应中的异种效应。","source":"老师第6章PPT 第44页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_71","kind":"fill","q":"______别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG（2,3-二磷酸甘油酸） ）等","a":"血红蛋白","e":"PPT原文：血红蛋白别构的异种效应 血红蛋白与O2 的结合受其它分子的调节， 如H+ 、CO2 和2,3- 二磷酸甘油酸（2,3- bisphosphate glycerate ，BPG（2,3-二磷酸甘油酸） ）等。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":72,"sec":"老师PPT逐页","title":"2,3- 二磷酸甘油酸","notes":"BPG（2,3-二磷酸甘油酸）是红细胞内小分子，带负电，结合Hb（血红蛋白）两条β链之间的中央空腔，稳定T态，降低O₂亲和力。","points":["BPG（2,3-二磷酸甘油酸）结合β链中央空腔。","稳定T态，曲线右移。","高原/贫血BPG（2,3-二磷酸甘油酸）升高，利于卸氧。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full45.jpg","imageExplain":"这张图在讲：BPG（2,3-二磷酸甘油酸）是红细胞内小分子，带负电，结合Hb（血红蛋白）两条β链之间的中央空腔，稳定T态，降低O₂亲和力。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：BPG结合β链中央空腔。；稳定T态，曲线右移。。","source":"老师第6章PPT 第45页","srcType":"老师PPT","role":"查阅"},{"i":73,"sec":"老师PPT逐页","title":"Bohr 效应","notes":"【图源】老师第6章PPT原页。Bohr 效应 组织中代谢作用产生H+ 和CO2 ，代谢越旺 盛的组织，需要的O2 越多，产生的H+ 和CO2 也越多。CO2 在体内被水合成碳酸。 CO2 水合的结果，使组织中pH 下降，即 [H+] 上升。 O2 与血红蛋白的结合受pH 和 CO2 浓度的影响。去氧血红蛋白对H+ 的亲和 力比氧合血红蛋白大。因此，增加H+ 浓度将 促进O2 的释放。 HbO2（氧合血红蛋白） ＋H+ HbH（HbH四聚体）+ ＋O2","points":["Bohr 效应 组织中代谢作用产生H+ 和CO2 ，代谢越旺 盛的组织，需要的O2 越多，产生的H+ 和CO2 也越多","CO2 在体内被水合成碳酸","CO2 水合的结果，使组织中pH 下降，即 [H+] 上升"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full46.jpg","imageExplain":"读图顺序：先看标题「Bohr 效应」，再在图中找：这张图讲pH/CO₂对Hb（血红蛋白）曲线的影响：pH降低或CO₂升高稳定T态，曲线右移，P50（半饱和氧分压）增大，组织更容易卸氧。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第46页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_73","kind":"fill","q":"Bohr 效应 组织中______作用产生H+ 和CO2 ，代谢越旺 盛的组织，需要的O2 越多，产生的H+ 和CO2 也越多","a":"代谢","e":"PPT原文：Bohr 效应 组织中代谢作用产生H+ 和CO2 ，代谢越旺 盛的组织，需要的O2 越多，产生的H+ 和CO2 也越多。正确答案：代谢。","src":"PPT原文题"}},{"i":74,"sec":"老师PPT逐页","title":"Bohr 效应","notes":"【图源】老师第6章PPT原页。Bohr 效应 氧合血红蛋白在组织中释放的O2 量除了受到 组织中低O2 浓度的作用外，还受组织中低pH 的 影响。后者叫做Bohr 效应，因1904 年发现此现 象的丹麦生理学家C. Bohr 而得名。 产生Bohr 效应的原因是血红蛋白中一些pK 值处于7 附近的可解离基团的作用，主要是 His ，它们解离与否会影响到血红蛋白的构象， 从而影响血红蛋白对O2 的亲和力。","points":["Bohr 效应 氧合血红蛋白在组织中释放的O2 量除了受到 组织中低O2 浓度的作用外，还受组织中低pH 的 影响","后者叫做Bohr 效应，因1904 年发现此现 象的丹麦生理学家C. Bohr 而得名","产生Bohr 效应的原因是血红蛋白中一些pK 值处于7 附近的可解离基团的作用，主要是 His ，它们解离与否会影响到血红蛋白的构象， 从而影响血红蛋白对O2 的亲和力"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full47.jpg","imageExplain":"读图顺序：先看标题「Bohr 效应」，再在图中找：这张图讲pH/CO₂对Hb（血红蛋白）曲线的影响：pH降低或CO₂升高稳定T态，曲线右移，P50（半饱和氧分压）增大，组织更容易卸氧。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第47页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_74","kind":"fill","q":"Bohr 效应 氧合______在组织中释放的O2 量除了受到 组织中低O2 浓度的作用外，还受组织中低pH 的 影响","a":"血红蛋白","e":"PPT原文：Bohr 效应 氧合血红蛋白在组织中释放的O2 量除了受到 组织中低O2 浓度的作用外，还受组织中低pH 的 影响。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":75,"sec":"老师PPT逐页","title":"Mb（肌红蛋白）与Hb（血红蛋白）在不同pH下的氧合曲线","notes":"pH降低时Hb（血红蛋白）曲线右移（Bohr效应），Mb（肌红蛋白）基本不受pH调节；比较时看P50（半饱和氧分压）和曲线位置。","points":["pH↓→Hb（血红蛋白）右移。","Mb（肌红蛋白）无Bohr效应。","右移=亲和力下降/卸氧。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full48.jpg","imageExplain":"这张图在讲：pH降低时Hb（血红蛋白）曲线右移（Bohr效应），Mb（肌红蛋白）基本不受pH调节。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：pH↓→Hb右移。；Mb无Bohr效应。。","source":"老师第6章PPT 第48页","srcType":"老师PPT","role":"查阅"},{"i":76,"sec":"老师PPT逐页","title":"CO2 与Hb（血红蛋白） 的结合","notes":"CO₂可与Hb（血红蛋白）亚基N端游离α-氨基结合形成氨基甲酸酯，稳定T态；CO₂/H⁺共同促进O₂释放，是Bohr效应的一部分。","points":["CO₂结合Hb（血红蛋白） N端α-氨基。","形成氨基甲酸酯，稳定T态。","促进O₂释放。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full49.jpg","imageExplain":"这张图在讲：CO₂可与Hb（血红蛋白）亚基N端游离α-氨基结合形成氨基甲酸酯，稳定T态；CO₂/H⁺共同促进O₂释放，是Bohr效应的一部分。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第49页","srcType":"老师PPT","role":"查阅"},{"i":77,"sec":"老师PPT逐页","title":"BPG（2,3-二磷酸甘油酸） 与Hb（血红蛋白） 的结合","notes":"【图源】老师第6章PPT原页。BPG（2,3-二磷酸甘油酸） 与Hb（血红蛋白） 的结合 2,3- 二磷酸甘油酸（BPG ）是血红蛋白一个重要 的别构效应剂（别构抑制剂）。正常人红细胞中约 含有4.5mmol/L 的BPG ，约与血红蛋白等摩尔数。 每个Hb 分子（四聚体）只有一个BPG 结合位点， 位于由4 个亚基缔合形成的中央孔穴内。高负电荷 的BPG 分子与每个β 链的若干个残基的带正电荷 基团通过静电结合于Hb 分子上，BPG 把两个β 链 交联在一起。O2 的结合使中央孔穴变小，使BPG 结合变得困难。在没有BPG 存在时，O2 的结合容 易，而在有BPG 存在时，O2 的结合变得困难。","points":["BPG（2,3-二磷酸甘油酸） 与Hb（血红蛋白） 的结合 2,3- 二磷酸甘油酸（BPG ）是血红蛋白一个重要 的别构效应剂（别构抑制剂）","正常人红细胞中约 含有4.5mmol/L 的BPG（2,3-二磷酸甘油酸） ，约与血红蛋白等摩尔数","每个Hb（血红蛋白） 分子（四聚体）只有一个BPG（2,3-二磷酸甘油酸） 结合位点， 位于由4 个亚基缔合形成的中央孔穴内"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full50.jpg","imageExplain":"这张图讲BPG（2,3-二磷酸甘油酸）结合位置：BPG带负电，卡在两条β链之间的中央空腔，形成盐桥稳定T态；BPG升高→右移→卸氧增加。","source":"老师第6章PPT 第50页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_77","kind":"fill","q":"BPG（2,3-二磷酸甘油酸） 与Hb（血红蛋白） 的结合 2,3- 二磷酸甘油酸（BPG ）是______一个重要 的别构效应剂（别构抑制剂）","a":"血红蛋白","e":"PPT原文：BPG（2,3-二磷酸甘油酸） 与Hb（血红蛋白） 的结合 2,3- 二磷酸甘油酸（BPG ）是血红蛋白一个重要 的别构效应剂（别构抑制剂）。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":78,"sec":"老师PPT逐页","title":"2,3-BPG与血红蛋白β链的结合","notes":"BPG（2,3-二磷酸甘油酸）带负电，结合Hb（血红蛋白）两条β链之间的中央空腔，与β链N端Val1、His2、Lys82、His143等形成盐桥，稳定T态，降低O₂亲和力。","points":["BPG（2,3-二磷酸甘油酸）结合β链中央空腔。","与Val1/His2/Lys82/His143等成盐桥。","稳定T态→曲线右移。","BPG（2,3-二磷酸甘油酸）升高→组织卸氧增加。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full51.jpg","imageExplain":"这张图在讲：BPG（2,3-二磷酸甘油酸）带负电，结合Hb（血红蛋白）两条β链之间的中央空腔，与β链N端Val1、His2、Lys82、His143等形成盐桥，稳定T态，降低O₂亲和力。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第51页","srcType":"老师PPT","role":"查阅"},{"i":79,"sec":"老师PPT逐页","title":"BPG（2,3-二磷酸甘油酸）对血红蛋白氧合曲线的影响","notes":"【图源】原书图。BPG（2,3-二磷酸甘油酸）优先结合T态，使曲线右移、P50（半饱和氧分压）增大、氧亲和力下降；BPG升高时组织卸氧增加。","points":["BPG（2,3-二磷酸甘油酸）→稳定T。","曲线右移，P50（半饱和氧分压）增大。","生理意义：高原/贫血代偿。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"原书图4-17：BPG（2,3-二磷酸甘油酸）浓度升高使Hb（血红蛋白）氧合曲线右移、P50（半饱和氧分压）增大，组织卸氧增加；比较无BPG/5/8 mmol/L三条曲线。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅"},{"i":80,"sec":"老师PPT逐页","title":"BPG（2,3-二磷酸甘油酸）对血红蛋白氧合曲线的影响","notes":"【图源】原书图。BPG（2,3-二磷酸甘油酸）优先结合T态，使曲线右移、P50（半饱和氧分压）增大、氧亲和力下降；BPG升高时组织卸氧增加。","points":["BPG（2,3-二磷酸甘油酸）→稳定T。","曲线右移，P50（半饱和氧分压）增大。","生理意义：高原/贫血代偿。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"原书图4-17：BPG（2,3-二磷酸甘油酸）浓度升高使Hb（血红蛋白）氧合曲线右移、P50（半饱和氧分压）增大，组织卸氧增加；比较无BPG/5/8 mmol/L三条曲线。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅"},{"i":81,"sec":"老师PPT逐页","title":"BPG（2,3-二磷酸甘油酸） 的生理作用","notes":"【图源】老师第6章PPT原页。BPG（2,3-二磷酸甘油酸） 的生理作用 人的某些生理性或病理性缺氧可以通过红细胞 中BPG 浓度的升高而代偿。当正常人在短时间内 由海平面上升到4500m 高的高山上时，红细胞中 的BPG 浓度几个小时后就开始上升，两天内可由 4.5mmol/L 增加到7.5mmol/L ，使氧的释放量增大。 值得注意的是，BPG 浓度增加对肺中Hb（血红蛋白） 与O2 的 结合影响不大。","points":["BPG（2,3-二磷酸甘油酸） 的生理作用 人的某些生理性或病理性缺氧可以通过红细胞 中BPG 浓度的升高而代偿","当正常人在短时间内 由海平面上升到4500m 高的高山上时，红细胞中 的BPG（2,3-二磷酸甘油酸） 浓度几个小时后就开始上升，两天内可由 4.5mmol/L 增加到7.5mmol/L ，使氧的释放量增大","值得注意的是，BPG（2,3-二磷酸甘油酸） 浓度增加对肺中Hb（血红蛋白） 与O2 的 结合影响不大"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full54.jpg","imageExplain":"这张图在讲：BPG（2,3-二磷酸甘油酸） 的生理作用 人的某些生理性或病理性缺氧可以通过红细胞 中BPG 浓度的升高而代偿。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：BPG 的生理作用 人的某些生理性或病理性缺氧可以通过红细胞 中BPG 浓度的升高而代偿；当正常人在短时间内 由海平面上升到4500m 高的高山上时，红细胞中 的BPG 浓度几个小时后就开始上升，两天内可由 4.5mmol/L 增加到7.5mmol/L ，使氧的释放量增大。","source":"老师第6章PPT 第54页","srcType":"老师PPT","role":"查阅"},{"i":82,"sec":"老师PPT逐页","title":"镰刀状细胞贫血病","notes":"【图源】老师第6章PPT原页。镰刀状细胞贫血病 镰刀状细胞贫血病（sickle-cell anemia ）是最早 被认识的一种分子病。这种病在非洲某些地区十分流 行（高达40% ），它是由于遗传基因的突变导致血 红蛋白分子中氨基酸残基被改变造成的。镰刀状细胞 贫血病人血红蛋白含量仅为正常人（15 ～16g/ 100ml ）的一半，红细胞数目也是正常人（4.6 ～ 6.2×106 个/ml ）的一半左右，而且红细胞的形态也 不正常，除了有非常大量的未成熟红细胞外，还有很 多成镰刀状的红细胞。当红细胞脱氧时，镰刀状红细 胞的数量明显增加。这种病人的血红蛋白称为 HbS（镰状血红蛋白） 。","points":["镰刀状细胞贫血病 镰刀状细胞贫血病（sickle-cell anemia ）是最早 被认识的一种分子病","这种病在非洲某些地区十分流 行（高达40% ），它是由于遗传基因的突变导致血 红蛋白分子中氨基酸残基被改变造成的","镰刀状细胞 贫血病人血红蛋白含量仅为正常人（15 ～16g/ 100ml ）的一半，红细胞数目也是正常人（4.6 ～ 6.2×106 个/ml ）的一半左右，而且红细胞的形态也 不正常，除了有非常大量的未成熟红细胞外，还有很 多成镰刀状的红细胞"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full56.jpg","imageExplain":"读图顺序：先看标题「镰刀状细胞贫血病」，再在图中找：这张图讲HbS（镰状血红蛋白）镰变：β6 Glu→Val，脱氧后疏水补丁暴露，分子间聚集成纤维，红细胞被拉成镰刀状。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第56页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_82","kind":"fill","q":"这种病在非洲某些地区十分流 行（高达40% ），它是由于遗传基因的突变导致血 红蛋白分子中______残基被改变造成的","a":"氨基酸","e":"PPT原文：这种病在非洲某些地区十分流 行（高达40% ），它是由于遗传基因的突变导致血 红蛋白分子中氨基酸残基被改变造成的。正确答案：氨基酸。","src":"PPT原文题"}},{"i":83,"sec":"老师PPT逐页","title":"正常红细胞与镰状细胞贫血红细胞比较","notes":"正常红细胞双凹圆盘、柔软；HbS（镰状血红蛋白）脱氧聚集成纤维，使红细胞变镰刀状、僵硬，易堵塞血管和溶血。","points":["正常：双凹圆盘。","HbS（镰状血红蛋白）：镰刀状/僵硬。","低氧加重镰变。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full57.jpg","imageExplain":"读图顺序：先看标题「正常红细胞与镰状细胞贫血红细胞比较」，再在图中找：这张图对比正常红细胞和镰状红细胞：正常是柔软双凹圆盘；HbS（镰状血红蛋白）脱氧聚集后变僵硬镰刀状，易堵塞血管。；把图中结构/曲线与要点对应；本页结论：正常红细胞双凹圆盘、柔软。","source":"老师第6章PPT 第57页","srcType":"老师PPT","role":"查阅"},{"i":84,"sec":"老师PPT逐页","title":"镰刀状细胞贫血病","notes":"【图源】老师第6章PPT原页。镰刀状细胞贫血病 镰刀状细胞贫血病是一种致死性疾病，它的纯合 子患者有的在童年就死亡。杂合子患者的寿命也不 长，但它能抵抗一种流行于非洲的疟疾。这种疟疾 也是一种致死性疾病，甚至具有正常血红蛋白的人 死于这种疟疾的比例也很高，常常在还没有繁殖后 代就已死去。Hbs 杂合子患者对这种疟疾有一定的 抵抗能力，尚能繁殖后代，这是因为杂合子患者加 速被感染红细胞的破坏而中断疟原虫的生活周期的 缘故。","points":["镰刀状细胞贫血病 镰刀状细胞贫血病是一种致死性疾病，它的纯合 子患者有的在童年就死亡","杂合子患者的寿命也不 长，但它能抵抗一种流行于非洲的疟疾","这种疟疾 也是一种致死性疾病，甚至具有正常血红蛋白的人 死于这种疟疾的比例也很高，常常在还没有繁殖后 代就已死去"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full58.jpg","imageExplain":"读图顺序：先看标题「镰刀状细胞贫血病」，再在图中找：这张图讲HbS（镰状血红蛋白）镰变：β6 Glu→Val，脱氧后疏水补丁暴露，分子间聚集成纤维，红细胞被拉成镰刀状。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第58页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_84","kind":"fill","q":"这种疟疾 也是一种致死性疾病，甚至具有正常______的人 死于这种疟疾的比例也很高，常常在还没有繁殖后 代就已死去","a":"血红蛋白","e":"PPT原文：这种疟疾 也是一种致死性疾病，甚至具有正常血红蛋白的人 死于这种疟疾的比例也很高，常常在还没有繁殖后 代就已死去。正确答案：血红蛋白。","src":"PPT原文题"}},{"i":85,"sec":"老师PPT逐页","title":"HbA（成人血红蛋白） 和HbS（镰状血红蛋白） 的胰蛋白酶消化液","notes":"【图源】原书图。HbA（成人血红蛋白）/HbS（镰状血红蛋白）经胰蛋白酶消化后得到的肽段指纹不同；用纸层析+电泳分开肽段，可定位HbS的β6 Glu→Val差异。","points":["HbA（成人血红蛋白）/HbS（镰状血红蛋白）酶切肽段指纹不同。","双向层析/电泳可比较肽段。","差异定位到β6。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-sickle-v2.png","imageExplain":"原书图4-19：HbA（成人血红蛋白）与HbS（镰状血红蛋白）的酶切肽段指纹不同，差异来自β6 Glu→Val；一个氨基酸改变就能改变肽段电荷/位置。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_85","kind":"fill","q":"HbA（成人血红蛋白）/HbS（镰状血红蛋白）______切肽段指纹不同。","a":"酶","e":"PPT原文：HbA（成人血红蛋白）/HbS（镰状血红蛋白）酶切肽段指纹不同。。正确答案：酶。","src":"PPT原文题"}},{"i":86,"sec":"老师PPT逐页","title":"HbA（成人血红蛋白） 和HbS（镰状血红蛋白） 氨基酸序列的比较","notes":"【图源】老师第6章PPT原页。HbA（成人血红蛋白） 和HbS（镰状血红蛋白） 氨基酸序列的比较 HbA H2N-Val-His-Leu-Thr-Pro-Glu-Glu-Lys…… C 端 HbS H2N-Val-His-Leu-Thr-Pro-Val -Glu-Lys…… C 端 （β 链） 1 2 3 4 5 6 7 8 （示差异处）","points":["HbA（成人血红蛋白） β6为Glu（负电）。","HbS（镰状血红蛋白） β6为Val（中性），负电荷减少。","突变导致脱氧聚集和镰状细胞贫血。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full60.jpg","imageExplain":"这张图在讲：HbA（成人血红蛋白） 和HbS（镰状血红蛋白） 氨基酸序列的比较 HbA H2N-Val-His-Leu-Thr-Pro-Glu-Glu-Lys…… C 端 HbS H2N-Val-His-Leu-Thr-Pro-Val -Glu-Lys…… C 端 （β 链） 1 2 3 4 5 6 7 8 （示差异处）。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：HbA β6为Glu（负电）。；HbS β6为Val（中性），负电荷减少。。","source":"老师第6章PPT 第60页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_86","kind":"fill","q":"______导致脱氧聚集和镰状细胞贫血。","a":"突变","e":"PPT原文：突变导致脱氧聚集和镰状细胞贫血。。正确答案：突变。","src":"PPT原文题"}},{"i":87,"sec":"老师PPT逐页","title":"HbS（镰状血红蛋白） 聚集成纤维状沉淀","notes":"HbA（成人血红蛋白） β6为Glu（带负电），HbS（镰状血红蛋白） β6为Val（中性）；一个氨基酸改变使HbS少一个负电荷，电泳变慢，脱氧时易聚集。","points":["HbA（成人血红蛋白） β6=Glu（负电）。","HbS（镰状血红蛋白） β6=Val（中性）。","HbS（镰状血红蛋白）负电荷少，电泳慢。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full61.jpg","imageExplain":"这张图在讲：HbA（成人血红蛋白） β6为Glu（带负电），HbS（镰状血红蛋白） β6为Val（中性）；一个氨基酸改变使HbS少一个负电荷，电泳变慢，脱氧时易聚集。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第61页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_87","kind":"fill","q":"HbS（镰状血红蛋白）负电荷少，______慢。","a":"电泳","e":"PPT原文：HbS（镰状血红蛋白）负电荷少，电泳慢。。正确答案：电泳。","src":"PPT原文题"}},{"i":88,"sec":"老师PPT逐页","title":"HbS（镰状血红蛋白）聚集成纤维状沉淀","notes":"脱氧HbS（镰状血红蛋白）的疏水补丁暴露，分子间互相粘住，形成长纤维；纤维把红细胞撑成镰刀状。","points":["脱氧HbS（镰状血红蛋白）疏水补丁暴露。","分子间聚集成纤维。","红细胞镰变。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full62.jpg","imageExplain":"读图顺序：先看标题「HbS（镰状血红蛋白）聚集成纤维状沉淀」，再在图中找：这张图看HbS聚集：脱氧HbS疏水补丁暴露，分子间互相粘住形成长纤维；纤维把红细胞撑成镰刀状。；把图中结构/曲线与要点对应；本页结论：脱氧HbS的疏水补丁暴露，分子间互相粘住，形成长纤维。","source":"老师第6章PPT 第62页","srcType":"老师PPT","role":"查阅"},{"i":89,"sec":"老师PPT逐页","title":"地中海贫血的分子机制","notes":"【图源】老师第6章PPT原页。地中海贫血可由三类珠蛋白基因缺陷引起：①缺失一个或多个α/β珠蛋白链基因，导致相应链合成不足；②无义突变使密码子提前终止、产生截短肽链，或移码突变使氨基酸序列错乱、产生无功能肽链；③编码区外突变（启动子、剪接位点等）导致不能转录或RNA加工错误。结果α/β珠蛋白链比例失衡，过剩链沉淀，红细胞破坏而贫血。我国广东携带率较高。","points":["基因缺失→珠蛋白链不足","无义突变→截短肽；移码→无功能肽","编码区外突变→转录/加工异常","共同后果：链比例失衡、溶血贫血","广东携带率高"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full63.jpg","imageExplain":"这张图在讲：地中海贫血可由三类珠蛋白基因缺陷引起：①缺失一个或多个α/β珠蛋白链基因，导致相应链合成不足。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：基因缺失→珠蛋白链不足；无义突变→截短肽；移码→无功能肽。","source":"老师第6章PPT 第63页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_89","kind":"fill","q":"无义______→截短肽；移码→无功能肽","a":"突变","e":"PPT原文：无义突变→截短肽；移码→无功能肽。正确答案：突变。","src":"PPT原文题"}},{"i":90,"sec":"老师PPT逐页","title":"四、免疫系统和免疫球蛋白","notes":"【图源】老师第6章PPT原页。四、免疫系统和免疫球蛋白 （免疫球蛋白部分） 免疫球蛋白，Immunoglobulin, Ig","points":["四、免疫系统和免疫球蛋白 （免疫球蛋白部分） 免疫球蛋白，Immunoglobulin, Ig"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full64.jpg","imageExplain":"这张图在讲：四、免疫系统和免疫球蛋白 （免疫球蛋白部分） 免疫球蛋白，Immunoglobulin, Ig。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：四、免疫系统和免疫球蛋白 （免疫球蛋白部分） 免疫球蛋白，Immunoglobulin, Ig。","source":"老师第6章PPT 第64页","srcType":"老师PPT","role":"查阅"},{"i":91,"sec":"老师PPT逐页","title":"免疫球蛋白G（IgG）的结构","notes":"【图源】老师第6章PPT原页。IgG（免疫球蛋白G）由两条相同重链（γ）和两条相同轻链（κ或λ）组成，呈Y形，链间/链内由二硫键连接。每个结构域是免疫球蛋白折叠。N端VH（重链可变区）+VL（轻链可变区）是可变区，三个CDR（互补决定区）组成抗原结合位点；CH1、CH2、CH3、CL（轻链恒定区）是恒定区，负责结构支撑和效应功能。木瓜蛋白酶在铰链区二硫键N端侧切割，产生2个单价Fab（VH+CH1+VL+CL）和1个Fc（CH2+CH3二聚体）；胃蛋白酶在C端侧切割，产生双价F(ab′)₂和小片段。Fc结合补体C1q/Fc受体，介导调理、ADCC（抗体依赖细胞介导的细胞毒作用）和补体激活；CH2上连糖链。","points":["IgG（免疫球蛋白G）=2重链(γ)+2轻链(κ/λ)，Y形","VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合抗原","Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区）；Fc（可结晶片段）=CH2+CH3","木瓜蛋白酶→2 Fab（抗原结合片段）+Fc（可结晶片段）；胃蛋白酶→F(ab′)₂+小片段","Fc（可结晶片段）介导补体/Fc受体效应"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full65.jpg","imageExplain":"这张IgG（免疫球蛋白G）图看Y形四链：Fab（VH+VL（轻链可变区））在臂端结合抗原；Fc（CH2+CH3）在柄端介导补体/Fc受体效应。","source":"老师第6章PPT 第65页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_91","kind":"fill","q":"VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合______","a":"抗原","e":"PPT原文：VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合抗原。正确答案：抗原。","src":"PPT原文题"}},{"i":92,"sec":"老师PPT逐页","title":"免疫球蛋白的空间填充模型","notes":"IgG（免疫球蛋白G）空间填充模型显示Y形：VH（重链可变区）+VL（轻链可变区）在两臂顶端形成抗原结合位点，CH（重链恒定区）/CL（轻链恒定区）构成骨架，糖链位于Fc（可结晶片段）；空间填充强调结构紧凑和互补表面。","points":["Y形抗体","VH（重链可变区）+VL（轻链可变区）=抗原结合部位","CL（轻链恒定区）=轻链恒定区","重链带糖链"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full66.jpg","imageExplain":"这张IgG（免疫球蛋白G）空间填充图看Y形：VH（重链可变区）+VL（轻链可变区）在臂端形成抗原结合位点；CH（重链恒定区）/CL（轻链恒定区）构成骨架；Fc（可结晶片段）在柄端带糖链，介导效应。","source":"老师第6章PPT 第66页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_92","kind":"fill","q":"VH（重链可变区）+VL（轻链可变区）=______结合部位","a":"抗原","e":"PPT原文：VH（重链可变区）+VL（轻链可变区）=抗原结合部位。正确答案：抗原。","src":"PPT原文题"}},{"i":93,"sec":"老师PPT逐页","title":"鸡卵清溶菌酶与其抗体的结合","notes":"IgG（免疫球蛋白G）空间填充模型呈Y形：VH（重链可变区）+VL（轻链可变区）在双臂顶端形成抗原结合位点；CH（重链恒定区）/CL（轻链恒定区）构成骨架；Fc（可结晶片段）在柄端，含CH2/CH3和糖链，介导效应功能。","points":["Y形四链：2重链+2轻链。","VH（重链可变区）+VL（轻链可变区）在臂端结合抗原。","Fc（可结晶片段）在柄端介导补体/Fc受体。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full67.jpg","imageExplain":"这张图在讲：IgG（免疫球蛋白G）空间填充模型呈Y形：VH（重链可变区）+VL（轻链可变区）在双臂顶端形成抗原结合位点；CH（重链恒定区）/CL（轻链恒定区）构成骨架；Fc（可结晶片段）在柄端，含CH2/CH3和糖链，介导效应功能。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第67页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_93","kind":"fill","q":"VH（重链可变区）+VL（轻链可变区）在臂端结合______。","a":"抗原","e":"PPT原文：VH（重链可变区）+VL（轻链可变区）在臂端结合抗原。。正确答案：抗原。","src":"PPT原文题"}},{"i":94,"sec":"老师PPT逐页","title":"鸡卵清溶菌酶与其抗体的结合","notes":"抗体Fab（抗原结合片段）的CDR（互补决定区）与溶菌酶表面互补；溶菌酶突出的Gln121是重要抗原决定簇。结合特异性来自形状、电荷、氢键等多弱相互作用的总和。","points":["Fab（抗原结合片段）的CDR（互补决定区）结合抗原表面。","Gln121是关键决定簇。","特异性=多弱相互作用总和。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full68.jpg","imageExplain":"这张图在讲：抗体Fab（抗原结合片段）的CDR（互补决定区）与溶菌酶表面互补。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Fab的CDR结合抗原表面。；Gln121是关键决定簇。。","source":"老师第6章PPT 第68页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_94","kind":"fill","q":"Fab（抗原结合片段）的CDR（互补决定区）结合______表面。","a":"抗原","e":"PPT原文：Fab（抗原结合片段）的CDR（互补决定区）结合抗原表面。。正确答案：抗原。","src":"PPT原文题"}},{"i":95,"sec":"老师PPT逐页","title":"免疫沉淀的交联晶格","notes":"【图源】原书图。抗原多价、抗体双价，按比例交联形成晶格；抗原过量或抗体过量时反而抑制沉淀。","points":["抗原多价+抗体双价。","合适比例→交联晶格。","过量时抑制沉淀。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-igg-v2.png","imageExplain":"读图顺序：先看标题「免疫沉淀的交联晶格」，再在图中找：原书图4-26：抗原多价、抗体双价，按比例交联成晶格；等价带沉淀最多，抗原/抗体过量会抑制沉淀。；把图中结构/曲线与要点对应；本页结论：【图源】原书图。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_95","kind":"fill","q":"______多价、抗体双价，按比例交联形成晶格","a":"抗原","e":"PPT原文：抗原多价、抗体双价，按比例交联形成晶格。正确答案：抗原。","src":"PPT原文题"}},{"i":96,"sec":"老师PPT逐页","title":"人免疫球蛋白的各种类型","notes":"【图源】老师第6章PPT原页。人免疫球蛋白的各种类型 人的免疫球蛋白除了IgG（免疫球蛋白G） 外，还有 IgA（免疫球蛋白A） 、IgM（免疫球蛋白M） 、IgD（免疫球蛋白D） 和 IgE（免疫球蛋白E） ，共有5 种类型，它们 各自存在于人体的不同部位，起着不同的作 用。Ig 分子轻链恒定区（CL ）的氨基酸序列可分 为两种基本类型：κ 和λ ，一个 Ig 分子只能含有 其中的一种。重链恒定区（包括CH1 、CH2 和 CH3 ）的序列分为5 种基本类型：γ （IgG ）、 α （IgA ）、μ （IgM ）、δ （IgD ）和 ε （IgE ）。","points":["人免疫球蛋白的各种类型 人的免疫球蛋白除了IgG（免疫球蛋白G） 外，还有 IgA（免疫球蛋白A） 、IgM（免疫球蛋白M） 、IgD（免疫球蛋白D） 和 IgE（免疫球蛋白E） ，共有5 种类型，它们 各自存在于人体的不同部位，起着不同的作 用","Ig 分子轻链恒定区（CL ）的氨基酸序列可分 为两种基本类型：κ 和λ ，一个 Ig 分子只能含有 其中的一种","重链恒定区（包括CH1 、CH2 和 CH3 ）的序列分为5 种基本类型：γ （IgG ）、 α （IgA ）、μ （IgM ）、δ （IgD ）和 ε （IgE ）"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full70.jpg","imageExplain":"这张图在讲：人免疫球蛋白的各种类型 人的免疫球蛋白除了IgG（免疫球蛋白G） 外，还有 IgA（免疫球蛋白A） 、IgM（免疫球蛋白M） 、IgD（免疫球蛋白D） 和 IgE（免疫球蛋白E） ，共有5 种类型，它们 各自存在于人体的不同部位，起着不同的作 用。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：人免疫球蛋白的各种类型 人的免疫球蛋白除了IgG 外，还有 IgA 、IgM 、IgD 和 IgE ，共有5 种类型，它们 各自存在于人体的不同部位，起着不同的作 用；Ig 分子轻链恒定区（CL ）的氨基酸序列可分 为两种基本类型：κ 和λ ，一个 Ig 分子只能含有 其中的一种。","source":"老师第6章PPT 第70页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_96","kind":"fill","q":"Ig 分子轻链恒定区（CL ）的______序列可分 为两种基本类型：κ 和λ ，一个 Ig 分子只能含有 其中的一种","a":"氨基酸","e":"PPT原文：Ig 分子轻链恒定区（CL ）的氨基酸序列可分 为两种基本类型：κ 和λ ，一个 Ig 分子只能含有 其中的一种。正确答案：氨基酸。","src":"PPT原文题"}},{"i":97,"sec":"老师PPT逐页","title":"各类免疫球蛋白的结构","notes":"IgG（免疫球蛋白G）/IgD（免疫球蛋白D）/IgE（免疫球蛋白E）/IgA（免疫球蛋白A）/IgM（免疫球蛋白M）都是Ig折叠，但重链类型、链数/聚合方式不同；IgM为五聚体，IgA可二聚体。","points":["IgG（免疫球蛋白G）单体；IgM（免疫球蛋白M）五聚体。","IgA（免疫球蛋白A）可二聚体。","IgE（免疫球蛋白E）/IgD（免疫球蛋白D）单体。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full71.jpg","imageExplain":"这张图在讲：IgG（免疫球蛋白G）/IgD（免疫球蛋白D）/IgE（免疫球蛋白E）/IgA（免疫球蛋白A）/IgM（免疫球蛋白M）都是Ig折叠，但重链类型、链数/聚合方式不同。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：IgG单体；IgM五聚体。；IgA可二聚体。。","source":"老师第6章PPT 第71页","srcType":"老师PPT","role":"查阅"},{"i":98,"sec":"老师PPT逐页","title":"IgM（免疫球蛋白M）的五聚体结构","notes":"IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系；五聚体有10个抗原结合位点，适合初次应答。","points":["5个单体","J链连接","二硫键维系","10个潜在位点"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full72.jpg","imageExplain":"读图顺序：先看标题「IgM（免疫球蛋白M）的五聚体结构」，再在图中找：这张IgM图看五聚体：5个Y形单体放射状排列，中心J链连接，二硫键维系；共有10个抗原结合位点。；把图中结构/曲线与要点对应；本页结论：IgM由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系。","source":"老师第6章PPT 第72页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_98","kind":"fill","q":"IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由______维系","a":"二硫键","e":"PPT原文：IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系。正确答案：二硫键。","src":"PPT原文题"}},{"i":99,"sec":"老师PPT逐页","title":"酶联免疫吸附测定","notes":"IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系；五聚体有10个抗原结合位点，适合初次应答。","points":["IgM（免疫球蛋白M）=五聚体，J链连接。","μ重链+轻链，二硫键维系。","10个抗原结合位点。","初次应答主要抗体。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full73.jpg","imageExplain":"这张图在讲：IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系；五聚体有10个抗原结合位点，适合初次应答。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第73页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_99","kind":"fill","q":"IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由______维系","a":"二硫键","e":"PPT原文：IgM（免疫球蛋白M）由5个Y形单体（μ重链+轻链）放射状排列，中心由J链连接，单体间/轻重链间由二硫键维系。正确答案：二硫键。","src":"PPT原文题"}},{"i":100,"sec":"老师PPT逐页","title":"血样中单纯疱疹病毒抗体的","notes":"【图源】老师第6章PPT原页。血样中单纯疱疹病毒抗体的 ELISA（酶联免疫吸附测定） 检测 An ELISA to test for the presence of herpes simplex virus (HSV) antibodies in blood samples. Wells were coated with an HSV antigen, to which antibodies against HSV will bind. The second antibody is antihuman IgG（免疫球蛋白G） linked to horseradish peroxidase. Blood samples with greater amounts of HSV antibody turn brighter yellow.","points":["ELISA（酶联免疫吸附测定）检测血清中的病毒抗体。","抗原包被孔板，加入血清，再加酶标二抗。","底物显色判断抗体有无/含量。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full74.jpg","imageExplain":"这张图在讲：血样中单纯疱疹病毒抗体的 ELISA（酶联免疫吸附测定） 检测 An ELISA to test for the presence of herpes simplex virus (HSV) antibodies in blood samples. Wells were coated with an HSV antigen, to which antibodies against HSV will bind. The second antibody is antihuman IgG（免疫球蛋白G） linked to horseradish peroxidase. Blood samples with greater amounts of HSV antibody turn brighter yellow.。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：ELISA检测血清中的病毒抗体。；抗原包被孔板，加入血清，再加酶标二抗。。","source":"老师第6章PPT 第74页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_100","kind":"fill","q":"ELISA（酶联免疫吸附测定）检测血清中的病毒______。","a":"抗体","e":"PPT原文：ELISA（酶联免疫吸附测定）检测血清中的病毒抗体。。正确答案：抗体。","src":"PPT原文题"}},{"i":101,"sec":"老师PPT逐页","title":"血清样品中单纯疱疹病毒抗","notes":"ELISA（酶联免疫吸附测定）检测血清中的病毒抗体：抗原包被孔板→加血清→加酶标二抗→底物显色；颜色深浅反映抗体有无/含量。","points":["抗原包被→加血清。","加酶标二抗。","底物显色→判断抗体。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full75.jpg","imageExplain":"这张图在讲：ELISA（酶联免疫吸附测定）检测血清中的病毒抗体：抗原包被孔板→加血清→加酶标二抗→底物显色；颜色深浅反映抗体有无/含量。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第75页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_101","kind":"fill","q":"ELISA（酶联免疫吸附测定）检测血清中的病毒抗体：______包被孔板→加血清→加酶标二抗→底物显色","a":"抗原","e":"PPT原文：ELISA（酶联免疫吸附测定）检测血清中的病毒抗体：抗原包被孔板→加血清→加酶标二抗→底物显色。正确答案：抗原。","src":"PPT原文题"}},{"i":102,"sec":"老师PPT逐页","title":"尿激酶的Western（蛋白印迹） blot检测","notes":"血清样品ELISA（酶联免疫吸附测定）：先包被抗原，封闭，加待测血清，洗去未结合抗体，再加酶标二抗和底物；颜色越深，特异性抗体越多。","points":["包被抗原/封闭。","加血清→洗。","酶标二抗+底物→显色。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full76.jpg","imageExplain":"这张图在讲：血清样品ELISA（酶联免疫吸附测定）：先包被抗原，封闭，加待测血清，洗去未结合抗体，再加酶标二抗和底物；颜色越深，特异性抗体越多。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第76页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_102","kind":"fill","q":"血清样品ELISA（酶联免疫吸附测定）：先包被______，封闭，加待测血清，洗去未结合抗体，再加酶标二抗和底物","a":"抗原","e":"PPT原文：血清样品ELISA（酶联免疫吸附测定）：先包被抗原，封闭，加待测血清，洗去未结合抗体，再加酶标二抗和底物。正确答案：抗原。","src":"PPT原文题"}},{"i":103,"sec":"老师PPT逐页","title":"单克隆抗体的制备方法","notes":"Western（蛋白印迹） blot：SDS-PAGE按分子量分离→转膜→封闭→一抗/二抗→显色/发光；可检测目标蛋白有无和分子量。","points":["SDS-PAGE分离。","转膜→抗体孵育。","显色/发光→看条带。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full77.jpg","imageExplain":"这张图在讲：Western（蛋白印迹） blot：SDS-PAGE按分子量分离→转膜→封闭→一抗/二抗→显色/发光；可检测目标蛋白有无和分子量。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第77页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_103","kind":"fill","q":"Western（蛋白印迹） blot：______按分子量分离→转膜→封闭→一抗/二抗→显色/发光","a":"SDS-PAGE","e":"PPT原文：Western（蛋白印迹） blot：SDS-PAGE按分子量分离→转膜→封闭→一抗/二抗→显色/发光。正确答案：SDS-PAGE。","src":"PPT原文题"}},{"i":104,"sec":"老师PPT逐页","title":"五、肌球蛋白丝、肌动蛋白丝","notes":"【图源】老师第6章PPT原页。五、肌球蛋白丝、肌动蛋白丝 与肌肉收缩 ( 肌纤维的结构) 脊椎动物的骨骼肌又称横纹肌或随意肌。肌肉由 许多平行的肌纤维束或称肌束组成。肌束中的每个 肌纤维就是一个骨骼肌细胞，它是长柱形的多核细 胞，直径约在20 ～100μm 之间，长可达5cm 以上， 人体的一些肌纤维甚至可达50cm 。肌细胞间有少 量结缔组织，并有毛细血管和神经纤维等。","points":["五、肌球蛋白丝、肌动蛋白丝 与肌肉收缩 ( 肌纤维的结构) 脊椎动物的骨骼肌又称横纹肌或随意肌","肌肉由 许多平行的肌纤维束或称肌束组成","肌束中的每个 肌纤维就是一个骨骼肌细胞，它是长柱形的多核细 胞，直径约在20 ～100μm 之间，长可达5cm 以上， 人体的一些肌纤维甚至可达50cm"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full78.jpg","imageExplain":"这张图在讲：五、肌球蛋白丝、肌动蛋白丝 与肌肉收缩 ( 肌纤维的结构) 脊椎动物的骨骼肌又称横纹肌或随意肌。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：五、肌球蛋白丝、肌动蛋白丝 与肌肉收缩 ( 肌纤维的结构) 脊椎动物的骨骼肌又称横纹肌或随意肌；肌肉由 许多平行的肌纤维束或称肌束组成。","source":"老师第6章PPT 第78页","srcType":"老师PPT","role":"查阅"},{"i":105,"sec":"老师PPT逐页","title":"骨骼肌的组织层次","notes":"【图源】原书图。从宏观到微观：肌肉→肌束→肌纤维→肌原纤维→肌节；肌节位于两条Z盘之间，含I带/A带，是收缩功能单位。","points":["肌节=收缩基本单位","Z盘界定肌节","I带/A带","肌质网/毛细血管"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「骨骼肌的组织层次」，再在图中找：原书图4-33：肌肉→肌束→肌纤维→肌原纤维→肌节；肌节是收缩功能单位，内含粗丝/细丝。；把图中结构/曲线与要点对应；本页结论：【图源】原书图。","source":"原书图（第4章）","srcType":"老师PPT","role":"查阅"},{"i":106,"sec":"老师PPT逐页","title":"肌纤维的细胞水平","notes":"骨骼肌从宏观到微观：肌肉→肌束→肌纤维→肌原纤维→肌节；肌节位于两条Z盘之间，是收缩功能单位，含I带/A带。","points":["肌肉→肌束→肌纤维→肌原纤维→肌节。","肌节=Z线到Z线。","肌节含粗丝/细丝。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full80.jpg","imageExplain":"这张图在讲：骨骼肌从宏观到微观：肌肉→肌束→肌纤维→肌原纤维→肌节；肌节位于两条Z盘之间，是收缩功能单位，含I带/A带。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第80页","srcType":"老师PPT","role":"查阅"},{"i":107,"sec":"老师PPT逐页","title":"肌原纤维的周期性结构","notes":"【图源】老师第6章PPT原页。肌 维的结构 肌原纤维呈现一个很有规则的周期性结构，暗带 和明带交替排列。明带折射率是各向同性的，因此 又称各向同性带（isotropic band ），简称 I 带；暗 带是各向异性的，所以又称各向异性带 （anisotropic band ），简称A 带。I 带被一条称 为Z 线或Z 盘的细线分成相等的两半。在A 带中央 有一个较明亮的区域称为H 区，H 区正中间有一个 致密的横线，称为M 线或M 盘，它将H 区分成相 等的两半。","points":["肌 维的结构 肌原纤维呈现一个很有规则的周期性结构，暗带 和明带交替排列","明带折射率是各向同性的，因此 又称各向同性带（isotropic band ），简称 I 带","暗 带是各向异性的，所以又称各向异性带 （anisotropic band ），简称A 带"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full81.jpg","imageExplain":"读图顺序：先看标题「肌原纤维的周期性结构」，再在图中找：这张图看肌原纤维的明带/暗带周期：粗丝在A带，细丝伸入A带；收缩时I带/H带变窄，A带不变。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第81页","srcType":"老师PPT","role":"查阅"},{"i":108,"sec":"老师PPT逐页","title":"骨骼肌肌原纤维电镜图","notes":"电镜图显示肌原纤维的明带/暗带周期、粗细肌丝和Z线；收缩时I/H带变窄，A带不变。","points":["明带/暗带交替。","粗细肌丝重叠。","A带不变，I/H变窄。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full82.jpg","imageExplain":"这张图在讲：电镜图显示肌原纤维的明带/暗带周期、粗细肌丝和Z线。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：明带/暗带交替。；粗细肌丝重叠。。","source":"老师第6章PPT 第82页","srcType":"老师PPT","role":"查阅"},{"i":109,"sec":"老师PPT逐页","title":"肌节的结构","notes":"电镜图显示肌原纤维的明带/暗带周期、粗细肌丝和Z线；收缩时I带/H带变窄，A带（粗丝长度）不变。","points":["明带/暗带交替。","粗丝/细丝重叠。","收缩：I/H变窄，A带不变。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full83.jpg","imageExplain":"这张图在讲：电镜图显示肌原纤维的明带/暗带周期、粗细肌丝和Z线；收缩时I带/H带变窄，A带（粗丝长度）不变。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第83页","srcType":"老师PPT","role":"查阅"},{"i":110,"sec":"老师PPT逐页","title":"肌肉收缩的显微观察","notes":"【图源】老师第6章PPT原页。肌肉收缩的显微观察 在一个完全的收缩中，每个肌节缩短约 1.0μm （原长2.5 μm ）。收缩时I 带和H 区几 乎消失，Z 盘向A 带靠拢，也即缩短是由I 带 和H 区两者的宽度减少造成的，但A 带宽度 （即粗丝长度）和Z 盘到H 区边缘的距离（即 细丝长度）并不改变。","points":["肌肉收缩的显微观察 在一个完全的收缩中，每个肌节缩短约 1.0μm （原长2.5 μm ）","收缩时I 带和H 区几 乎消失，Z 盘向A 带靠拢，也即缩短是由I 带 和H 区两者的宽度减少造成的，但A 带宽度 （即粗丝长度）和Z 盘到H 区边缘的距离（即 细丝长度）并不改变"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full84.jpg","imageExplain":"这张图在讲：肌肉收缩的显微观察 在一个完全的收缩中，每个肌节缩短约 1.0μm （原长2.5 μm ）。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌肉收缩的显微观察 在一个完全的收缩中，每个肌节缩短约 1.0μm （原长2.5 μm ）；收缩时I 带和H 区几 乎消失，Z 盘向A 带靠拢，也即缩短是由I 带 和H 区两者的宽度减少造成的，但A 带宽度 （即粗丝长度）和Z 盘到H 区边缘的距离（即 细丝长度）并不改变。","source":"老师第6章PPT 第84页","srcType":"老师PPT","role":"查阅"},{"i":111,"sec":"老师PPT逐页","title":"肌原纤维由粗丝和细丝构成","notes":"【图源】老师第6章PPT原页。肌 维由粗丝和细丝构成 粗丝是由250~360 个肌球蛋白分子通过它们 的尾部缔合而成的分子束，直径约为16nm ；它 们的尾都朝向A 带的中央（H 区），长度约为 1.5μm 。结构中肌球蛋白的头部有规则地每间隔 约14nm 在两端伸出。粗丝上伸出的头部与相邻 的细丝接触。 （粗丝的结构）","points":["肌 维由粗丝和细丝构成 粗丝是由250~360 个肌球蛋白分子通过它们 的尾部缔合而成的分子束，直径约为16nm","它 们的尾都朝向A 带的中央（H 区），长度约为 1.5μm","结构中肌球蛋白的头部有规则地每间隔 约14nm 在两端伸出"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full85.jpg","imageExplain":"这张图在讲：肌 维由粗丝和细丝构成 粗丝是由250~360 个肌球蛋白分子通过它们 的尾部缔合而成的分子束，直径约为16nm。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌 维由粗丝和细丝构成 粗丝是由250~360 个肌球蛋白分子通过它们 的尾部缔合而成的分子束，直径约为16nm；它 们的尾都朝向A 带的中央（H 区），长度约为 1.5μm。","source":"老师第6章PPT 第85页","srcType":"老师PPT","role":"查阅"},{"i":112,"sec":"老师PPT逐页","title":"粗丝与细丝的分子组成","notes":"【图源】老师第6章PPT原页。图A粗丝（肌球蛋白）标出头部、160nm裸区、M盘位置及14/16nm周期；图B细丝含肌钙蛋白复合体(TnT（肌钙蛋白T）/TnC（肌钙蛋白C）/TnI（肌钙蛋白I）)、原肌球蛋白和F-肌动蛋白；图C F-肌动蛋白以36nm为重复周期，由肌动蛋白单体组成。","points":["粗丝肌球蛋白头/裸区","细丝含TnT（肌钙蛋白T）/TnC（肌钙蛋白C）/TnI（肌钙蛋白I）","F-肌动蛋白36nm周期"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full86.jpg","imageExplain":"这张图在讲：图A粗丝（肌球蛋白）标出头部、160nm裸区、M盘位置及14/16nm周期。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：粗丝肌球蛋白头/裸区；细丝含TnT（肌钙蛋白T）/TnC（肌钙蛋白C）/TnI（肌钙蛋白I）。","source":"老师第6章PPT 第86页","srcType":"老师PPT","role":"查阅"},{"i":113,"sec":"老师PPT逐页","title":"肌球蛋白与F-肌动蛋白电镜/模型","notes":"肌球蛋白为双头杆状分子，尾部装配成粗丝；F-肌动蛋白由G-肌动蛋白亚基串成细丝，肌球蛋白头与细丝接触形成横桥。","points":["肌球蛋白=双头+杆状尾。","F-肌动蛋白=G亚基串。","头部接触细丝=横桥。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full87.jpg","imageExplain":"读图顺序：先看标题「肌球蛋白与F-肌动蛋白电镜/模型」，再在图中找：这张图看粗丝/细丝：肌球蛋白双头杆状，尾部装成粗丝；F-肌动蛋白由G亚基串成细丝；头部接触细丝形成横桥。；把图中结构/曲线与要点对应；本页结论：肌球蛋白为双头杆状分子，尾部装配成粗丝。","source":"老师第6章PPT 第87页","srcType":"老师PPT","role":"查阅"},{"i":114,"sec":"老师PPT逐页","title":"肌原纤维由粗丝和细丝构成","notes":"肌球蛋白为双头杆状分子，尾部装配成粗丝；F-肌动蛋白由G-肌动蛋白亚基串成细丝；肌球蛋白头与细丝接触形成横桥。","points":["肌球蛋白=双头+杆状尾。","F-肌动蛋白=G亚基串。","头部接触细丝=横桥。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full88.jpg","imageExplain":"这张图在讲：肌球蛋白为双头杆状分子，尾部装配成粗丝；F-肌动蛋白由G-肌动蛋白亚基串成细丝；肌球蛋白头与细丝接触形成横桥。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第88页","srcType":"老师PPT","role":"查阅"},{"i":115,"sec":"老师PPT逐页","title":"骨骼肌的相关蛋白质","notes":"【图源】老师第6章PPT原页。骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用。肌球蛋白和肌动蛋白共占总肌丝蛋白质的 65% ，原肌球蛋白和肌钙蛋白各占5% ，其它的 调节和结构蛋白约占肌丝蛋白质的25% 。 两个细胞骨架蛋白，肌连蛋白和伴肌动蛋白， 它们共同形成肌原纤维周围的柔性丝状网。","points":["骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用","肌球蛋白和肌动蛋白共占总肌丝蛋白质的 65% ，原肌球蛋白和肌钙蛋白各占5% ，其它的 调节和结构蛋白约占肌丝蛋白质的25%","两个细胞骨架蛋白，肌连蛋白和伴肌动蛋白， 它们共同形成肌原纤维周围的柔性丝状网"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full89.jpg","imageExplain":"这张图在讲：骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用；肌球蛋白和肌动蛋白共占总肌丝蛋白质的 65% ，原肌球蛋白和肌钙蛋白各占5% ，其它的 调节和结构蛋白约占肌丝蛋白质的25%。","source":"老师第6章PPT 第89页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_115","kind":"fill","q":"骨骼肌的相关______ 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用","a":"蛋白质","e":"PPT原文：骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用。正确答案：蛋白质。","src":"PPT原文题"}},{"i":116,"sec":"老师PPT逐页","title":"骨骼肌收缩的肌丝滑行模型","notes":"【图源】老师第6章PPT原页。肌肉收缩时粗细肌丝本身不缩短，而是细丝（F-肌动蛋白）在粗丝（肌球蛋白）上向中央滑行。图中两条Z线是细丝的锚定点；收缩时细丝插入粗丝的程度增加，两Z线靠近，肌节变短。重叠区增大，中央无细丝的H带变窄甚至消失，而粗丝全长（A带）不变。分子机制：Ca²⁺结合肌钙蛋白，原肌球蛋白移位暴露肌动蛋白结合位点；肌球蛋白横桥结合肌动蛋白，水解ATP（三磷酸腺苷）驱动头部摆动，反复结合—摆动—解离，把细丝拉向中央。","points":["Z线=细丝锚定点；收缩时Z线间距缩短","细丝沿粗丝滑行，重叠区增大","A带（粗丝长度）不变，I带/H带变窄","Ca²⁺触发，横桥循环消耗ATP（三磷酸腺苷）","收缩是滑行，不是肌丝缩短","A带=粗肌丝全长；I带=细肌丝区域；H带=粗丝中央无细丝区；Z线=肌节边界。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full90.jpg","imageExplain":"读图顺序：先看标题「骨骼肌收缩的肌丝滑行模型」，再在图中找：这张图看肌丝滑行：细丝在粗丝上向中央滑动，I带/H带变窄，A带不变；Z线靠近，肌节缩短。；把图中结构/曲线与要点对应；本页结论：【图源】老师第6章PPT原页。","source":"老师第6章PPT 第90页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_116","kind":"fill","q":"Ca²⁺触发，横桥循环消耗______（三磷酸腺苷）","a":"ATP","e":"PPT原文：Ca²⁺触发，横桥循环消耗ATP（三磷酸腺苷）。正确答案：ATP。","src":"PPT原文题"}},{"i":117,"sec":"老师PPT逐页","title":"肌肉收缩的分子机制","notes":"神经兴奋→Ca²⁺释放→Ca²⁺结合肌钙蛋白→原肌球蛋白移位→横桥结合/摆动→细丝滑行；ATP（三磷酸腺苷）驱动。","points":["Ca²⁺触发。","横桥循环耗ATP（三磷酸腺苷）。","细丝滑行，肌节缩短。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full91.jpg","imageExplain":"读图顺序：先看标题「肌肉收缩的分子机制」，再在图中找：这张图看横桥循环：Ca²⁺暴露位点→肌球蛋白头结合→ATP（三磷酸腺苷）水解摆动→ATP结合解离；循环拉细丝。；把图中结构/曲线与要点对应；本页结论：神经兴奋→Ca²⁺释放→Ca²⁺结合肌钙蛋白→原肌球蛋白移位→横桥结合/摆动→细丝滑行。","source":"老师第6章PPT 第91页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_117","kind":"fill","q":"横桥循环耗______（三磷酸腺苷）。","a":"ATP","e":"PPT原文：横桥循环耗ATP（三磷酸腺苷）。。正确答案：ATP。","src":"PPT原文题"}},{"i":118,"sec":"老师PPT逐页","title":"肌肉收缩的分子机制","notes":"神经兴奋→Ca²⁺释放→Ca²⁺结合肌钙蛋白→原肌球蛋白移位→横桥结合/摆动→细丝滑行；ATP（三磷酸腺苷）驱动。","points":["Ca²⁺触发。","横桥循环耗ATP（三磷酸腺苷）。","细丝滑行，肌节缩短。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full92.jpg","imageExplain":"读图顺序：先看标题「肌肉收缩的分子机制」，再在图中找：这张图看横桥循环：Ca²⁺暴露位点→肌球蛋白头结合→ATP（三磷酸腺苷）水解摆动→ATP结合解离；循环拉细丝。；把图中结构/曲线与要点对应；本页结论：神经兴奋→Ca²⁺释放→Ca²⁺结合肌钙蛋白→原肌球蛋白移位→横桥结合/摆动→细丝滑行。","source":"老师第6章PPT 第92页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_118","kind":"fill","q":"横桥循环耗______（三磷酸腺苷）。","a":"ATP","e":"PPT原文：横桥循环耗ATP（三磷酸腺苷）。。正确答案：ATP。","src":"PPT原文题"}},{"i":119,"sec":"老师PPT逐页","title":"肌球蛋白头与肌动蛋白丝结合","notes":"空间填充模型显示肌球蛋白头结合在F-肌动蛋白丝上形成横桥；横桥循环时头部反复结合—摆动—解离，拉动细丝。","points":["肌球蛋白头结合F-肌动蛋白。","形成横桥。","ATP（三磷酸腺苷）驱动结合/摆动/解离。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full93.jpg","imageExplain":"这张图在讲：空间填充模型显示肌球蛋白头结合在F-肌动蛋白丝上形成横桥。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌球蛋白头结合F-肌动蛋白。；形成横桥。。","source":"老师第6章PPT 第93页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_119","kind":"fill","q":"______（三磷酸腺苷）驱动结合/摆动/解离。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）驱动结合/摆动/解离。。正确答案：ATP。","src":"PPT原文题"}},{"i":120,"sec":"老师PPT逐页","title":"肌肉松弛","notes":"【图源】老师第6章PPT原页。肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一ATP（三磷酸腺苷） 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛。ATP 由线粒体供给，当 机体死亡后，线粒体停止产生ATP ，无新的ATP 与肌球蛋白结合，因而肌球蛋白头部不能脱离肌 动蛋白，使肌肉长期处于收缩状态，称为尸僵。","points":["肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一ATP（三磷酸腺苷） 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛","ATP（三磷酸腺苷） 由线粒体供给，当 机体死亡后，线粒体停止产生ATP ，无新的ATP 与肌球蛋白结合，因而肌球蛋白头部不能脱离肌 动蛋白，使肌肉长期处于收缩状态，称为尸僵"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full94.jpg","imageExplain":"这张图在讲：肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一ATP（三磷酸腺苷） 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一ATP 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛；ATP 由线粒体供给，当 机体死亡后，线粒体停止产生ATP ，无新的ATP 与肌球蛋白结合，因而肌球蛋白头部不能脱离肌 动蛋白，使肌肉长期处于收缩状态，称为尸僵。","source":"老师第6章PPT 第94页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_120","kind":"fill","q":"肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一______（三磷酸腺苷） 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛","a":"ATP","e":"PPT原文：肌肉松弛 肌肉收缩完成后，钙离子被钙泵从肌浆中回收 到肌质网，另一ATP（三磷酸腺苷） 与肌球蛋白的头部结合时， 肌球蛋白头部与肌动蛋白脱离，肌球蛋白头部又 回至原位，肌纤维松弛。正确答案：ATP。","src":"PPT原文题"}},{"i":121,"sec":"老师PPT逐页","title":"肌连蛋白","notes":"【图源】老师第6章PPT原页。肌连蛋白 肌连蛋白是一种弹性蛋白质。它是现在已知最大 的单链蛋白质，人的心肌肌连蛋白由26926 个氨基 酸残基组成，分子量为2993×103 。在肌连蛋白分子 中央是一个新的结构花式，由PEVK（弹性肽段） 的重复单位组 成。PEVK 花式可能起弹簧装置的作用，在肌肉伸 展之后可拉动肌肉恢复原状，并且也可能在调节肌 纤维的强度和弹性方面起作用。在强度特殊的肌肉 中，如心肌，PEVK 区的长度只有163 个残基，而 在弹性大的骨骼肌中PEVK 区超过2000 个残基。","points":["肌连蛋白 肌连蛋白是一种弹性蛋白质","它是现在已知最大 的单链蛋白质，人的心肌肌连蛋白由26926 个氨基 酸残基组成，分子量为2993×103","在肌连蛋白分子 中央是一个新的结构花式，由PEVK（弹性肽段） 的重复单位组 成"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full95.jpg","imageExplain":"这张图在讲：肌连蛋白 肌连蛋白是一种弹性蛋白质。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌连蛋白 肌连蛋白是一种弹性蛋白质；它是现在已知最大 的单链蛋白质，人的心肌肌连蛋白由26926 个氨基 酸残基组成，分子量为2993×103。","source":"老师第6章PPT 第95页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_121","kind":"fill","q":"肌连蛋白 肌连蛋白是一种弹性______","a":"蛋白质","e":"PPT原文：肌连蛋白 肌连蛋白是一种弹性蛋白质。正确答案：蛋白质。","src":"PPT原文题"}},{"i":122,"sec":"老师PPT逐页","title":"肌连蛋白在肌纤维中的分布","notes":"【图源】老师第6章PPT原页。肌连蛋 在肌纤维中肌连蛋白形成长而柔软的细丝，一 个这样的细丝，在松弛状态下长1000nm ，在张力 下它能伸长到3000nm 以上。在肌肉中肌连蛋白从 M 线的边缘开始，沿肌球蛋白丝全长伸展至Z 盘。 在这里肌连蛋白的作用可能是把肌球蛋白连接到Z 盘上，以及作为“分子尺”调节肌节的长度，防止 肌肉过分伸张。当肌原纤维伸张超过粗、细丝的重 叠部分，肌连蛋白则被动产生张力，使肌原纤维复 原。","points":["肌连蛋 在肌纤维中肌连蛋白形成长而柔软的细丝，一 个这样的细丝，在松弛状态下长1000nm ，在张力 下它能伸长到3000nm 以上","在肌肉中肌连蛋白从 M 线的边缘开始，沿肌球蛋白丝全长伸展至Z 盘","在这里肌连蛋白的作用可能是把肌球蛋白连接到Z 盘上，以及作为“分子尺”调节肌节的长度，防止 肌肉过分伸张"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full96.jpg","imageExplain":"这张图在讲：肌连蛋 在肌纤维中肌连蛋白形成长而柔软的细丝，一 个这样的细丝，在松弛状态下长1000nm ，在张力 下它能伸长到3000nm 以上。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：肌连蛋 在肌纤维中肌连蛋白形成长而柔软的细丝，一 个这样的细丝，在松弛状态下长1000nm ，在张力 下它能伸长到3000nm 以上；在肌肉中肌连蛋白从 M 线的边缘开始，沿肌球蛋白丝全长伸展至Z 盘。","source":"老师第6章PPT 第96页","srcType":"老师PPT","role":"查阅"},{"i":123,"sec":"老师PPT逐页","title":"细胞器沿微管的运动","notes":"驱动蛋白kinesin（驱动蛋白）通常向微管正端运输，动力蛋白dynein（动力蛋白）向负端；两者用ATP（三磷酸腺苷）驱动。","points":["Kinesin→正端。","Dynein→负端。","ATP（三磷酸腺苷）驱动。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full97.jpg","imageExplain":"这张图在讲：驱动蛋白kinesin（驱动蛋白）通常向微管正端运输，动力蛋白dynein（动力蛋白）向负端。看图时先找主体结构/坐标/箭头，再看标注；本页要抓住：Kinesin→正端。；Dynein→负端。。","source":"老师第6章PPT 第97页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_123","kind":"fill","q":"驱动蛋白kinesin（驱动蛋白）通常向______正端运输，动力蛋白dynein（动力蛋白）向负端","a":"微管","e":"PPT原文：驱动蛋白kinesin（驱动蛋白）通常向微管正端运输，动力蛋白dynein（动力蛋白）向负端。正确答案：微管。","src":"PPT原文题"}},{"i":124,"sec":"老师PPT逐页","title":"六、蛋白质的结构与功能进化","notes":"蛋白质结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰；同源蛋白保守残基常位于结构/功能关键位点。","points":["突变→序列变异→功能差异。","有利/中性保留，不利淘汰。","保守残基提示关键位点。"],"fig":"","page":null,"anim":null,"cards":null,"img":"assets/img/bc04/full98.jpg","imageExplain":"这张图在讲：驱动蛋白kinesin（驱动蛋白）通常向微管正端运输，动力蛋白dynein（动力蛋白）向负端；两者都用ATP（三磷酸腺苷）驱动，沿微管运输细胞器。 看图时先找主体结构/坐标，再看标注，最后联系本页要点。","source":"老师第6章PPT 第98页","srcType":"老师PPT","role":"查阅","check":{"id":"bc04_ck_124","kind":"fill","q":"______结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰","a":"蛋白质","e":"PPT原文：蛋白质结构-功能进化由基因突变驱动：有利/中性突变被保留，不利/致死突变被淘汰。正确答案：蛋白质。","src":"PPT原文题"}},{"sec":"第4章 · 原书单图","title":"原书单图：Mb（肌红蛋白）三级结构","img":"assets/img/bc04book/fig-mb-v2.png","notes":"原书图4-3单图裁切：Mb（肌红蛋白）为一条多肽链折叠成8段α螺旋的珠蛋白折叠，中央疏水口袋容纳血红素。","imageExplain":"这张单图看Mb（肌红蛋白）的三级结构：先找8段α螺旋和短环；再看中央血红素口袋；最后理解“单体+一个血红素”决定它没有协同、曲线为双曲线。","points":["Mb（肌红蛋白）单体，8段α螺旋组成珠蛋白折叠。","中央疏水口袋结合血红素。","单体单位点→无协同→双曲线。"],"i":125,"source":"原书图（第4章）","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_125","kind":"fill","q":"Mb（肌红蛋白）单体，8段______组成珠蛋白折叠。","a":"α螺旋","e":"PPT原文：Mb（肌红蛋白）单体，8段α螺旋组成珠蛋白折叠。。正确答案：α螺旋。","src":"PPT原文题"}},{"sec":"第4章 · 原书单图","title":"原书单图：Mb（肌红蛋白）与Hb（血红蛋白）亚基结构比较","img":"assets/img/bc04book/fig-hb-v2.png","notes":"原书图4-6单图裁切：Mb（肌红蛋白）与Hb（血红蛋白）的α/β亚基三级结构相似，都是珠蛋白折叠+血红素口袋；Hb靠四聚体产生协同。","imageExplain":"这张单图把Mb（肌红蛋白）和Hb（血红蛋白）亚基放一起：先看它们的三级结构几乎一样（珠蛋白折叠+血红素）；再看Hb有四个这样的亚基，所以能协同，Mb只有一个所以不能。","points":["Mb（肌红蛋白）与Hb（血红蛋白）亚基三级结构相似。","Hb（血红蛋白）为α₂β₂四聚体，4个血红素。","四级结构差异导致协同/别构。"],"i":126,"source":"原书图（第4章）","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_126","kind":"fill","q":"Mb（肌红蛋白）与Hb（血红蛋白）亚基______相似。","a":"三级结构","e":"PPT原文：Mb（肌红蛋白）与Hb（血红蛋白）亚基三级结构相似。。正确答案：三级结构。","src":"PPT原文题"}},{"sec":"第4章 · 原书单图","title":"原书单图：HbA（成人血红蛋白）/HbS（镰状血红蛋白）肽指纹","img":"assets/img/bc04book/fig-sickle-v2.png","notes":"原书图4-19单图裁切：HbA（成人血红蛋白）与HbS（镰状血红蛋白）的酶切肽段指纹不同；差异来自β6 Glu→Val。","imageExplain":"这张单图是HbA（成人血红蛋白）/HbS（镰状血红蛋白）的肽指纹：先看两块指纹图谱的差异点；再把它对应到β6 Glu→Val；说明一个氨基酸改变就能改变肽段电荷/位置。","points":["HbA（成人血红蛋白）/HbS（镰状血红蛋白）指纹图谱有差异。","差异定位到β6 Glu→Val。","一氨基酸突变可改变电泳/层析行为。"],"i":127,"source":"原书图（第4章）","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_127","kind":"fill","q":"一______突变可改变电泳/层析行为。","a":"氨基酸","e":"PPT原文：一氨基酸突变可改变电泳/层析行为。。正确答案：氨基酸。","src":"PPT原文题"}},{"sec":"第4章 · 原书单图","title":"原书单图：抗原-抗体交联晶格","img":"assets/img/bc04book/fig-igg-v2.png","notes":"原书图4-26单图裁切：抗原多价、抗体双价，按比例交联形成晶格；等价带沉淀最多。","imageExplain":"这张单图讲抗原抗体怎样交联：先看抗原多价、IgG（免疫球蛋白G）双价；再看它们按比例搭成网格；等价带网格最大、沉淀最多，过量时反而抑制。","points":["抗原多价+抗体双价。","等价带→最大交联/沉淀。","抗原或抗体过量→抑制沉淀。"],"i":128,"source":"原书图（第4章）","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_128","kind":"fill","q":"原书图4-26单图裁切：______多价、抗体双价，按比例交联形成晶格","a":"抗原","e":"PPT原文：原书图4-26单图裁切：抗原多价、抗体双价，按比例交联形成晶格。正确答案：抗原。","src":"PPT原文题"}},{"sec":"第4章 · 原书单图","title":"原书单图：骨骼肌结构层次","img":"assets/img/bc04book/fig-muscle.png","notes":"原书图4-33单图裁切：肌肉→肌束→肌纤维→肌原纤维→肌节，逐级组装。","imageExplain":"这张单图从大看到小：肌肉→肌束→肌纤维→肌原纤维→肌节；肌节是收缩单位，里面有粗丝/细丝。看图记住“层次越分越小，功能单位是肌节”。","points":["肌肉→肌束→肌纤维→肌原纤维→肌节。","肌节=Z线到Z线，是收缩单位。","肌节内含粗丝/细丝。"],"i":129,"source":"原书图（第4章）","srcType":"原书","role":"查阅"},{"sec":"第4章 · 原书页扫描","title":"原书页：第4章 蛋白质的生物学功能","img":"assets/img/bc04book/ch4-intro.png","notes":"原书扫描页：本章从蛋白质三维结构转向“蛋白质怎样与其他分子相互作用”。先看全章主线：Mb（肌红蛋白）/Hb（血红蛋白）、分子病、免疫球蛋白、肌肉收缩、进化。","imageExplain":"这张原书页是第4章开篇：它告诉你本章不再只讲静态结构，而是讲蛋白质怎样结合配体、传递信号、产生运动。看图时抓住“结构→功能→相互作用”。","points":["本章主线：配体结合、协同/别构、分子病、免疫、肌肉、进化。","蛋白质功能依赖构象变化和与其他分子的相互作用。","后续各节都用具体蛋白说明结构-功能关系。"],"i":130,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_130","kind":"fill","q":"本章主线：配体结合、协同/______、分子病、免疫、肌肉、进化。","a":"别构","e":"PPT原文：本章主线：配体结合、协同/别构、分子病、免疫、肌肉、进化。。正确答案：别构。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：肌红蛋白（Mb）","img":"assets/img/bc04book/mb.png","notes":"原书扫描页：Mb（肌红蛋白）为单体、153个残基、一个血红素，存在于肌肉，负责储氧和细胞内氧转运。","imageExplain":"读图顺序：先看标题「原书页：肌红蛋白（Mb）」，再在图中找：这张原书页讲Mb：先看它是一条多肽链+一个血红素；再看它和Hb（血红蛋白）亚基同源；最后看它的功能是肌肉储氧。；把图中结构/曲线与要点对应；本页结论：原书扫描页：Mb为单体、153个残基、一个血红素，存在于肌肉，负责储氧和细胞内氧转运。","points":["Mb（肌红蛋白）：单体、153 aa、1个血红素/1个O₂位点。","存在于肌肉，P50（半饱和氧分压）约2 torr，高亲和，储氧。","与Hb（血红蛋白）的α/β亚基同源，三级结构相似。"],"i":131,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_131","kind":"fill","q":"与Hb（血红蛋白）的α/β亚基同源，______相似。","a":"三级结构","e":"PPT原文：与Hb（血红蛋白）的α/β亚基同源，三级结构相似。。正确答案：三级结构。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：血红蛋白（Hb）","img":"assets/img/bc04book/hb.png","notes":"原书扫描页：Hb（血红蛋白）为α₂β₂四聚体，4个血红素/4个O₂位点，有协同和别构调节，负责运输氧。","imageExplain":"这张原书页讲Hb（血红蛋白）：先看α₂β₂四聚体；再看四个血红素相距较远，不能直接传O₂；最后看亚基界面构象变化产生协同和S形曲线。","points":["Hb（血红蛋白）：α₂β₂四聚体，4个血红素/4个O₂位点。","亚基间靠构象变化“通信”，产生正协同。","受H⁺、CO₂、BPG（2,3-二磷酸甘油酸）调节，负责肺装载/组织卸氧。"],"i":132,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_132","kind":"fill","q":"原书扫描页：Hb（血红蛋白）为α₂β₂四聚体，4个血红素/4个O₂位点，有协同和______调节，负责运输氧","a":"别构","e":"PPT原文：原书扫描页：Hb（血红蛋白）为α₂β₂四聚体，4个血红素/4个O₂位点，有协同和别构调节，负责运输氧。正确答案：别构。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：镰状细胞贫血","img":"assets/img/bc04book/sickle.png","notes":"原书扫描页：HbS（镰状血红蛋白）为β6 Glu→Val，脱氧后聚集成长纤维，红细胞镰变；低氧加重。","imageExplain":"这张原书页讲HbS（镰状血红蛋白）：先看β6 Glu→Val；再看脱氧HbS疏水补丁暴露、分子间聚集；最后看纤维把红细胞拉成镰刀状。","points":["HbS（镰状血红蛋白）：β6 Glu→Val，负电荷减少。","脱氧HbS（镰状血红蛋白）聚集成长纤维，红细胞镰变。","低氧促进脱氧/聚集，症状加重。"],"i":133,"source":"原书第4章扫描页","srcType":"原书","role":"查阅"},{"sec":"第4章 · 原书页扫描","title":"原书页：IgG（免疫球蛋白G）与免疫沉淀","img":"assets/img/bc04book/igg.png","notes":"原书扫描页：IgG（免疫球蛋白G）为Y形四链，Fab（抗原结合片段）结合抗原，Fc（可结晶片段）介导效应；抗原多价、抗体双价可形成交联晶格。","imageExplain":"这张原书页讲抗体怎样“抓抗原”和“交联”：先看IgG（免疫球蛋白G）的Y形和Fab（抗原结合片段）/Fc（可结晶片段）；再看抗原多价、抗体双价，按比例交联形成沉淀晶格。","points":["IgG（免疫球蛋白G）：2重链+2轻链，Fab（抗原结合片段）结合抗原，Fc（可结晶片段）效应。","抗原多价+抗体双价→交联晶格。","等价带沉淀最多；抗原/抗体过量抑制沉淀。"],"i":134,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_134","kind":"fill","q":"IgG（免疫球蛋白G）：2重链+2轻链，Fab（抗原结合片段）结合______，Fc（可结晶片段）效应。","a":"抗原","e":"PPT原文：IgG（免疫球蛋白G）：2重链+2轻链，Fab（抗原结合片段）结合抗原，Fc（可结晶片段）效应。。正确答案：抗原。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：肌肉收缩","img":"assets/img/bc04book/muscle.png","notes":"原书扫描页：肌球蛋白粗丝、肌动蛋白细丝、肌节；收缩时细丝滑行，A带不变，I/H带变窄。","imageExplain":"这张原书页讲肌肉的“零件”：先看粗丝（肌球蛋白）和细丝（肌动蛋白）；再看肌节A/I/H带；最后看收缩是细丝向中央滑行。","points":["粗丝=肌球蛋白；细丝=肌动蛋白+原肌球蛋白+肌钙蛋白。","肌节：Z线到Z线；A带=粗丝长度。","收缩：细丝滑行，I/H带变窄，A带不变。"],"i":135,"source":"原书第4章扫描页","srcType":"原书","role":"查阅"},{"sec":"第4章 · 原书页扫描","title":"原书页：免疫记忆与再次应答","img":"assets/img/bc04book/immune-memory.png","notes":"原书扫描页：初次免疫产生记忆细胞；再次遇到同一抗原时，再次应答更快、更强，是疫苗长期保护的基础。","imageExplain":"这张原书页讲“为什么得过病/打过疫苗后反应更快”：先看初次应答产生记忆细胞；再看再次遇到抗原时记忆细胞迅速扩增，抗体产生更快更强。","points":["初次免疫→记忆细胞。","再次应答更快、更强。","疫苗利用免疫记忆提供长期保护。"],"i":136,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_136","kind":"fill","q":"再次遇到同一______时，再次应答更快、更强，是疫苗长期保护的基础","a":"抗原","e":"PPT原文：再次遇到同一抗原时，再次应答更快、更强，是疫苗长期保护的基础。正确答案：抗原。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：各类免疫球蛋白","img":"assets/img/bc04book/ig-classes.png","notes":"原书扫描页：IgG（免疫球蛋白G）/IgD（免疫球蛋白D）/IgE（免疫球蛋白E）/IgA（免疫球蛋白A）/IgM（免疫球蛋白M）的重链类型、链数和聚合方式不同；IgM为五聚体，IgA可二聚体。","imageExplain":"这张原书页把五类Ig放一起比较：先看重链类型（γ/δ/ε/α/μ）；再看是单体还是多聚体；最后看功能差异（IgG为主、IgM（免疫球蛋白M）初次应答、IgA（免疫球蛋白A）黏膜、IgE（免疫球蛋白E）过敏）。","points":["IgG（免疫球蛋白G）单体，血清主要抗体。","IgM（免疫球蛋白M）五聚体，初次应答。","IgA（免疫球蛋白A）可二聚体，黏膜免疫；IgE（免疫球蛋白E）过敏；IgD（免疫球蛋白D） B细胞受体。"],"i":137,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_137","kind":"fill","q":"IgG（免疫球蛋白G）单体，血清主要______。","a":"抗体","e":"PPT原文：IgG（免疫球蛋白G）单体，血清主要抗体。。正确答案：抗体。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：肌球蛋白ATPase（ATP酶）与横桥","img":"assets/img/bc04book/myosin-atp.png","notes":"原书扫描页：肌球蛋白头具有ATPase（ATP酶）活性；ATP水解驱动头部构象变化，为横桥摆动提供能量。","imageExplain":"这张原书页讲肌球蛋白头怎样“烧ATP（三磷酸腺苷）做功”：先看头部结合ATP并水解；再看水解引起头部构象变化/摆动；最后看它拉着肌动蛋白细丝移动。","points":["肌球蛋白头有ATPase（ATP酶）活性。","ATP（三磷酸腺苷）水解→头部构象变化。","能量用于横桥摆动/拉细丝。"],"i":138,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_138","kind":"fill","q":"______（三磷酸腺苷）水解→头部构象变化。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）水解→头部构象变化。。正确答案：ATP。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：横桥循环与肌肉收缩","img":"assets/img/bc04book/crossbridge.png","notes":"原书扫描页：横桥循环=结合→摆动→解离→再结合；ATP（三磷酸腺苷）水解驱动摆动，ATP结合促进解离；细丝向中央滑行。","imageExplain":"这张原书页把横桥循环连起来：先看肌球蛋白头结合细丝；再看ATP（三磷酸腺苷）水解让头摆动；然后ATP结合使头解离；循环重复，细丝被拉向中央。","points":["横桥循环：结合→摆动→解离→再结合。","ATP（三磷酸腺苷）水解驱动摆动。","ATP（三磷酸腺苷）结合促进解离；Ca²⁺维持位点暴露。"],"i":139,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_139","kind":"fill","q":"______（三磷酸腺苷）水解驱动摆动。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）水解驱动摆动。。正确答案：ATP。","src":"PPT原文题"}},{"sec":"第4章 · 原书页扫描","title":"原书页：第4章总结","img":"assets/img/bc04book/ch4-summary.png","notes":"原书扫描页：本章总结Mb（肌红蛋白）/Hb（血红蛋白）、协同/别构、分子病、免疫球蛋白、肌肉收缩和进化；结构决定功能，构象变化实现调节。","imageExplain":"这张原书页是全章总结：先看Mb（肌红蛋白）/Hb（血红蛋白）的氧结合；再看协同/别构（Bohr/BPG）；再看分子病、免疫、肌肉；最后落到“结构决定功能、构象变化实现调节”。","points":["Mb（肌红蛋白）储氧，Hb（血红蛋白）运输氧；Hb有协同/别构。","H⁺/CO₂/BPG（2,3-二磷酸甘油酸）调节Hb（血红蛋白）曲线。","HbS（镰状血红蛋白）、IgG（免疫球蛋白G）、肌肉都是结构-功能例子。","主线：结构→构象变化→功能。"],"i":140,"source":"原书第4章扫描页","srcType":"原书","role":"查阅","check":{"id":"bc04_ck_140","kind":"fill","q":"Mb（肌红蛋白）储氧，Hb（血红蛋白）运输氧；Hb有协同/______。","a":"别构","e":"PPT原文：Mb（肌红蛋白）储氧，Hb（血红蛋白）运输氧；Hb有协同/别构。。正确答案：别构。","src":"PPT原文题"}},{"title":"难点精讲1：Hill方程与协同性","notes":"Hill方程Y=pO2（氧分压）^n/(P50（半饱和氧分压）^n+pO2^n)，Y为氧饱和度；Hill作图log[Y/(1−Y)]对log pO2，斜率nH（Hill系数）。Mb（肌红蛋白）无协同，nH≈1，曲线双曲线；Hb（血红蛋白）有正协同，nH≈2.8，曲线S形。P50反映亲和力，nH反映协同性，两者不是一回事。","points":["Y公式，P50（半饱和氧分压）是半饱和。","Hill斜率=nH（Hill系数）。","Mb（肌红蛋白） nH（Hill系数）≈1；Hb（血红蛋白） nH≈2.8。","P50（半饱和氧分压）=亲和力，nH（Hill系数）=协同性。"],"sec":"第04章 · 难点精讲","i":141,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"读图顺序：先看标题「难点精讲1：Hill方程与协同性」，再在图中找：看Hill/协同曲线。；把图中结构/曲线与要点对应；本页结论：Hill方程Y=pO2（氧分压）^n/(P50（半饱和氧分压）^n+pO2^n)，Y为氧饱和度。","srcType":"白话辅助","role":"练习"},{"title":"难点精讲2：Bohr效应、CO2与BPG（2,3-二磷酸甘油酸）别混","notes":"Bohr效应：pH降低/H+升高→Hb（血红蛋白）对O2亲和力下降，曲线右移，利于组织放氧。CO2可形成氨基甲酸酯并产H+，也右移。2,3-BPG结合脱氧Hb的β链中央，稳定T态，右移；胎儿Hb结合BPG（2,3-二磷酸甘油酸）弱，曲线偏左。三者都右移，但结合位点/机制不同。","points":["H+→右移（Bohr）。","CO2→氨基甲酸酯/产H+。","BPG（2,3-二磷酸甘油酸）结合脱氧Hb（血红蛋白） β链，稳定T。","胎儿Hb（血红蛋白） BPG（2,3-二磷酸甘油酸）弱→左移。"],"sec":"第04章 · 难点精讲","i":142,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"读图顺序：先看标题「难点精讲2：Bohr效应、CO2与BPG（2,3-二磷酸甘油酸）别混」，再在图中找：看BPG对氧合曲线的影响。；把图中结构/曲线与要点对应；本页结论：Bohr效应：pH降低/H+升高→Hb（血红蛋白）对O2亲和力下降，曲线右移，利于组织放氧。","srcType":"白话辅助","role":"练习"},{"title":"难点精讲3：横桥循环与ATP（三磷酸腺苷）","notes":"肌肉收缩的横桥循环：ATP（三磷酸腺苷）结合肌球蛋白头→与肌动蛋白分离；ATP水解→头复位/蓄能；头结合肌动蛋白→Pi释放→动力冲程；ADP释放→rigor状态；新ATP结合→再分离。Ca2+结合肌钙蛋白，使原肌球蛋白移开，暴露结合位点。ATP既用于分离也用于复位。","points":["ATP（三磷酸腺苷）结合→分离。","水解→复位蓄能。","Pi释放→动力冲程。","Ca2+→暴露结合位点。"],"sec":"第04章 · 难点精讲","i":143,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「难点精讲3：横桥循环与ATP（三磷酸腺苷）」，再在图中找：看肌肉/横桥结构。；把图中结构/曲线与要点对应；本页结论：肌肉收缩的横桥循环：ATP结合肌球蛋白头→与肌动蛋白分离。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_143","kind":"fill","q":"______（三磷酸腺苷）结合→分离。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）结合→分离。。正确答案：ATP。","src":"PPT原文题"}},{"title":"卡点闭环1-诊断页：Hill系数","notes":"先做：Hb（血红蛋白）的nH（Hill系数）≈2.8，最准确的意思是？","points":["A. Hb（血红蛋白）对O₂亲和力是Mb（肌红蛋白）的2.8倍","B. Hb（血红蛋白）有2.8个亚基","C. Hb（血红蛋白）有正协同性","D. Hb（血红蛋白）的P50（半饱和氧分压）=2.8"],"table":[["常见错答","错在哪"],["选A","nH（Hill系数）不是亲和力"],["选B","亚基数是4"],["选D","P50（半饱和氧分压）是压力单位"]],"tableTitle":"答案：C。nH反映协同性，不直接等于亲和力。","sec":"第04章 · 卡点闭环","i":144,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"读图顺序：先看标题「卡点闭环1-诊断页：Hill系数」，再在图中找：看Hill曲线。；把图中结构/曲线与要点对应；本页结论：先做：Hb（血红蛋白）的nH（Hill系数）≈2.8，最准确的意思是？。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-例题：Hill方程","notes":"Y=pO₂^n/(P50（半饱和氧分压）^n+pO₂^n)。当pO₂=P50时Y=0.5；Hill作图log[Y/(1−Y)]对log pO₂，斜率=nH（Hill系数）。Mb（肌红蛋白）无协同nH≈1；Hb（血红蛋白）正协同nH≈2.8。","points":["P50（半饱和氧分压）：Y=0.5时的pO₂。","nH（Hill系数）：Hill图斜率。","Mb（肌红蛋白）：nH（Hill系数）≈1，双曲线。","Hb（血红蛋白）：nH（Hill系数）≈2.8，S形曲线。","P50（半饱和氧分压）说亲和力，nH（Hill系数）说协同性。"],"sec":"第04章 · 卡点闭环","i":145,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"读图顺序：先看标题「卡点闭环1-例题：Hill方程」，再在图中找：看Hill方程。；把图中结构/曲线与要点对应；本页结论：Y=pO₂^n/(P50（半饱和氧分压）^n+pO₂^n)。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-变式：两张曲线怎么判","notes":"先看P50（半饱和氧分压）判亲和力，再看曲线陡不陡/nH（Hill系数）判协同。","table":[["情况","P50（半饱和氧分压）","nH（Hill系数）","结论"],["Mb（肌红蛋白）","小","≈1","高亲和、无协同"],["Hb（血红蛋白）","较大","≈2.8","协同释放O₂"],["Hb（血红蛋白） + BPG（2,3-二磷酸甘油酸）","增大","≈2.8","右移、放氧"],["胎儿Hb（血红蛋白）","减小","≈2.8","左移、抓氧"]],"tableTitle":"变式答案：P50看左右，nH看陡缓。","sec":"第04章 · 卡点闭环","i":146,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"读图顺序：先看标题「卡点闭环1-变式：两张曲线怎么判」，再在图中找：看左右移曲线。；把图中结构/曲线与要点对应；本页结论：先看P50（半饱和氧分压）判亲和力，再看曲线陡不陡/nH（Hill系数）判协同。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环1-错因：nH（Hill系数）三个误读","notes":"错因：①把nH（Hill系数）当亲和力；②把nH当亚基数；③把P50（半饱和氧分压）当协同性。记住：P50管“位置”，nH管“形状”。","points":["P50（半饱和氧分压）小→亲和力高→曲线左。","P50（半饱和氧分压）大→亲和力低→曲线右。","nH（Hill系数）≈1→无协同。","nH（Hill系数）>1→正协同。","nH（Hill系数）不是亚基数的精确值。"],"sec":"第04章 · 卡点闭环","i":147,"img":"assets/img/bc04book/fig-curves.png","imageExplain":"读图顺序：先看标题「卡点闭环1-错因：nH（Hill系数）三个误读」，再在图中找：看nH/协同。；把图中结构/曲线与要点对应；本页结论：错因：①把nH当亲和力。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环2-诊断页：三种效应","notes":"先做：运动时pH↓、CO₂↑、BPG（2,3-二磷酸甘油酸）↑，Hb（血红蛋白）氧合曲线怎么变？","points":["A. 左移，更容易抓氧","B. 右移，更容易放氧","C. 不变","D. 先左后右"],"table":[["常见错答","错在哪"],["选A","把组织放氧判反"],["选C","忽略别构效应"],["选D","三者方向一致"]],"tableTitle":"答案：B。都稳定T态→右移→放氧。","sec":"第04章 · 卡点闭环","i":148,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"读图顺序：先看标题「卡点闭环2-诊断页：三种效应」，再在图中找：看Bohr/BPG（2,3-二磷酸甘油酸）效应。；把图中结构/曲线与要点对应；本页结论：先做：运动时pH↓、CO₂↑、BPG↑，Hb（血红蛋白）氧合曲线怎么变？。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环2-例题：三种效应怎么区分","notes":"H⁺结合Hb（血红蛋白）→稳定T→右移（Bohr）；CO₂形成氨基甲酸酯并产H⁺→右移；BPG（2,3-二磷酸甘油酸）结合脱氧Hb的β链中央→稳定T→右移。胎儿Hb结合BPG弱→左移。","points":["H⁺：Bohr，右移。","CO₂：氨基甲酸酯/H⁺，右移。","BPG（2,3-二磷酸甘油酸）：结合脱氧Hb（血红蛋白），右移。","胎儿Hb（血红蛋白）：BPG（2,3-二磷酸甘油酸）弱，左移。"],"sec":"第04章 · 卡点闭环","i":149,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"读图顺序：先看标题「卡点闭环2-例题：三种效应怎么区分」，再在图中找：看三种效应曲线。；把图中结构/曲线与要点对应；本页结论：H⁺结合Hb（血红蛋白）→稳定T→右移（Bohr）。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环2-变式：左移还是右移","notes":"先判断效应物稳定T还是R，再判方向。","table":[["条件","稳定态","曲线","生理意义"],["pH↓/H⁺↑","T","右移","组织放氧"],["CO₂↑","T","右移","组织放氧"],["BPG（2,3-二磷酸甘油酸）↑","T","右移","高海拔/运动"],["胎儿Hb（血红蛋白）","R偏","左移","胎儿抓氧"]],"tableTitle":"变式答案：稳定T→右移；稳定R→左移。","sec":"第04章 · 卡点闭环","i":150,"srcType":"白话辅助","role":"练习"},{"title":"卡点闭环2-错因：Bohr/BPG（2,3-二磷酸甘油酸）/CO₂混","notes":"错因：①左右移记反；②以为BPG（2,3-二磷酸甘油酸）结合氧合Hb（血红蛋白）；③以为CO₂只影响pH；④把胎儿Hb与成人Hb混。","points":["右移=亲和力下降=放氧。","BPG（2,3-二磷酸甘油酸）结合脱氧Hb（血红蛋白） β链。","CO₂可成氨基甲酸酯。","胎儿Hb（血红蛋白）对BPG（2,3-二磷酸甘油酸）弱→左移。","H⁺、CO₂、BPG（2,3-二磷酸甘油酸）都稳定T。"],"sec":"第04章 · 卡点闭环","i":151,"img":"assets/img/bc04book/fig-bpg.png","imageExplain":"读图顺序：先看标题「卡点闭环2-错因：Bohr/BPG（2,3-二磷酸甘油酸）/CO₂混」，再在图中找：看Bohr/BPG/CO2。；把图中结构/曲线与要点对应；本页结论：错因：①左右移记反。","srcType":"白话辅助","role":"练习"},{"title":"卡点闭环3-诊断页：横桥循环与ATP（三磷酸腺苷）","notes":"先做：肌肉收缩中ATP（三磷酸腺苷）只用于动力冲程吗？","points":["A. 是，只供动力冲程","B. 不是，还用于肌球蛋白与肌动蛋白分离","C. ATP（三磷酸腺苷）不重要","D. 只用于Ca²⁺释放"],"table":[["常见错答","错在哪"],["选A","忽略ATP（三磷酸腺苷）结合导致分离"],["选C","rigor需要ATP（三磷酸腺苷）解除"],["选D","Ca²⁺是信号，不是ATP（三磷酸腺苷）"]],"tableTitle":"答案：B。ATP既供能，也用于解除rigor/分离。","sec":"第04章 · 卡点闭环","i":152,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「卡点闭环3-诊断页：横桥循环与ATP（三磷酸腺苷）」，再在图中找：肌肉结构。；把图中结构/曲线与要点对应；本页结论：先做：肌肉收缩中ATP只用于动力冲程吗？。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_152","kind":"fill","q":"C. ______（三磷酸腺苷）不重要","a":"ATP","e":"PPT原文：C. ATP（三磷酸腺苷）不重要。正确答案：ATP。","src":"PPT原文题"}},{"title":"卡点闭环3-例题：五步循环","notes":"横桥循环：①ATP（三磷酸腺苷）结合肌球蛋白头→与肌动蛋白分离；②ATP水解→头复位/蓄能；③头结合新的肌动蛋白；④Pi释放→动力冲程；⑤ADP释放→rigor；新ATP再结合→循环。Ca²⁺结合肌钙蛋白，使原肌球蛋白移开。","points":["ATP（三磷酸腺苷）结合→分离。","水解→复位蓄能。","结合肌动蛋白。","Pi释放→动力冲程。","ADP释放→rigor；新ATP（三磷酸腺苷）再循环。"],"sec":"第04章 · 卡点闭环","i":153,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「卡点闭环3-例题：五步循环」，再在图中找：肌肉结构。；把图中结构/曲线与要点对应；本页结论：横桥循环：①ATP（三磷酸腺苷）结合肌球蛋白头→与肌动蛋白分离。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_153","kind":"fill","q":"______（三磷酸腺苷）结合→分离。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）结合→分离。。正确答案：ATP。","src":"PPT原文题"}},{"title":"卡点闭环3-变式：rigor与松弛","notes":"先看ATP（三磷酸腺苷）和Ca²⁺，再判断横桥状态。","table":[["条件","Ca²⁺","ATP（三磷酸腺苷）","状态"],["正常收缩","高","有","循环"],["松弛","低","有","结合位点被遮挡"],["rigor","高/低","无","横桥锁住"],["ATP（三磷酸腺苷）恢复","—","有","解除rigor"]],"tableTitle":"变式答案：Ca²⁺暴露位点；ATP分离/复位；无ATP→rigor。","sec":"第04章 · 卡点闭环","i":154,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「卡点闭环3-变式：rigor与松弛」，再在图中找：肌肉结构。；把图中结构/曲线与要点对应；本页结论：先看ATP（三磷酸腺苷）和Ca²⁺，再判断横桥状态。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_154","kind":"fill","q":"先看______（三磷酸腺苷）和Ca²⁺，再判断横桥状态","a":"ATP","e":"PPT原文：先看ATP（三磷酸腺苷）和Ca²⁺，再判断横桥状态。正确答案：ATP。","src":"PPT原文题"}},{"title":"卡点闭环3-错因：ATP（三磷酸腺苷）只当“燃料”","notes":"错因：①以为ATP（三磷酸腺苷）只供动力冲程；②以为Ca²⁺直接提供能量；③以为rigor是正常收缩；④忘记ATP结合导致分离。","points":["ATP（三磷酸腺苷）结合→分离。","ATP（三磷酸腺苷）水解→复位。","Ca²⁺是开关，不是能量。","无ATP（三磷酸腺苷）→rigor。","横桥循环是机械化学偶联。"],"sec":"第04章 · 卡点闭环","i":155,"img":"assets/img/bc04book/fig-muscle.png","imageExplain":"读图顺序：先看标题「卡点闭环3-错因：ATP（三磷酸腺苷）只当“燃料”」，再在图中找：肌肉结构。；把图中结构/曲线与要点对应；本页结论：错因：①以为ATP只供动力冲程。","srcType":"白话辅助","role":"练习","check":{"id":"bc04_ck_155","kind":"fill","q":"______（三磷酸腺苷）结合→分离。","a":"ATP","e":"PPT原文：ATP（三磷酸腺苷）结合→分离。。正确答案：ATP。","src":"PPT原文题"}},{"sec":"第4章 · 使用评估","title":"bc04 使用评估与学习建议","notes":"学习顺序：AI统一版→AI考点/精讲→过程版→AI进化→老师细节→原书单图→网页题；原书页附录只查阅。","points":["AI统一版先建立主线。","AI精讲/过程版攻难点。","老师细节补老师重点。","单图精学，附录查阅。","网页题检验掌握。","题库：134本页自测、117页级选择、39章测、41网页题。"],"table":[["维度","评价"],["内容覆盖","第4章六节完整"],["讲解/过程","老师图+AI精讲+过程+原书页/单图"],["题库","39章测+41网页题+117页级题"],["视觉","原书扫描+AI图解"],["综合评分","约 90 分"]],"tableTitle":"bc04 当前评估","i":156,"img":"","source":"AI整理（依据老师PPT/原书）","srcType":"其他","role":"评估"}],"mcq":[{"id":"bc03_mcq_1","modI":0,"q":"在蛋白质一级结构测定时要确定二硫键的位置，可以用下列哪一种方法测定出含二硫键的肽段? 〈 ) [华中农业大学 2016 研]","o":["A. 欧基化合物还原","B. 过甲酸氧化","D. 双向电泳"],"a":"C","e":"","kp":""},{"id":"bc03_mcq_2","modI":0,"q":"血红蛋白的氧合曲线向右移动是由于〈 )。[山东大学研","o":["A. O2 分压的减少","B. ","C. ","D. pH 的增加"],"a":"C","e":"","kp":""},{"id":"bc03_mcq_3","modI":0,"q":"用下列方法测定蛋白质含量时，哪一种方法需要完整的肽键? ) [华中农业大学 2002 研]","o":["A. SL","B. 紫外吸收法","D. 双缩脲法"],"a":"D","e":"","kp":""},{"id":"bc03_mcq_4","modI":0,"q":"在一个肽平面中，能自由旋转的价键有几个? ¢ ) [中山大学 2019 研; 中国科学院水生生物研究所 2004 研","o":["A. 2","B. 3","C. 4","D. 5","E. 6"],"a":"B","e":"","kp":""},{"id":"bc03_mcq_5","modI":0,"q":"下列关于维持蛋白质分子空间结构的化学键的叙述，哪个是错误的? 《 ) [河北师范大学研 AL 了玻水作用是非极性氨基酸残基的侧链基团避开水，相互积聚在一起的现象。","o":["B. 在蛋白质分子中只有","C. 带负电的羧基与氨基、肌基、咪唑基等基团之问可形成盐键。","D. 在羧基与羟基之间也可以形成酯键。","E. —"],"a":"B","e":"","kp":""},{"id":"bc03_mcq_6","modI":0,"q":"测定小肽氨基酸序列的最好方法是〈 )。[华东师范大学 2007 研]","o":["A. 2,4-二硝基氟茶法","B. 二甲氨基荣矿酰氯法","C. ","D. "],"a":"D","e":"","kp":""}],"judge":[],"fill":[],"short":[{"id":"bc03_short_1","modI":0,"q":"CL) 计算一个含有 78 个氨基酸的 -螺旋的轴长。(2) 此多肽的 w-螺旋完全伸展时多长?","a":"(1) or螺旋中每个残基绕轴旋转 100*，沿轴上升 015nm，故该 -螺旋的轴长为78X0.15nm=11.7nm 。 (2) 完全伸展的肽链，残基间距离为 0.36nm，故该多肽的 o-螺旋完全伸展时长度为 0.36X78王28.08nm。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_2","modI":0,"q":"某一蛋白质的多肽链除一些区段为 -螺旋构象外，其他区段均为 B-折屋片构象。该蛋白质相对分子质量 为 240000，多肽链外形的长度为 5.06X10- cm。试计算: -螺旋占该多肽链的百分数。(假设 PHT RMA PAA 基酸残基的长度为 0.3Snm)","a":"已知氨基酸残基的平均相对分子质量为 110，所以该多肽链中氨基酸残基数为 240000/110王2182 个; 设此多肽链中 w-螺旋的氨基酸残基数为 x，则 久折县的氨基酸残基数为 2182一x; 根据 o-螺旋构象中，每个 残基上升的高度为 0.153nm，B-折县构象中，每个残基上升的高度为 0.353nm，则有","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_3","modI":0,"q":"虽然在真空中氧键键能约为 20kJ/mol，但在折县的蛋白质中它对蛋白质的稳定烩贡献却要小得多 C< 5kJ/mol)。试解释这种差别的原因。","a":"原因: 在伸展的蛋白质中大多数氢键的供体和接纳体都与水形成氢键，导致它在折奴的蛋白质中对蛋白 质的稳定烩贡献要小得多。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_4","modI":0,"q":"多聚甘氨酸是一个简单的多肽，能形成一个具有 $王一80\"，y三十120*的螺旋，根据拉氏构象图，描述 该螺旋的〈1) 手性，(2) 每圈的碱基数。 aa “fie SIS Os Pad 人 +1208 8s © x ©. sw te > +60 NU (2) ZS -60 PS 人 EN -180 Ee \\ -180 -120 -60 0 +60 +120 +180 $(deg) 图3-1 拉氏构象图","a":"(1) 根据拉氏构象图(图 3-1)，g三一80\"，y三十120\"时可知该螺旋为左手性。 (2) 根据拉氏构象图(图 3-1)，9=一80\"，y三十120\"时可知该螺旋每圈残基数为 3.0。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_5","modI":0,"q":"or-螺旋的稳定性不仅取决于肽链间的氢键形成，而且还取决于肽链的氨基酸侧链的性质。试预测在室温 下的溶液中下列多聚氨基酸哪些种将形成 w-螺旋，哪些种形成其他的有规则的结构，哪些种不能形成有规则的 结构? 并说明理由。呈多聚亮氨酸，pH=7.0; @多聚异亮氨酸，pH=7.0; OF RWAM, pH=7.0; OLR 氨酸，pH=13; OF RFAM, pH=15; @多聚苏氨酸，pH=7.0; OF RiiAM, pH=7.0.","a":"C1) @和名的 o-碳原子附近有较大的R 基，造成空间阻碍因而不能形成 -螺旋; (2) @在 pH7.0 时，其 R 基带正电荷，彼此间产生静电排斥，不能形成链内氧键，所以不能形成性螺旋; (3) @SOHy R 基在给定的 pH条件下均不带电荷，能形成链内氧键，所以可以形成 -螺旋; (4) OEY -碳原子参与R 基吡咯的形成，环内的 Cu-N 键和 C-N 肽键不能旋转，且多聚且氨酸的肽键不具 酰胺氧，不能形成链内所键，所以含有且氨酸 o-螺旋被中断，产生结节; 因此人人和名能形成 -螺旋，@@@和人@不能形成有规则的结构;加有规则，但不是 o-螺旋。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_6","modI":0,"q":"多聚甘氨酸的右手或左手 u-螺旋中哪一个比较稳定? 为什么?","a":"甘氨酸是在 w-碳原子上呈对称的特殊氨基酸，因此多聚甘氨酸的右手螺旋和左手螺旋为一对对喘体， 所以它们在能量上是相当的，也是同等稳定的。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_7","modI":0,"q":"考虑一个小的含 101 残基的蛋白质。该蛋白质将有 200 个可旋转的键。并假设对每个键 Fl 有两个定 向。问: (1) 这个蛋白质可能有多少种随机构象 (w) ? (2) 根据 CL) 的答案计算在当使 1Imol BRAM BCR AT — BP RS BT RIT HD SH AE, (AS ra); (3) WORSE A TE ET Be EH EE Fe EI ERA o- 螺旋，并且每 molH HEX AG AY TTARA—SkI/mol, iit Hl AH wa: (4) 根据你的(2) 和 (3) 的答案，计算 25C时 蛋白质的 AG yao WR AMM BBA HE 25C时是否稳定?","a":"(1) 随机构象， 由题意可知每个键可采取 2 个不同的定向，则 W=27°= 1.61 x 10 种。 (2) 粒的变化: AS wa二1.15kJ/ CK + mol). (3) AH ys一100X (—SkJ/mol) =—500kJ/mol. (4) AG we=AH ya —TXAS 和一一500十〈273十25) X1.15三一157.3kJ/mol，由于在 25C时，AG yz到0， 因此折县的蛋白质是稳定的。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_8","modI":0,"q":"两个多肽链 A 和 B，有着相似的三级结构。但是在正常情况下 A 是以单体形式存在的，而 B 是以四聚体 (By) 形式存在的，问A和了B 的氨基酸组成可能有什么差别。","a":"AA B 的氨基酸组成可能有的差别: 亚基缔合的驱动力主要是疏水作用，参与四聚体 B4 的亚基缔合的 表面可能比单体 A 的对应表面具有较多的疏水残基。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_9","modI":0,"q":"下面两个肽〈a) 和 〈(b)，哪一个更可能采取 -螺旋的二级结构? 为什么? (a) LKAENDEAARAMSEA (b) CRAGGFPWDQPGTSN","a":"Ca) 更可能采取 w-螺旋的二级结构。这是因为肽 〈a) 中有更多的有利于形成 -螺旋的氨基酸残基，而 Co) 中还有终止 w-螺旋形成的肺氨酸残基。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_10","modI":0,"q":"从热力学考虑，完全暴露在水环境中和完全埋藏在蛋白质分子非极性内部的两种多肽片段，哪一种更容 易形成 w-螺旋? 为什么?","a":"完全埋藏在蛋白质的非极性内部的多肽片段更容易形成 w-螺旋。原因是因为在水环境中多肽对稳定烩 CAH sig) 的贡献要小些。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_11","modI":0,"q":"一种酶 M,为 300000，在酸性环境中可解离成两个不同组分，其中一个组分的 M为 100000，另一个为 50000。大的组分占总蛋白质的三分之二，具有催化活性，小的组分无活性。用 P-琉基乙醇〈能还原二硫桥) 处 理时，大的失去催化能力，并且它的沉降速度减小，但沉降图案上只呈现一个峰。关于该酶的结构可作出什么结 论?","a":"CL) 由酶和解离得到的组分的相对分子质量可知此酶含 4 个亚基。 (2)由组分的活性可知, 两个无活性亚基的相对分子质量为 50000, 两个催化亚基的相对分子质量为 100000。 (3) 由 B-琉基乙醇处理后得到的沉降图案可知每个催化亚基是由两条无活性的多肽链〈相对分子质量为 50000) 组成，彼此间由二硫键交联在一起。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"},{"id":"bc03_short_12","modI":0,"q":"今有一种植物的毒素蛋白，直接用 SDS 凝胶电泳分析〈见第 5 章) 时，它的区带位于肌红蛋白 (M.A 16900) 和 B-乳球蛋白 (M, 为 37100) 两种蛋白之间，当这个毒素蛋白用 B-琶基乙醇和碘乙酸处理后，在 SDS 凝胶电泳中仍得到一条区带，但其位置靠近标记蛋白细胞素 c (M 为 13370)，进一步实验表明，该毒素蛋白与 FDNB 反应并酸水解后，释放出游离的 DNP-Gly 和 DNP-Tyr。关于此蛋白的结构，你能做出什么结论?","a":"(1) 已知 B-琉基乙醇能够还原二硫键为-SH，碘乙酸能作用于-SH。该毒素蛋白在处理前后经 SDS BEE 电泳分析得到的相对分子质量不同，并且进一步实验，与 FEDNB 能得到两种不同的 N-末端氨基酸，可判断该毒 素蛋白由两条不同的多肽链通过链间二硫键交联而成。 (2) 经 B-琉基乙醇和碘乙酸处理后,进行 SDS 凝胶电泳分析只得到一条相对分子质量在 13370 的条带，可 判断这两条不同的太短的相对分子质量均在 13000 左右。","kps":"","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记"}],"calc":[],"term":[]}],"mcq":[{"id":"bc04_exam_mcq1","modI":0,"q":"肌红蛋白的氧合曲线通常呈？","o":["A. 双曲线","B. S形曲线","C. 直线","D. 钟形"],"a":"A","e":"Mb为单体、单位点、无协同，Y对pO₂为双曲线。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_mcq2","modI":0,"q":"血红蛋白的亚基组成是？","o":["A. α₂β₂","B. α₄","C. β₄","D. 单链"],"a":"A","e":"成人Hb主要为α₂β₂四聚体，含4个血红素。","kp":"","kpId":"bc04_s0_52"},{"id":"bc04_exam_mcq3","modI":0,"q":"Hb氧合时由哪种构象转为哪种构象？","o":["A. T→R","B. R→T","C. A→B","D. 无构象变化"],"a":"A","e":"O₂结合稳定R态，T→R转变产生协同。","kp":"","kpId":"bc04_s0_52"},{"id":"bc04_exam_mcq4","modI":0,"q":"Bohr效应中，pH降低使Hb氧合曲线？","o":["A. 右移","B. 左移","C. 不变","D. 变成双曲线"],"a":"A","e":"H⁺稳定T态，降低O₂亲和力，曲线右移。","kp":"","kpId":"bc04_s0_10"},{"id":"bc04_exam_mcq5","modI":0,"q":"2,3-BPG主要结合Hb的哪个部位？","o":["A. β链间中央空腔","B. 血红素铁","C. α链N端","D. Fc段"],"a":"A","e":"BPG带负电，结合β链中央空腔，稳定T态。","kp":"","kpId":"bc04_s0_10"},{"id":"bc04_exam_mcq6","modI":0,"q":"HbS的β链突变是？","o":["A. Glu6→Val","B. Val6→Glu","C. Lys6→Arg","D. Gly6→Ala"],"a":"A","e":"HbS为β链第6位Glu→Val，负电荷减少。","kp":"","kpId":"bc04_s0_83"},{"id":"bc04_exam_mcq7","modI":0,"q":"IgG的Fab段主要功能是？","o":["A. 结合抗原","B. 激活补体","C. 结合Fc受体","D. 形成膜攻击复合物"],"a":"A","e":"Fab含VH+VL和CDR，负责抗原结合。","kp":"","kpId":"bc04_s0_90"},{"id":"bc04_exam_mcq8","modI":0,"q":"肌肉收缩时肌节中保持不变的是？","o":["A. A带宽度","B. I带宽度","C. H带宽度","D. Z线间距"],"a":"A","e":"A带为粗丝全长，收缩时不变；I带/H带变窄。","kp":"","kpId":"bc04_s0_21"}],"judge":[{"id":"bc04_exam_judge1","modI":0,"q":"肌红蛋白有4个氧结合位点。","a":"错","e":"Mb为单体，只有1个血红素/1个O₂位点。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_judge2","modI":0,"q":"血红蛋白的氧合曲线呈S形与亚基间正协同有关。","a":"对","e":"一个O₂结合促进后续O₂结合，产生S形曲线。","kp":"","kpId":"bc04_s0_52"},{"id":"bc04_exam_judge3","modI":0,"q":"pH降低时血红蛋白对O₂的亲和力升高。","a":"错","e":"H⁺稳定T态，亲和力下降，曲线右移（Bohr效应）。","kp":"","kpId":"bc04_s0_52"},{"id":"bc04_exam_judge4","modI":0,"q":"BPG升高会使Hb氧合曲线右移。","a":"对","e":"BPG稳定T态，P50增大，促进卸氧。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_judge5","modI":0,"q":"肌肉收缩时A带会明显缩短。","a":"错","e":"A带为粗丝全长，收缩时不变；I带/H带变窄。","kp":"","kpId":"bc04_s0_21"}],"fill":[{"id":"bc04_exam_fill1","modI":0,"q":"Mb的P50约为______ torr。","a":"2","e":"Mb对O₂亲和力高，P50约2 torr。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_fill2","modI":0,"q":"Hb的P50约为______ torr。","a":"26","e":"成人Hb P50约26 torr。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_fill3","modI":0,"q":"Mb的Hill系数约为______。","a":"1","e":"单体无协同，nH≈1。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_fill4","modI":0,"q":"HbS的β链第6位由Glu变为______。","a":"Val","e":"Glu6→Val导致负电荷减少、镰状细胞贫血。","kp":"","kpId":"bc04_s0_83"},{"id":"bc04_exam_fill5","modI":0,"q":"IgG经木瓜蛋白酶水解产生2个Fab和1个______。","a":"Fc","e":"木瓜蛋白酶切铰链区N端侧，产生2 Fab+Fc。","kp":"","kpId":"bc04_s0_90"}],"term":[{"id":"bc04_exam_term1","modI":0,"term":"协同效应","def":"一个配体结合后改变同一蛋白其他亚基对配体的亲和力；Hb结合O₂后正协同，氧合曲线呈S形。","kps":"配体结合+改变亲和力+亚基间","kp":"","kpId":"bc04_s0_52"},{"id":"bc04_exam_term2","modI":0,"term":"Bohr效应","def":"pH降低/CO₂升高时Hb对O₂亲和力下降、氧合曲线右移，促进组织释氧的现象。","kps":"H⁺/CO₂+右移+释氧","kp":"","kpId":"bc04_s0_10"},{"id":"bc04_exam_term3","modI":0,"term":"P50","def":"氧饱和度Y=0.5时的氧分压，是氧亲和力的指标；P50越小亲和力越高。","kps":"Y=0.5+pO₂+亲和力","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_term4","modI":0,"term":"别构效应","def":"效应物结合到蛋白的调节部位，改变活性部位构象和功能的现象；Hb受H⁺、CO₂、BPG调节。","kps":"调节部位+构象+功能","kp":"","kpId":"bc04_s0_10"},{"id":"bc04_exam_term5","modI":0,"term":"肌丝滑行","def":"肌肉收缩时粗细肌丝本身不缩短，细丝在粗丝上滑行、重叠区增大、肌节缩短的过程。","kps":"细丝滑行+重叠增加+肌节缩短","kp":"","kpId":"bc04_s0_21"}],"short":[{"id":"bc04_short_1","modI":0,"q":"CL) 计算一个含有 78 个氨基酸的 -螺旋的轴长。(2) 此多肽的 w-螺旋完全伸展时多长?","a":"(1) or螺旋中每个残基绕轴旋转 100*，沿轴上升 015nm，故该 -螺旋的轴长为78X0.15nm=11.7nm 。 (2) 完全伸展的肽链，残基间距离为 0.36nm，故该多肽的 o-螺旋完全伸展时长度为 0.36X78王28.08nm。","kps":"α-螺旋每残基上升0.15nm；伸展肽链每残基0.36nm；长度=残基数×每残基长度","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"α-螺旋中每个氨基酸残基沿螺旋轴上升约0.15 nm，78个残基的轴长=78×0.15=11.7 nm。完全伸展的肽链中相邻残基距离约0.36 nm，长度=78×0.36=28.08 nm。注意题目问“轴长”不是螺旋总长度；α-螺旋每圈3.6个残基、螺距0.54 nm，也可由圈数×螺距验证。","kpId":"bc04_s0_141"},{"id":"bc04_short_2","modI":0,"q":"某一蛋白质的多肽链除一些区段为 -螺旋构象外，其他区段均为 B-折屋片构象。该蛋白质相对分子质量 为 240000，多肽链外形的长度为 5.06X10- cm。试计算: -螺旋占该多肽链的百分数。(假设 PHT RMA PAA 基酸残基的长度为 0.3Snm)","a":"已知氨基酸残基的平均相对分子质量为 110，所以该多肽链中氨基酸残基数为 240000/110王2182 个; 设此多肽链中 w-螺旋的氨基酸残基数为 x，则 久折县的氨基酸残基数为 2182一x; 根据 o-螺旋构象中，每个 残基上升的高度为 0.153nm，B-折县构象中，每个残基上升的高度为 0.353nm，则有","kps":"残基数=M/110；α-螺旋0.15nm/残基，β-折叠0.35nm/残基；长度方程求x","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"先求残基数：240000/110≈2182。设α-螺旋残基数为x，β-折叠为2182−x；肽链外形长度=0.15x+0.35(2182−x)=506 nm（5.06×10^-5 cm=506 nm）。解得x≈1300，α-螺旋约占1300/2182≈60%。易错：cm与nm换算；β-折叠每个残基的上升距离题给0.35 nm，不要用0.15 nm。","kpId":"bc04_s0_141"},{"id":"bc04_short_3","modI":0,"q":"虽然在真空中氧键键能约为 20kJ/mol，但在折县的蛋白质中它对蛋白质的稳定烩贡献却要小得多 C< 5kJ/mol)。试解释这种差别的原因。","a":"原因: 在伸展的蛋白质中大多数氢键的供体和接纳体都与水形成氢键，导致它在折奴的蛋白质中对蛋白 质的稳定烩贡献要小得多。","kps":"水中氢键竞争；折叠时去溶剂化；净稳定贡献小","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"真空中氢键没有水竞争，键能约20 kJ/mol；在折叠的蛋白质中，肽键的C=O和N—H本来在水中就与水形成氢键，折叠时只是把“与水形成的氢键”换成“链内氢键”，净能量差很小（常小于5 kJ/mol）。此外，埋藏极性基团需要去溶剂化，付出能量代价；氢键还有协同作用和几何限制。因此单个氢键对稳定性的净贡献远小于真空键能。","kpId":"bc04_s0_52"},{"id":"bc04_short_4","modI":0,"q":"多聚甘氨酸是一个简单的多肽，能形成一个具有 $王一80\"，y三十120*的螺旋，根据拉氏构象图，描述 该螺旋的〈1) 手性，(2) 每圈的碱基数。 aa “fie SIS Os Pad 人 +1208 8s © x ©. sw te > +60 NU (2) ZS -60 PS 人 EN -180 Ee \\ -180 -120 -60 0 +60 +120 +180 $(deg) 图3-1 拉氏构象图","a":"(1) 根据拉氏构象图(图 3-1)，g三一80\"，y三十120\"时可知该螺旋为左手性。 (2) 根据拉氏构象图(图 3-1)，9=一80\"，y三十120\"时可知该螺旋每圈残基数为 3.0。","kps":"拉氏图；φ=-80°、ψ=+120°落在左手α区；每圈3个残基","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"在Ramachandran图中，φ=-80°、ψ=+120°位于左手α-螺旋允许区，因此该多聚甘氨酸形成左手α-螺旋。该构象每圈约3.0个残基（左手α-螺旋），与右手α-螺旋每圈3.6个残基不同。注意φ、ψ是主链两个可旋转键的二面角，判断手性看落在哪个允许区。","kpId":"bc04_s0_141"},{"id":"bc04_short_5","modI":0,"q":"or-螺旋的稳定性不仅取决于肽链间的氢键形成，而且还取决于肽链的氨基酸侧链的性质。试预测在室温 下的溶液中下列多聚氨基酸哪些种将形成 w-螺旋，哪些种形成其他的有规则的结构，哪些种不能形成有规则的 结构? 并说明理由。呈多聚亮氨酸，pH=7.0; @多聚异亮氨酸，pH=7.0; OF RWAM, pH=7.0; OLR 氨酸，pH=13; OF RFAM, pH=15; @多聚苏氨酸，pH=7.0; OF RiiAM, pH=7.0.","a":"C1) @和名的 o-碳原子附近有较大的R 基，造成空间阻碍因而不能形成 -螺旋; (2) @在 pH7.0 时，其 R 基带正电荷，彼此间产生静电排斥，不能形成链内氧键，所以不能形成性螺旋; (3) @SOHy R 基在给定的 pH条件下均不带电荷，能形成链内氧键，所以可以形成 -螺旋; (4) OEY -碳原子参与R 基吡咯的形成，环内的 Cu-N 键和 C-N 肽键不能旋转，且多聚且氨酸的肽键不具 酰胺氧，不能形成链内所键，所以含有且氨酸 o-螺旋被中断，产生结节; 因此人人和名能形成 -螺旋，@@@和人@不能形成有规则的结构;加有规则，但不是 o-螺旋。","kps":"大侧链/β-分支阻碍；电荷排斥；Pro中断；Gly柔性；判断规则","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"α-螺旋稳定性受侧链影响：①侧链过大或β-碳分支（Val、Ile、Thr）会造成空间阻碍，降低螺旋倾向；②带同种电荷的侧链（如pH7时Glu−）会静电排斥，破坏链内氢键；③Pro的吡咯环使主链不能旋转，且缺少酰胺氢，直接中断α-螺旋；④Gly侧链小、主链柔性大，倾向无规卷曲；⑤Leu、Ala、Glu、Arg、Met等螺旋倾向较高。答题时按“大侧链/电荷/Pro/Gly”逐类判断。","kpId":"bc04_s0_141"},{"id":"bc04_short_6","modI":0,"q":"多聚甘氨酸的右手或左手 u-螺旋中哪一个比较稳定? 为什么?","a":"甘氨酸是在 w-碳原子上呈对称的特殊氨基酸，因此多聚甘氨酸的右手螺旋和左手螺旋为一对对喘体， 所以它们在能量上是相当的，也是同等稳定的。","kps":"甘氨酸α-碳对称；右手与左手互为对映体；能量相等","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"甘氨酸的α-碳上两个H相同，是唯一非手性氨基酸；多聚甘氨酸的右手α-螺旋与左手α-螺旋互为对映体，二者能量相等，因此在溶液中同等稳定，不能像有手性侧链的氨基酸那样偏向一种手性。若侧链有手性，右手/左手螺旋不再是镜像等价，能量不同。","kpId":"bc04_s0_141"},{"id":"bc04_short_7","modI":0,"q":"考虑一个小的含 101 残基的蛋白质。该蛋白质将有 200 个可旋转的键。并假设对每个键 Fl 有两个定 向。问: (1) 这个蛋白质可能有多少种随机构象 (w) ? (2) 根据 CL) 的答案计算在当使 1Imol BRAM BCR AT — BP RS BT RIT HD SH AE, (AS ra); (3) WORSE A TE ET Be EH EE Fe EI ERA o- 螺旋，并且每 molH HEX AG AY TTARA—SkI/mol, iit Hl AH wa: (4) 根据你的(2) 和 (3) 的答案，计算 25C时 蛋白质的 AG yao WR AMM BBA HE 25C时是否稳定?","a":"(1) 随机构象， 由题意可知每个键可采取 2 个不同的定向，则 W=27°= 1.61 x 10 种。 (2) 粒的变化: AS wa二1.15kJ/ CK + mol). (3) AH ys一100X (—SkJ/mol) =—500kJ/mol. (4) AG we=AH ya —TXAS 和一一500十〈273十25) X1.15三一157.3kJ/mol，由于在 25C时，AG yz到0， 因此折县的蛋白质是稳定的。","kps":"W=2^200；ΔS=RlnW；折叠ΔS为负；ΔG=ΔH−TΔS","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"(1) 每个可旋转键2种定向，200个键的随机构象数W=2^200≈1.61×10^60。(2) ΔS=R lnW≈8.314×ln(1.61×10^60)≈1.15 kJ/(K·mol)；折叠使构象熵降低，所以ΔS为负值（约−1.15 kJ/(K·mol)）。(3) 100个氢键×(−5 kJ/mol)=−500 kJ/mol。(4) ΔG=ΔH−TΔS=−500−298×(−1.15)≈−157 kJ/mol，ΔG<0，折叠态稳定。易错：熵变符号；折叠是熵减，−TΔS为正。","kpId":"bc04_s0_141"},{"id":"bc04_short_8","modI":0,"q":"两个多肽链 A 和 B，有着相似的三级结构。但是在正常情况下 A 是以单体形式存在的，而 B 是以四聚体 (By) 形式存在的，问A和了B 的氨基酸组成可能有什么差别。","a":"AA B 的氨基酸组成可能有的差别: 亚基缔合的驱动力主要是疏水作用，参与四聚体 B4 的亚基缔合的 表面可能比单体 A 的对应表面具有较多的疏水残基。","kps":"四聚体靠疏水作用；B亚基界面疏水残基多；A表面极性/带电残基多","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"A以单体存在、B以四聚体存在，差别主要在亚基结合表面：B的亚基界面应有较多疏水残基，埋藏疏水面释放有序水，靠疏水作用驱动四聚体形成；A的对应表面应更多极性/带电残基，与水相容，缺乏足够疏水驱动力，故以单体稳定。也可能涉及盐桥、氢键和二硫键，但疏水作用是主要驱动力。","kpId":"bc04_s0_52"},{"id":"bc04_short_9","modI":0,"q":"下面两个肽〈a) 和 〈(b)，哪一个更可能采取 -螺旋的二级结构? 为什么? (a) LKAENDEAARAMSEA (b) CRAGGFPWDQPGTSN","a":"Ca) 更可能采取 w-螺旋的二级结构。这是因为肽 〈a) 中有更多的有利于形成 -螺旋的氨基酸残基，而 Co) 中还有终止 w-螺旋形成的肺氨酸残基。","kps":"螺旋倾向：Leu/Ala/Glu/Arg/Met高；Pro中断；Gly柔性；疏水/带电分布","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"(a) LKAENDEAARAMSEA更可能形成α-螺旋：含较多螺旋倾向高的残基（Leu、Ala、Glu、Arg、Met、Ser），且没有Pro；电荷分布可通过盐桥稳定。(b) CRAGGFPWDQPGTSN含Pro（中断螺旋）、Gly（柔性）和多个β-分支/芳香残基，螺旋倾向低。答题时抓Pro/Gly和螺旋倾向残基。","kpId":"bc04_s0_52"},{"id":"bc04_short_10","modI":0,"q":"从热力学考虑，完全暴露在水环境中和完全埋藏在蛋白质分子非极性内部的两种多肽片段，哪一种更容 易形成 w-螺旋? 为什么?","a":"完全埋藏在蛋白质的非极性内部的多肽片段更容易形成 w-螺旋。原因是因为在水环境中多肽对稳定烩 CAH sig) 的贡献要小些。","kps":"水中氢键竞争/去溶剂化；非极性内部更利于链内氢键","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"完全埋藏在蛋白质非极性内部的多肽片段更容易形成α-螺旋。水环境中，主链C=O和N—H会与水竞争形成氢键，链内氢键的净稳定贡献小；埋入非极性核心后，水被排除，链内氢键不再被水竞争，同时疏水效应使螺旋构象更稳定。注意“埋藏”不等于没有极性基团；极性主链需被氢键配对。","kpId":"bc04_s0_141"},{"id":"bc04_short_11","modI":0,"q":"一种酶 M,为 300000，在酸性环境中可解离成两个不同组分，其中一个组分的 M为 100000，另一个为 50000。大的组分占总蛋白质的三分之二，具有催化活性，小的组分无活性。用 P-琉基乙醇〈能还原二硫桥) 处 理时，大的失去催化能力，并且它的沉降速度减小，但沉降图案上只呈现一个峰。关于该酶的结构可作出什么结 论?","a":"CL) 由酶和解离得到的组分的相对分子质量可知此酶含 4 个亚基。 (2)由组分的活性可知, 两个无活性亚基的相对分子质量为 50000, 两个催化亚基的相对分子质量为 100000。 (3) 由 B-琉基乙醇处理后得到的沉降图案可知每个催化亚基是由两条无活性的多肽链〈相对分子质量为 50000) 组成，彼此间由二硫键交联在一起。","kps":"总分子量300k=2×100k+2×50k；β-巯基乙醇还原二硫键；100k催化亚基由两条50k链组成","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"由解离得到100k和50k两种组分，且100k占2/3、50k占1/3（质量比），可推出酶由2个100k催化亚基和2个50k无活性亚基组成，总分子量2×100k+2×50k=300k，共4个亚基。β-巯基乙醇还原二硫键后，100k催化亚基失去活性且沉降变慢，但沉降图只有一个峰，说明100k亚基解离成两条50k多肽链，二者由链间二硫键连接；还原后变成50k单链。","kpId":"bc04_s0_52"},{"id":"bc04_short_12","modI":0,"q":"今有一种植物的毒素蛋白，直接用 SDS 凝胶电泳分析〈见第 5 章) 时，它的区带位于肌红蛋白 (M.A 16900) 和 B-乳球蛋白 (M, 为 37100) 两种蛋白之间，当这个毒素蛋白用 B-琶基乙醇和碘乙酸处理后，在 SDS 凝胶电泳中仍得到一条区带，但其位置靠近标记蛋白细胞素 c (M 为 13370)，进一步实验表明，该毒素蛋白与 FDNB 反应并酸水解后，释放出游离的 DNP-Gly 和 DNP-Tyr。关于此蛋白的结构，你能做出什么结论?","a":"(1) 已知 B-琉基乙醇能够还原二硫键为-SH，碘乙酸能作用于-SH。该毒素蛋白在处理前后经 SDS BEE 电泳分析得到的相对分子质量不同，并且进一步实验，与 FEDNB 能得到两种不同的 N-末端氨基酸，可判断该毒 素蛋白由两条不同的多肽链通过链间二硫键交联而成。 (2) 经 B-琉基乙醇和碘乙酸处理后,进行 SDS 凝胶电泳分析只得到一条相对分子质量在 13370 的条带，可 判断这两条不同的太短的相对分子质量均在 13000 左右。","kps":"SDS-PAGE测亚基分子量；β-巯基乙醇还原二硫键；FDNB测N端；两条不同链约13k","freq":"常考","prio":"A","req":"理解","src":"朱圣庚第4版第3章笔记","e":"SDS-PAGE测的是亚基分子量。处理前毒素蛋白条带在16.9k—37.1k之间，说明完整蛋白由两个约13k的亚基通过二硫键连接（总约26k）。用β-巯基乙醇还原、碘乙酸封闭-SH后，条带靠近13.37k，说明二硫键被还原成单链。FDNB反应后酸水解得到DNP-Gly和DNP-Tyr两种N-末端，说明两条链的N端分别是Gly和Tyr，即两条不同的多肽链。结论：该毒素蛋白是由两条不同、各约13k的肽链通过链间二硫键连接的二聚体。","kpId":"bc04_s0_30"}],"calc":[{"id":"bc04_exam_calc1","modI":0,"q":"Mb的P50=2 torr，pO₂=8 torr时氧饱和度Y是多少？","a":"Y=8/(8+2)=0.80。","e":"Mb为双曲线：Y=pO₂/(pO₂+P50)。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_calc2","modI":0,"q":"Hb的P50=26 torr、n=2.8，pO₂=52 torr时Y约为多少？","a":"(52/26)=2；2^2.8≈6.96；Y=6.96/(1+6.96)≈0.874。","e":"用Hill方程Y=pO₂ⁿ/(P50ⁿ+pO₂ⁿ)。","kp":"","kpId":"bc04_s0_30"},{"id":"bc04_exam_calc3","modI":0,"q":"pH 8.6电泳时，HbA和HbS谁向正极迁移更快？为什么？","a":"HbA更快；HbS的β6 Glu→Val，负电荷减少，向正极迁移较慢。","e":"比较电荷差异；Glu带负电，Val中性。","kp":"","kpId":"bc04_s0_83"},{"id":"bc04_exam_calc4","modI":0,"q":"设计实验比较加BPG前后Hb的氧亲和力，写出关键步骤和判断指标。","a":"不同pO₂平衡Hb，测吸收光谱求Y，作氧合曲线并拟合P50/nH；加BPG后P50增大、曲线右移说明亲和力下降。设无BPG对照、控制pH/温度。","e":"核心：Y-pO₂曲线、P50、nH、对照。","kp":"","kpId":"bc04_s0_30"}],"preview":{"main":"3.1 复习笔记\n-、蛋白质三维构象的概述\n一个蛋白质中或一个蛋白质的任一部分中的原子空间排列称为它的三维结构或构象。\n1. 稳定蛋白质三维结构的作用力\n稳定蛋白质三维结构的作用力主要是一些非共价键或次级键，包括氧键、范德华力、疏水作用和盐键〈离子\n键)，此外共价二硫键〈一S-S一) 在稳定某些蛋白质的构象方面也起作用。\n#3-1 稳定蛋白质三维结构的作用力\n作用力                         定兴及功能作用\n氢键指一个与电负性很强的原子共价结合的氨厚子，与另一个电负性强的厚子\nBvt | 之间","questions":["CL) 计算一个含有 78 个氨基酸的 -螺旋的轴长。(2) 此多肽的 w-螺旋完全伸展时多长?","某一蛋白质的多肽链除一些区段为 -螺旋构象外，其他区段均为 B-折屋片构象。该蛋白质相对分子质量 为 240000，多肽链外形的长度为 5.06X10- cm。","虽然在真空中氧键键能约为 20kJ/mol，但在折县的蛋白质中它对蛋白质的稳定烩贡献却要小得多 C< 5kJ/mol)。试解释这种差别的原因。"]},"toc":[{"title":"前导：封面与学习路线","pages":"2页","start":0,"end":2,"items":[{"title":"封面/学习路线","start":0,"end":2}]},{"title":"AI统一版样板（Mb/Hb）","pages":"10页","start":2,"end":12,"items":[{"title":"结构/配位/定量/T→R/协同/Bohr/BPG","start":2,"end":12}]},{"title":"AI考点串讲","pages":"4页","start":12,"end":16,"items":[{"title":"Mb/Hb/别构/IgG/肌肉","start":12,"end":16}]},{"title":"AI精讲：难点突破","pages":"6页","start":16,"end":22,"items":[{"title":"T→R/BPG/HbS/IgG/ELISA/横桥","start":16,"end":22}]},{"title":"过程版：计算与实验","pages":"4页","start":22,"end":26,"items":[{"title":"Hill/曲线/电泳/实验","start":22,"end":26}]},{"title":"AI进化专题","pages":"4页","start":26,"end":30,"items":[{"title":"同源/保守/突变/复制","start":26,"end":30}]},{"title":"老师细节：一、Mb","pages":"22页","start":30,"end":52,"items":[{"title":"Mb结构/O2/曲线","start":30,"end":52}]},{"title":"老师细节：二、Hb","pages":"30页","start":52,"end":82,"items":[{"title":"Hb结构/协同/Bohr/BPG","start":52,"end":82}]},{"title":"老师细节：三、分子病","pages":"8页","start":82,"end":90,"items":[{"title":"HbS/地中海贫血","start":82,"end":90}]},{"title":"老师细节：四、免疫","pages":"14页","start":90,"end":104,"items":[{"title":"IgG/ELISA/抗体","start":90,"end":104}]},{"title":"老师细节：五、肌肉","pages":"20页","start":104,"end":124,"items":[{"title":"肌丝/横桥/收缩","start":104,"end":124}]},{"title":"老师细节：六、进化","pages":"1页","start":124,"end":125,"items":[{"title":"结构-功能进化","start":124,"end":125}]},{"title":"原书单图（精学图卡）","pages":"5页","start":125,"end":130,"items":[{"title":"Mb/Hb/指纹/晶格/肌肉","start":125,"end":130}]},{"title":"原书页查阅（附录）","pages":"11页","start":130,"end":141,"items":[{"title":"原书扫描页","start":130,"end":141}]},{"title":"难点精讲（3页）","pages":"3页","start":141,"end":144,"items":[{"title":"学生最难理解的机制/公式/方法补充","start":141,"end":144}]},{"title":"卡点闭环（12页）","pages":"12页","start":144,"end":156,"items":[{"title":"诊断/例题/变式/错因四页一组","start":144,"end":156}]},{"title":"使用评估","pages":"1页","start":156,"end":157,"items":[{"title":"评估与建议","start":156,"end":157}]}],"exerciseTitle":"蛋白质功能 · 网页题","exercises":[{"id":"bc04_ex1","no":1,"type":"简答","q":"肌红蛋白和血红蛋白在结构、氧合曲线和功能上有什么主要区别？","kp":"Mb单体/双曲线/储氧；Hb四聚体/S形/协同运输。","analysis":"Mb为单体、1个血红素/1个O₂位点，无协同，双曲线，P50约2 torr，适合肌肉储氧；Hb为α₂β₂四聚体、4个位点，有正协同，S形曲线，P50约26 torr，适合肺装载/组织卸氧。","answer":"Mb：单体、双曲线、高亲和、储氧；Hb：四聚体、S形、协同、运输氧。","slide":12,"slideTitle":"AI串讲1：Mb vs Hb 一张表","pitfalls":"Mb是单体/双曲线，Hb是四聚体/S形；不要把P50大小和亲和力方向记反。","kpId":"bc04_s0_56"},{"id":"bc04_ex2","no":2,"type":"计算","q":"Mb的P50=2 torr，pO₂=8 torr时氧饱和度Y是多少？","kp":"Mb双曲线：Y=pO₂/(pO₂+P50)。","analysis":"Mb单位点、无协同，用Y=pO₂/(pO₂+P50)。代入8/(8+2)=0.80。","answer":"Y=0.80（80%）。","slide":46,"slideTitle":"肌红蛋白的氧结合曲线：双曲线与P50","pitfalls":"Mb用Y=pO₂/(pO₂+P50)，不要套Hill方程；P50是Y=0.5时的pO₂。","kpId":"bc04_s0_46"},{"id":"bc04_ex3","no":3,"type":"计算","q":"Hb的P50=26 torr、Hill系数n=2.8，pO₂=52 torr时Y约为多少？","kp":"Hill方程：Y=pO₂ⁿ/(P50ⁿ+pO₂ⁿ)。","analysis":"先算pO₂/P50=2；2^2.8≈6.96；Y=6.96/(1+6.96)≈0.874。","answer":"Y≈0.874（87.4%）。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"Hill方程指数是n；先算pO₂/P50，再取n次方，不是直接pO₂/P50。","kpId":"bc04_s0_68"},{"id":"bc04_ex4","no":4,"type":"简答","q":"Bohr效应是什么？pH降低时Hb氧合曲线如何移动？","kp":"H⁺/CO₂稳定T态；曲线右移；组织卸氧。","analysis":"pH降低或CO₂升高时，H⁺与Hb结合稳定T态（低亲和），使P50增大、曲线右移，促进组织释放O₂，这就是Bohr效应。","answer":"pH降低→稳定T态→曲线右移→促进卸氧。","slide":73,"slideTitle":"Bohr 效应","pitfalls":"Bohr效应是pH降低/CO₂升高→曲线右移；不要记成左移。","kpId":"bc04_s0_73"},{"id":"bc04_ex5","no":5,"type":"简答","q":"2,3-BPG如何影响Hb的氧亲和力？为什么高原居民BPG升高有利？","kp":"BPG结合β链中央空腔；稳定T态；右移。","analysis":"BPG带负电，结合两条β链之间的中央空腔，形成盐桥，稳定T态，降低O₂亲和力，使曲线右移。高原低氧时BPG升高，促进组织卸氧。","answer":"BPG稳定T态、曲线右移、降低亲和力；高原代偿有利于卸氧。","slide":78,"slideTitle":"2,3-BPG与血红蛋白β链的结合","pitfalls":"BPG稳定T态→右移；HbF结合BPG弱→左移。","kpId":"bc04_s0_78"},{"id":"bc04_ex6","no":6,"type":"简答","q":"HbS的分子突变是什么？pH 8.6电泳时HbA和HbS谁迁移更快？","kp":"β6 Glu→Val；负电荷减少；电泳迁移慢。","analysis":"HbS为β链第6位Glu→Val，少一个负电荷；pH 8.6时HbA更负，向正极迁移更快，HbS较慢。","answer":"β6 Glu→Val；HbA更快，HbS较慢。","slide":82,"slideTitle":"镰刀状细胞贫血病","pitfalls":"HbS是β6 Glu→Val，负电荷减少→电泳慢；HbA快。","kpId":"bc04_s0_82"},{"id":"bc04_ex7","no":7,"type":"简答","q":"IgG经木瓜蛋白酶水解产生哪些片段？各有什么功能？","kp":"Fab结合抗原；Fc效应功能。","analysis":"木瓜蛋白酶在铰链区二硫键N端侧切割，产生2个Fab和1个Fc；Fab=VH+CH1+VL+CL，结合抗原；Fc=CH2+CH3，结合补体/Fc受体。","answer":"2个Fab（结合抗原）+1个Fc（补体/Fc受体效应）。","slide":91,"slideTitle":"免疫球蛋白G（IgG）的结构","pitfalls":"木瓜蛋白酶→2 Fab+Fc；胃蛋白酶→F(ab′)₂，不要混。","kpId":"bc04_s0_91"},{"id":"bc04_ex8","no":8,"type":"简答","q":"ELISA和Western blot分别利用什么原理检测蛋白质？","kp":"抗原-抗体特异结合；酶标显色/电泳转膜。","analysis":"ELISA把抗原或抗体包被，利用酶标抗体和底物显色定量；Western blot先SDS-PAGE分离、转膜，再用特异抗体检测目标蛋白。","answer":"ELISA=抗原抗体+酶标显色；Western=电泳+转膜+抗体检测。","slide":99,"slideTitle":"酶联免疫吸附测定","pitfalls":"ELISA定量看颜色；Western看条带和分子量，二者不是同一方法。","kpId":"bc04_s0_99"},{"id":"bc04_ex9","no":9,"type":"简答","q":"肌肉收缩时A带、I带、H带如何变化？","kp":"肌丝滑行；A带不变；I/H变窄。","analysis":"收缩时粗细肌丝本身不缩短，细丝在粗丝上滑行；A带为粗丝全长不变，I带和H带变窄，Z线间距缩短。","answer":"A带不变；I带、H带变窄；Z线靠近。","slide":116,"slideTitle":"骨骼肌收缩的肌丝滑行模型","pitfalls":"A带不变；I带、H带变窄；Z线靠近。","kpId":"bc04_s0_116"},{"id":"bc04_ex10","no":10,"type":"简答","q":"肌肉收缩的分子机制中，Ca²⁺和ATP各起什么作用？","kp":"Ca²⁺结合肌钙蛋白；ATP驱动横桥循环。","analysis":"Ca²⁺结合肌钙蛋白，使原肌球蛋白移位、暴露肌动蛋白结合位点；肌球蛋白横桥结合肌动蛋白并水解ATP，驱动头部摆动，反复循环拉细丝。","answer":"Ca²⁺暴露结合位点；ATP驱动横桥循环。","slide":117,"slideTitle":"肌肉收缩的分子机制","pitfalls":"Ca²⁺暴露结合位点；ATP驱动横桥循环；两者作用不要混。","kpId":"bc04_s0_117"},{"id":"bc04_ex11","no":11,"type":"简答","q":"镰状细胞贫血为什么在低氧时红细胞更容易成镰刀状？","kp":"HbS脱氧后聚集；纤维状沉淀；膜变形。","analysis":"HbS脱氧后疏水补丁暴露，分子间聚集成长纤维，使红细胞变成镰刀状；低氧促进脱氧HbS聚集，所以症状在低氧时加重。","answer":"低氧促进HbS脱氧聚集，形成纤维，红细胞镰变。","slide":88,"slideTitle":"HbS聚集成纤维状沉淀","pitfalls":"低氧促进HbS脱氧聚集；不是氧合HbS聚集。","kpId":"bc04_s0_88"},{"id":"bc04_ex12","no":12,"type":"简答","q":"同源蛋白质中保守残基通常说明什么？","kp":"共同进化起源；结构/功能关键位点；选择压力。","analysis":"同源蛋白由共同祖先基因演化，序列相似；保守残基往往位于结构/功能关键位点，受选择压力保留，突变可能影响功能。","answer":"保守残基提示结构/功能重要位点，支持共同进化起源。","slide":124,"slideTitle":"六、蛋白质的结构与功能进化","pitfalls":"同源=共同进化起源，不是“功能相同”或“序列完全相同”。","kpId":"bc04_s0_124"},{"id":"bc04_ex13","no":13,"type":"简答","q":"Hb氧合时T→R构象变化的关键步骤是什么？","kp":"Fe入平面、His F8/F螺旋、α1β2界面、盐桥。","analysis":"O₂结合Fe²⁺后Fe进入卟啉环平面，牵动近侧His F8和F螺旋，通过α1β2界面放大，T态盐桥断裂，四聚体转向R态。","answer":"O₂→Fe入平面→His F8/F螺旋→界面旋转→盐桥断裂→T→R。","slide":16,"slideTitle":"AI精讲1：Hb的T→R构象变化","pitfalls":"T→R顺序：Fe入平面→His F8/F螺旋→界面旋转→盐桥断裂。","kpId":"bc04_s0_16"},{"id":"bc04_ex14","no":14,"type":"简答","q":"为什么胎儿HbF对O₂的亲和力比成人Hb高？","kp":"HbF结合BPG弱；曲线左移。","analysis":"HbF的γ链与BPG结合较弱，BPG稳定T态的作用减弱，HbF更偏向R态，O₂亲和力更高，利于胎儿从母体取氧。","answer":"HbF结合BPG弱→曲线左移→亲和力高→利于胎儿取氧。","slide":17,"slideTitle":"AI精讲2：Bohr/BPG与曲线左右移","pitfalls":"HbF的γ链结合BPG弱→曲线左移→亲和力高。","kpId":"bc04_s0_17"},{"id":"bc04_ex15","no":15,"type":"简答","q":"pH 8.6电泳时HbA、HbS、HbAS分别呈现什么条带？","kp":"HbA快、HbS慢；杂合子两条带。","analysis":"HbA β6为Glu，负电荷多，向正极快；HbS β6为Val，负电荷少，迁移慢；HbAS同时有HbA和HbS，两条带。","answer":"HbA快带；HbSS慢带；HbAS快+慢两条带。","slide":18,"slideTitle":"AI精讲3：HbS聚集与电泳","pitfalls":"HbA一条快带；HbSS一条慢带；HbAS快+慢两条带。","kpId":"bc04_s0_18"},{"id":"bc04_ex16","no":16,"type":"简答","q":"胃蛋白酶水解IgG产生什么片段？与木瓜蛋白酶有何不同？","kp":"胃蛋白酶F(ab′)₂；木瓜蛋白酶2 Fab+Fc。","analysis":"胃蛋白酶在铰链区二硫键C端侧切割，产生双价F(ab′)₂和小片段；木瓜蛋白酶在N端侧切割，产生2个Fab和1个Fc。","answer":"胃蛋白酶→F(ab′)₂+小片段；木瓜蛋白酶→2 Fab+Fc。","slide":19,"slideTitle":"AI精讲4：IgG的Fab/Fc与酶切","pitfalls":"胃蛋白酶→F(ab′)₂；木瓜蛋白酶→2 Fab+Fc。","kpId":"bc04_s0_19"},{"id":"bc04_ex17","no":17,"type":"简答","q":"ELISA为什么能定量？","kp":"酶标抗体+底物显色；颜色深浅与含量相关。","analysis":"ELISA把抗原/抗体包被，加入样品和酶标抗体，洗去未结合物后加底物；酶催化显色，颜色深浅与目标物含量相关，用标准曲线定量。","answer":"酶标抗体+底物显色，颜色深浅反映含量，标准曲线定量。","slide":20,"slideTitle":"AI精讲5：ELISA与Western blot","pitfalls":"ELISA定量需要标准曲线；颜色深浅不是绝对量。","kpId":"bc04_s0_20"},{"id":"bc04_ex18","no":18,"type":"简答","q":"Western blot为什么要先电泳再转膜？","kp":"按分子量分离；转膜后抗体可及。","analysis":"SDS-PAGE按分子量分离蛋白，转膜把蛋白固定到膜上，便于抗体孵育和检测；这样既能看目标蛋白有无，也能看分子量。","answer":"电泳按分子量分离，转膜便于抗体检测并判断分子量。","slide":20,"slideTitle":"AI精讲5：ELISA与Western blot","pitfalls":"Western先电泳分离，再转膜，抗体才能检测目标条带。","kpId":"bc04_s0_20"},{"id":"bc04_ex19","no":19,"type":"简答","q":"肌肉收缩横桥循环中ATP水解和ATP结合各起什么作用？","kp":"水解驱动摆动；结合促解离。","analysis":"ATP水解驱动肌球蛋白头部摆动，拉细丝；新的ATP结合使肌球蛋白与肌动蛋白解离，循环才能继续。","answer":"ATP水解→摆动；ATP结合→解离。","slide":21,"slideTitle":"AI精讲6：肌肉收缩横桥循环","pitfalls":"ATP水解驱动摆动；ATP结合促进解离，不要反。","kpId":"bc04_s0_21"},{"id":"bc04_ex20","no":20,"type":"简答","q":"肌肉松弛时Ca²⁺和ATP如何变化？","kp":"Ca²⁺回收；ATP使横桥解离。","analysis":"Ca²⁺被钙泵回收到肌质网，肌钙蛋白释放Ca²⁺，原肌球蛋白回到阻断位置；ATP结合使肌球蛋白与肌动蛋白解离，肌肉松弛。","answer":"Ca²⁺回收+ATP结合使横桥解离→松弛。","slide":120,"slideTitle":"肌肉松弛","pitfalls":"松弛=Ca²⁺被回收+ATP结合使横桥解离。","kpId":"bc04_s0_120"},{"id":"bc04_ex21","no":21,"type":"简答","q":"HbS为什么会在低氧时聚集？","kp":"脱氧暴露疏水补丁；分子间聚集。","analysis":"HbS β6 Glu→Val，脱氧后疏水补丁暴露，分子间互相粘住，聚集成纤维；低氧促进脱氧，所以聚集和镰变加重。","answer":"低氧→脱氧HbS→疏水补丁暴露→聚集纤维→镰变。","slide":18,"slideTitle":"AI精讲3：HbS聚集与电泳","pitfalls":"HbS脱氧才聚集；氧合状态溶解度较好。","kpId":"bc04_s0_18"},{"id":"bc04_ex22","no":22,"type":"简答","q":"同源蛋白中保守残基说明什么？","kp":"共同起源；结构/功能关键位点。","analysis":"同源蛋白由共同祖先基因演化；保守残基多位于结构/功能关键位点，受选择压力保留，突变可能影响功能。","answer":"提示结构/功能重要位点，支持共同进化起源。","slide":124,"slideTitle":"六、蛋白质的结构与功能进化","pitfalls":"保守残基提示结构/功能重要位点，不是序列完全相同。","kpId":"bc04_s0_124"},{"id":"bc04_ex23","no":23,"type":"简答","q":"为什么Hb的P50比Mb大？","kp":"Hb低亲和/协同运输；Mb高亲和/储氧。","analysis":"Mb单体、单位点、无协同，P50约2 torr，亲和力高，适合储氧；Hb四聚体、有协同，P50约26 torr，亲和力较低，适合肺装载/组织卸氧。","answer":"Hb P50大（约26 torr），Mb P50小（约2 torr）；Hb适合运输，Mb适合储氧。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"Hb P50大=亲和力低；Mb P50小=亲和力高。","kpId":"bc04_s0_68"},{"id":"bc04_ex24","no":24,"type":"简答","q":"CO中毒为什么危险？","kp":"CO与Fe²⁺高亲和；占位+改变亲和力。","analysis":"CO与血红素Fe²⁺结合亲和力远高于O₂，占据O₂位点；同时使剩余亚基对O₂亲和力升高，O₂不易在组织释放，导致组织缺氧。","answer":"CO占位且提高剩余亚基O₂亲和力，组织缺氧。","slide":37,"slideTitle":"CO 的毒性作用","pitfalls":"CO既占位又提高剩余亚基O₂亲和力，双重导致组织缺氧。","kpId":"bc04_s0_37"},{"id":"bc04_ex25","no":25,"type":"名词","q":"解释名词：配体","kp":"配体定义；与蛋白质结合。","analysis":"配体是与蛋白质等大分子特定结合部位结合的原子、离子或分子；结合靠非共价/配位等相互作用。","answer":"与蛋白质结合部位结合的分子/离子。","slide":35,"slideTitle":"O2 与肌红蛋白的结合","pitfalls":"配体是被结合的分子/离子；结合部位是蛋白质上的区域。","kpId":"bc04_s0_16"},{"id":"bc04_ex26","no":26,"type":"名词","q":"解释名词：结合部位","kp":"蛋白质上与配体结合的区域。","analysis":"结合部位是大分子或膜蛋白上与配体发生特异结合的特定区域，决定结合特异性/亲和力。","answer":"蛋白质上与配体特异结合的区域。","slide":35,"slideTitle":"O2 与肌红蛋白的结合","pitfalls":"结合部位是蛋白质上的特定区域，不是配体本身。","kpId":"bc04_s0_17"},{"id":"bc04_ex27","no":27,"type":"名词","q":"解释名词：氧合曲线","kp":"pO₂-Y曲线；P50。","analysis":"以pO₂为横坐标、氧饱和度Y为纵坐标的曲线，用来描述蛋白对O₂的亲和力和协同性；Y=0.5时pO₂=P50。","answer":"pO₂对氧饱和度Y的曲线；P50是Y=0.5时的pO₂。","slide":46,"slideTitle":"肌红蛋白的氧结合曲线：双曲线与P50","pitfalls":"氧合曲线横轴pO₂、纵轴Y；P50是Y=0.5时的pO₂。","kpId":"bc04_s0_46"},{"id":"bc04_ex28","no":28,"type":"名词","q":"解释名词：Hill系数","kp":"协同性指标；nH=1无协同，>1正协同。","analysis":"Hill系数nH是Hill图斜率，衡量配体结合的协同性；nH=1无协同，nH>1正协同，Hb约2.8。","answer":"衡量协同性的指标；nH=1无协同，>1正协同。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"nH=1无协同，nH>1正协同；Hill系数不是结合位点数。","kpId":"bc04_s0_68"},{"id":"bc04_ex29","no":29,"type":"名词","q":"解释名词：协同性","kp":"一个配体结合影响后续配体结合。","analysis":"协同性是一个配体结合后改变同一蛋白其他结合部位对配体的亲和力；Hb结合O₂后正协同，曲线S形。","answer":"一个配体结合后改变其他位点亲和力的现象。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"协同性是一个配体改变其他位点亲和力；别构效应是更广的概念。","kpId":"bc04_s0_68"},{"id":"bc04_ex30","no":30,"type":"名词","q":"解释名词：Bohr效应","kp":"H⁺/CO₂降低Hb氧亲和力，曲线右移。","analysis":"pH降低或CO₂升高时，Hb结合H⁺稳定T态，O₂亲和力下降，曲线右移，促进组织释氧。","answer":"H⁺/CO₂升高→Hb曲线右移→释氧增加。","slide":73,"slideTitle":"Bohr 效应","pitfalls":"Bohr效应是H⁺/CO₂影响Hb对O₂亲和力，不是BPG。","kpId":"bc04_s0_73"},{"id":"bc04_ex31","no":31,"type":"计算","q":"蛋白质A和B各有一个配体X结合部位，Kd分别为10⁻⁶和10⁻⁹ mol/L。(1)哪个亲和力更高？(2)转换为Ka。","kp":"Kd越小亲和力越高；Ka=1/Kd。","analysis":"Kd是解离常数，越小表示结合越紧、亲和力越高；B的Kd=10⁻⁹更小，亲和力更高。Ka=1/Kd：A=10⁶ M⁻¹，B=10⁹ M⁻¹。","answer":"B亲和力更高；Ka(A)=10⁶ M⁻¹，Ka(B)=10⁹ M⁻¹。","slide":35,"slideTitle":"O2 与肌红蛋白的结合","pitfalls":"Kd越小亲和力越高；Ka=1/Kd，别把Kd和Ka方向记反。","kpId":"bc04_s0_68"},{"id":"bc04_ex32","no":32,"type":"简答","q":"HbA为什么能抑制HbS形成长纤维和镰状化？","kp":"HbA可加到HbS纤维末端，但缺少“粘性”突起，不能继续延长。","analysis":"去氧HbA有互补部位，能结合到HbS纤维末端；但HbA末端缺少继续堆叠的疏水“粘性”区，纤维不能延长，从而抑制镰状化。","answer":"HbA占据纤维末端但不能继续延长，抑制HbS纤维生长。","slide":88,"slideTitle":"HbS聚集成纤维状沉淀","pitfalls":"HbA占据纤维末端但不能继续延长；不是HbA直接分解纤维。","kpId":"bc04_s0_88"},{"id":"bc04_ex33","no":33,"type":"简答","q":"一个单克隆抗体只结合G-肌动蛋白、不结合F-肌动蛋白，说明抗原表位可能是什么？","kp":"G→F聚合时表位被埋藏。","analysis":"抗体只识别G-肌动蛋白，说明该表位在G→F聚合时被埋藏或构象改变，F-肌动蛋白中不可及。","answer":"该表位在G-肌动蛋白表面，聚合成F时被埋藏。","slide":119,"slideTitle":"肌球蛋白头与肌动蛋白丝结合","pitfalls":"G→F聚合时表位被埋藏/构象改变，所以抗体只认G。","kpId":"bc04_s0_119"},{"id":"bc04_ex34","no":34,"type":"计算","q":"Fab-半抗原复合体在25℃、pH7时Kd=5×10⁻⁷ mol/L，koff=120 s⁻¹。求ΔG°、Ka和kon。","kp":"ΔG°=RTlnKd；Ka=1/Kd；kon=koff/Kd。","analysis":"ΔG°=RTlnKd=8.314×298×ln(5×10⁻⁷)≈−35.9 kJ/mol；Ka=1/(5×10⁻⁷)=2×10⁶ M⁻¹；kon=koff/Kd=120/(5×10⁻⁷)=2.4×10⁸ M⁻¹s⁻¹。","answer":"ΔG°≈−35.9 kJ/mol；Ka≈2×10⁶ M⁻¹；kon≈2.4×10⁸ M⁻¹s⁻¹。","slide":35,"slideTitle":"O2 与肌红蛋白的结合","pitfalls":"ΔG=RTlnKd（负值）；Ka=1/Kd；kon=koff/Kd。","kpId":"bc04_s0_19"},{"id":"bc04_ex35","no":35,"type":"计算","q":"肺泡pO₂=100 torr时Hb的Y≈0.97，肌肉毛细血管pO₂=20 torr时Y≈0.25。一次循环Hb释放氧的比例约多少？","kp":"Y差=释放比例；Hb P50≈26 torr。","analysis":"肺Y=0.97，组织Y=0.25；释放比例=0.97−0.25=0.72，即约72%。","answer":"约72%（0.97−0.25）。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"释放比例=肺Y−组织Y，不是组织Y/肺Y。","kpId":"bc04_s0_68"},{"id":"bc04_ex36","no":36,"type":"计算","q":"Hb的P50=3.5 kPa、n=2.8，pO₂=13 kPa时Y约多少？若n=1.0呢？","kp":"Hill方程Y=pO₂ⁿ/(P50ⁿ+pO₂ⁿ)。","analysis":"pO₂/P50=3.714；3.714^2.8≈39.4；Y=39.4/(1+39.4)≈0.975。n=1时Y=13/(13+3.5)≈0.788。协同性使高pO₂下更饱和。","answer":"n=2.8时Y≈0.975；n=1时Y≈0.788。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"先算pO₂/P50，再取n次方；n=1时用双曲线。","kpId":"bc04_s0_68"},{"id":"bc04_ex37","no":37,"type":"简答","q":"接受BPG浓度低的输血，为什么可能影响组织供氧？","kp":"BPG低→Hb曲线左移→释氧减少。","analysis":"BPG稳定T态、促进卸氧；BPG低时Hb更偏R态，曲线左移，P50降低，组织处释放O₂减少，可能供氧不足。","answer":"BPG低→曲线左移→组织释氧减少。","slide":78,"slideTitle":"2,3-BPG与血红蛋白β链的结合","pitfalls":"BPG低→曲线左移→组织释氧减少。","kpId":"bc04_s0_78"},{"id":"bc04_ex38","no":38,"type":"简答","q":"Scatchard作图以N/[L]对N作图，斜率和横截距分别代表什么？","kp":"Scatchard：斜率−Ka，横截距n。","analysis":"Scatchard方程N/[L]=Ka(n−N)；斜率=−Ka，横截距=n（结合位点数），可求亲和力和位点数。","answer":"斜率=−Ka；横截距=n（结合位点数）。","slide":68,"slideTitle":"血红蛋白的实际氧合曲线与Hill系数","pitfalls":"Scatchard斜率=−Ka，横截距=n；不要写反。","kpId":"bc04_s0_68"},{"id":"bc04_ex39","no":39,"type":"简答","q":"同源蛋白中的保守残基通常说明什么？","kp":"共同起源；结构/功能关键位点。","analysis":"同源蛋白由共同祖先基因演化；保守残基受选择压力，常位于血红素结合、亚基界面等关键位点。","answer":"保守残基提示关键结构/功能位点，支持共同起源。","slide":26,"slideTitle":"AI进化1：同源蛋白与保守残基","kpId":"bc04_s0_26"},{"id":"bc04_ex40","no":40,"type":"简答","q":"HbS的单个氨基酸突变为什么能导致疾病？","kp":"β6 Glu→Val；电荷/溶解度改变；脱氧聚集。","analysis":"Glu→Val少一个负电荷，HbS脱氧时疏水补丁暴露，分子间聚集成纤维，红细胞镰变。","answer":"β6 Glu→Val→脱氧聚集→镰状细胞贫血。","slide":27,"slideTitle":"AI进化2：一个突变怎样改变功能","kpId":"bc04_s0_27"},{"id":"bc04_ex41","no":41,"type":"简答","q":"基因复制在蛋白质进化中有什么作用？","kp":"冗余拷贝；突变分化；新功能。","analysis":"基因复制产生冗余拷贝，一个拷贝维持原功能，另一个可积累突变并分化出新功能，形成蛋白质家族。","answer":"提供冗余拷贝，突变后可分化出新功能。","slide":28,"slideTitle":"AI进化3：基因复制、突变与选择","kpId":"bc04_s0_28"}],"kpMap":{"bc04_s0_30":{"label":"Mb/血红素/氧合","slide":30},"bc04_s0_52":{"label":"Hb/T→R/协同","slide":52},"bc04_s0_10":{"label":"Bohr/BPG/CO2","slide":10},"bc04_s0_83":{"label":"分子病/HbS","slide":83},"bc04_s0_90":{"label":"免疫/IgG/ELISA","slide":90},"bc04_s0_21":{"label":"肌肉/横桥","slide":21},"bc04_s0_26":{"label":"进化/同源","slide":26},"bc04_s0_141":{"label":"训练/综合","slide":141}},"bank":[{"id":"bc04_bank_fill_1","kind":"fill","no":1,"src":"朱圣庚4版配套题库·第4章·填空题","a":"性质；功能","e":"正确答案：性质；功能。对应知识点：原书页：第4章 蛋白质的生物学功能。本章主线：配体结合、协同/别构、分子病、免疫、肌肉、进化。；蛋白质功能依赖构象变化和与其他分子的相互作用。。","q":"蛋白质的分子结构决定蛋白质的______和______。"},{"id":"bc04_bank_fill_2","kind":"fill","no":2,"src":"朱圣庚4版配套题库·第4章·填空题","a":"协同；别构","e":"正确答案：协同；别构。对应知识点：原书页：第4章 蛋白质的生物学功能。本章主线：配体结合、协同/别构、分子病、免疫、肌肉、进化。；蛋白质功能依赖构象变化和与其他分子的相互作用。。","q":"血红蛋白（Hb）与氧结合的过程呈现______效应，是通过Hb的______现象实现的。"},{"id":"bc04_bank_fill_3","kind":"fill","no":3,"src":"朱圣庚4版配套题库·第4章·填空题","a":"ATP","e":"正确答案：ATP。对应知识点：难点精讲3：横桥循环与ATP（三磷酸腺苷）。ATP（三磷酸腺苷）结合→分离。；水解→复位蓄能。。","q":"肌球蛋白本身具有______酶的活性，所以当ATP释放能量时，就引起肌肉收缩。"},{"id":"bc04_bank_fill_4","kind":"fill","no":4,"src":"朱圣庚4版配套题库·第4章·填空题","a":"糖基","e":"正确答案：糖基。对应知识点：肌红蛋白辅助细胞内氧转运。Mb（肌红蛋白）在细胞内促进O₂从膜向线粒体扩散。；Mb（肌红蛋白） P50（半饱和氧分压）约2 torr，高亲和，肌肉内多处于高饱和。。","q":"凝集素能专一地识别细胞表面的______并与之结合，从而使细胞与细胞相互凝集。"},{"id":"bc04_bank_fill_5","kind":"fill","no":5,"src":"朱圣庚4版配套题库·第4章·填空题","a":"免疫","e":"正确答案：免疫。对应知识点：AI串讲3：IgG（免疫球蛋白G）与免疫检测。IgG（免疫球蛋白G）=2条重链γ+2条轻链κ/λ，二硫键连接。；Fab（抗原结合片段）=VH（重链可变区）+CH1+VL（轻链可变区）+CL（轻链恒定区），含CDR（互补决定区），结合抗原。。","q":"抗体就是______球蛋白。"},{"id":"bc04_bank_fill_6","kind":"fill","no":6,"src":"朱圣庚4版配套题库·第4章·填空题","a":"信号；肽胰岛素原；C（连接）","e":"正确答案：信号；肽胰岛素原；C（连接）。对应知识点：免疫球蛋白G（IgG）的结构。IgG（免疫球蛋白G）=2重链(γ)+2轻链(κ/λ)，Y形；VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合抗原。","q":"胰岛素是胰岛β-细胞分泌的，它是由前胰岛素原经专一性蛋白酶水解，失去N端的______成为______ 。\n再经类胰蛋白酶和类羧肽酶的作用失去______肽，形成具有生物活性的胰岛素。"},{"id":"bc04_bank_fill_7","kind":"fill","no":7,"src":"朱圣庚4版配套题库·第4章·填空题","a":"氧分压；二氧化碳分压；氢离子浓度；2,3-二磷酸甘油酸","e":"正确答案：氧分压；二氧化碳分压；氢离子浓度；2,3-二磷酸甘油酸。对应知识点：过程版4：测Hb（血红蛋白）氧亲和力实验设计。样品：纯化Hb（血红蛋白），控制温度、pH、离子强度。；测Y：不同pO₂平衡后测吸收光谱，计算氧饱和度。。","q":"影响血红蛋白与氧结合的因素有______、______、______和______等。"},{"id":"bc04_bank_fill_8","kind":"fill","no":8,"src":"朱圣庚4版配套题库·第4章·填空题","a":"肌红蛋白","e":"正确答案：肌红蛋白。对应知识点：镰刀状细胞贫血病。镰刀状细胞贫血病 镰刀状细胞贫血病（sickle-cell anemia ）是最早 被认识的一种分子病；这种病在非洲某些地区十分流 行（高达40% ），它是由于遗传基因的突变导致血 红蛋白分子中氨基酸残基被改变造成的。","q":"生活在海洋中的哺乳动物能长时间潜水，是由于它们的肌肉中含有大量的______以储存氧气。"},{"id":"bc04_bank_fill_9","kind":"fill","no":9,"src":"朱圣庚4版配套题库·第4章·填空题","a":"2；2；2","e":"正确答案：2；2；2。对应知识点：免疫球蛋白G（IgG）的结构。IgG（免疫球蛋白G）=2重链(γ)+2轻链(κ/λ)，Y形；VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合抗原。","q":"免疫球蛋白分子是由______条一样的轻链和______条一样的重链组成，它们之间共有______对二硫键\n来维持整个分子结构。"},{"id":"bc04_bank_fill_10","kind":"fill","no":10,"src":"朱圣庚4版配套题库·第4章·填空题","a":"疏水氨基酸；盐键和氢键","e":"正确答案：疏水氨基酸；盐键和氢键。对应知识点：肌红蛋白的结构：珠蛋白折叠与血红素口袋。肌红蛋白=单体+1个血红素+1个O₂位点；二级结构以8段α-螺旋为主，无β折叠。","q":"蛋白质亚基之间存在界面。界面的大部分是由______组成。亚基之间主要的化学作用力是______。"},{"id":"bc04_bank_judge_1","kind":"judge","no":1,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"生物合成胰岛素时，首先合成它的前体-前胰岛素原，它是单链的。","q":"胰岛素的生物合成途径是先分别合成A、B两条链，然后通过S-S键相连。（  ）"},{"id":"bc04_bank_judge_2","kind":"judge","no":2,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"对一定的氧压而言，肌红蛋白与氧的亲和力较血红蛋白强。","q":"血红蛋白的α-链、β-链和肌红蛋白的肽链在三级结构上很相似，所以它们都有结合氧的能力。血红蛋白\n与氧的亲和力较肌红蛋白更强。（  ）"},{"id":"bc04_bank_judge_3","kind":"judge","no":3,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"血红蛋白是输氧蛋白，而肌红蛋白主要是捕获氧、储藏氧。","q":"血红蛋白和肌红蛋白的功能都是运输氧。（  ）"},{"id":"bc04_bank_judge_4","kind":"judge","no":4,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：血红蛋白的两种构象态。血红蛋白的两种构象态 血红蛋白有两种主要构象态，一种是T 态即紧张 态（tense state ），另一种是R 态即松弛态 （relaxed state ）；O2 对R 态的亲和力明显地高于 对T 态的亲和力，并且O2 的结合更稳定了R 态。","q":"GSH分子中含有-SH基，故能参与体内一些氧化还原反应。（  ）"},{"id":"bc04_bank_judge_5","kind":"judge","no":5,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"蛋白质的四级结构是指数条具有独立的三级结构的多肽链通过非共价键相互连接而成的聚合体结\n构。在具有四级结构的蛋白质中，每一条具有三级结构的肽链称为亚基或亚单位，缺少一个亚基或亚基单\n独存在都不具有活性。四级结构涉及亚基在整个分子中的空间排布以及亚基之间的相互关系。","q":"具有四级结构的蛋白质，当它的每个亚基单独存在时仍能保持蛋白质原有的生物活性。（  ）"},{"id":"bc04_bank_judge_6","kind":"judge","no":6,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"生活在空气稀薄的高山地区的人比平地上的人血液中2,3-DPG的浓度高，这样使为数不多的氧合血\n红蛋白分子尽量释放氧，以满足组织对氧的需要。","q":"生活在空气稀薄的高山地区的人和生活在平地上的人比较，高山地区的人血液中2,3-二磷酸甘油酸\n（2,3-DPG）的浓度较低。（  ）"},{"id":"bc04_bank_judge_7","kind":"judge","no":7,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：免疫球蛋白G（IgG）的结构。IgG（免疫球蛋白G）=2重链(γ)+2轻链(κ/λ)，Y形；VH（重链可变区）+VL（轻链可变区）=可变区，CDR（互补决定区）结合抗原。","q":"免疫球蛋白是一种糖蛋白，它由两条重链和两条轻链组成。（  ）"},{"id":"bc04_bank_judge_8","kind":"judge","no":8,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：血红蛋白的四级结构：α₂β₂与四个血红素。血红蛋白=α₂β₂四聚体，4个血红素/4个O₂位点；每个亚基类似肌红蛋白的三级结构。","q":"人血红蛋白分离成二个αβ-二聚体后，其与氧的结合类似肌红蛋白。（  ）"},{"id":"bc04_bank_judge_9","kind":"judge","no":9,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"氧与血红蛋白血红素中的二价铁结合，而二氧化碳与血红蛋白4个亚基的N端氨基结合。","q":"在生理条件下，氧和二氧化碳均与血红蛋白血红素中的二价铁结合。（  ）"},{"id":"bc04_bank_judge_10","kind":"judge","no":10,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：血红蛋白的别构效应。血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质；血红蛋白的氧合具有 正协同同促效应，即一个O2 的结合促进同一分子 其它亚基与O2 的结合。","q":"多数寡聚蛋白质分子其亚基的排列是对称的，对称性是蛋白质分子四级结构的最重要的性质之一。\n（  ）"},{"id":"bc04_bank_judge_11","kind":"judge","no":11,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"组蛋白是染色体基本结构蛋白，因富含碱性氨基酸精氨酸和赖氨酸而呈碱性，可与酸性的DNA紧\n密结合。","q":"组蛋白是一类碱性蛋白质，它含有很多的组氨酸。（  ）"},{"id":"bc04_bank_judge_12","kind":"judge","no":12,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"蛋白质中一个氨基酸残基的改变，不一定会引起蛋白质结构的显著变化。这要看氨基酸在肽链中的\n具体位置。例如血红蛋白C（HbC），β链中赖氨酸被谷氨酸取代，但是依旧能发挥血红蛋白的作用。而血\n红蛋白S（HbS），镰刀状细胞红蛋白，β链的第6位谷氨酸被缬氨酸所代替，形成一个不溶的长柱形螺旋纤\n维束，使红细胞扭旋成镰刀形，携氧能力也下降。","q":"蛋白质中一个氨基酸残基的改变，必定引起蛋白质结构的显著变化。（  ）"},{"id":"bc04_bank_judge_13","kind":"judge","no":13,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"血红蛋白分子近似球形，是一个四聚体蛋白质，由4个多肽亚基组成，每一亚基缔合有一个血红素\n辅基。肌红蛋白只有一、二、三级结构，无四级结构。","q":"血红蛋白和肌红蛋白具有相同的生物学功能，因此它们具有相同的空间结构。（  ）"},{"id":"bc04_bank_judge_14","kind":"judge","no":14,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：血红蛋白的别构效应。血红蛋白的别构效应 血红蛋白是一个四聚体蛋白，它与肌红蛋白相 比，出现了一些新的性质；血红蛋白的氧合具有 正协同同促效应，即一个O2 的结合促进同一分子 其它亚基与O2 的结合。","q":"血红蛋白与肌红蛋白均为氧载体，前者是一个典型的别构（或变构）蛋白，因而与氧结合过程中呈现\n协同效应，而后者却不是。（  ）"},{"id":"bc04_bank_judge_15","kind":"judge","no":15,"src":"朱圣庚4版配套题库·第4章·判断题","a":"对","e":"正确答案：对。对应知识点：BPG（2,3-二磷酸甘油酸） 的生理作用。BPG（2,3-二磷酸甘油酸） 的生理作用 人的某些生理性或病理性缺氧可以通过红细胞 中BPG 浓度的升高而代偿；当正常人在短时间内 由海平面上升到4500m 高的高山上时，红细胞中 的BPG（2,3-二磷酸甘油酸） 浓度几个小时后就开始上升，两天内可由 4.5mmol/L 增加到7.5mmol/L ，使氧的释放量增大。","q":"镰状细胞贫血症患者红细胞内的2,3-BPG的浓度通常比正常人高。（  ）"},{"id":"bc04_bank_judge_16","kind":"judge","no":16,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"血红蛋白与细胞色素C都含有血红素辅基，前者是运输氧，后者血红素是用于传递电子，因此生物\n学本质截然不同。","q":"血红蛋白和细胞色素C的辅基相同，前者运输氧，后者用于组成呼吸链。它们的生物学功能本质是相\n同的。（  ）"},{"id":"bc04_bank_judge_17","kind":"judge","no":17,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"肌球蛋白（myosin）是一种很长的棒状分子，有6条多肽链组成。原肌球蛋白（protomyosin）也是\n一种纤维状蛋白质。由两条不同的螺旋肽链互相缠绕而形成超螺旋。","q":"肌球蛋白、原肌球蛋白及γ球蛋白都是由几条多肽链组成的球形分子。（  ）"},{"id":"bc04_bank_judge_18","kind":"judge","no":18,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"抗体介导免疫细胞对抗原的作用，不具有直接杀伤作用。","q":"抗体在体内除了识别抗原与结合抗原作用外还具有杀伤抗原的作用。（  ）"},{"id":"bc04_bank_judge_19","kind":"judge","no":19,"src":"朱圣庚4版配套题库·第4章·判断题","a":"错","e":"血液凝结时，血纤维蛋白（纤维蛋白原）α2β2γ2从两条α-链和两条β-链的N端各断裂一个特定的肽","q":"血液凝结时，血纤维蛋白的几条可溶性肽链随时可以通过非共价键的高度聚合成为不溶性的血纤维蛋\n白的凝块。（  ）"},{"id":"bc04_bank_term_1","kind":"term","no":1,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"蛋白质的四级结构是指蛋白质分子中各亚基的空间排布及亚基接触部位的布局和相互作用，即寡聚蛋\n白中各亚基的空间排布。蛋白质亚基之间主要通过疏水作用、氢键、离子键、范德华力等作用力形成四级\n结构，其中最主要的是疏水作用。","e":"","q":"蛋白质四级结构","term":"蛋白质四级结构"},{"id":"bc04_bank_term_2","kind":"term","no":2,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"蛋白质的别构作用是指一些蛋白质受某些因素影响，其一级结构不变，空间构象发生一定的变化，导\n致其生物功能改变的现象。不直接涉及蛋白质活性的物质，结合于蛋白质活性部位以外的其它部位（别构\n部位），引起蛋白质分子的构象变化，从而导致蛋白质活性改变。","e":"","q":"蛋白质的别构作用","term":"蛋白质的别构作用"},{"id":"bc04_bank_term_3","kind":"term","no":3,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"（1）抗原是指凡能刺激动物机体产生抗体并能特异地与这种抗体结合的物质。\n（2）抗体又称免疫球蛋白，是一类特殊的蛋白质，也是机体内最复杂的分子，它以巨大的多样性识别着外\n部世界纷繁的抗原结构。","e":"","q":"抗原和抗体","term":"抗原和抗体"},{"id":"bc04_bank_term_4","kind":"term","no":4,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"同源蛋白质是指存在于不同物种、起源相同、序列和功能类似的蛋白质，例如人与牛的血红蛋白。","e":"","q":"同源蛋白质","term":"同源蛋白质"},{"id":"bc04_bank_term_5","kind":"term","no":5,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"同功蛋白质是指不同种属来源的执行同种生物学功能的蛋白质。它们的分子组成基本相同，但有差\n异。同功蛋白质的氨基酸组成可区分为两部分：一部分是不变的氨基酸顺序，它决定蛋白质的空间结构与\n功能，各种同功蛋白质的不变氨基酸顺序完全一致；另一部分是可变的氨基酸顺序，这部分是同功蛋白质\n的种属差异的体现。","e":"","q":"同功蛋白质","term":"同功蛋白质"},{"id":"bc04_bank_term_6","kind":"term","no":6,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"镰刀形细胞贫血病（sickle-cell anemia）是指病人的血红蛋白分子与正常人血红蛋白分子的主要差异在\nβ-链上第6位氨基酸残基，正常人为谷氨酸，病人则为缬氨酸的一种疾病。缬氨酸侧链与谷氨酸侧链的性质\n和在蛋白质分子结构形成中的作用完全不同，所以导致病人的血红蛋白结构异常，红细胞呈镰刀状，当红\n细胞脱氧时，这种镰刀状细胞明显增加。","e":"","q":"镰刀形细胞贫血病（sickle-cell anemia）","term":"镰刀形细胞贫血病（sickle-cell anemia）"},{"id":"bc04_bank_term_7","kind":"term","no":7,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"分子病是指由于基因突变引起的某个功能蛋白的某一个或几个氨基酸残基发生了遗传性替代，从而导\n致整个分子的三维结构发生改变，功能部分或全部丧失从而引发的疾病。镰刀状细胞贫血病是最早被认识\n的一种分子病。","e":"","q":"分子病","term":"分子病"},{"id":"bc04_bank_term_8","kind":"term","no":8,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"协同效应（cooperativity）是指一个寡聚体蛋白质的一个亚基与其配体结合后，能影响此寡聚体中另一\n个亚基与配体结合能力的现象。如果是促进作用则称为正协同效应，如：带氧的Hb亚基协助不带氧亚基结\n合氧；如果是抑制作用则称为负协同效应。","e":"","q":"协同效应（cooperativity）","term":"协同效应（cooperativity）"},{"id":"bc04_bank_term_9","kind":"term","no":9,"src":"朱圣庚4版配套题库·第4章·名词解释","a":"波尔效应（Bohreffect）是指增加CO2分压，提高CO2的浓度，能够提高血红蛋白亚基的协同效应，降\n低血红蛋白对氧的亲和力。并且发现增加H＋离子浓度或降低pH值，也能增加亚基协同效应，促进血红蛋\n白释放氧。反之高浓度的O2或者增加O2的分压，都将促进脱氧血红蛋白分子释放H＋和CO2这些相互有关的\n现象。波尔效应主要是描述H＋浓度或pH值及CO2分压的变化，对血红蛋白结合氧的影响，它具有重要的生\n理意义。","e":"","q":"波尔效应（Bohreffect）","term":"波尔效应（Bohreffect）"},{"id":"bc04_bank_short_1","kind":"short","no":1,"src":"朱圣庚4版配套题库·第4章·问答题","a":"分子病是指由于基因突变引起的某个功能蛋白的某一个或几个氨基酸残基发生了遗传性替代，从而导\n致整个分子的三维结构发生改变，功能部分或全部丧失从而引发的疾病。\n镰刀形红细胞贫血症的病因是β-球蛋白基因发生点突变，引起血红蛋白β-链六位的谷氨酸被替换为缬氨\n酸。此种变化导致血红蛋白构象变化，分子间聚合，最终使红细胞变形。","e":"","q":"为什么镰刀形红细胞贫血症是一种分子病？"},{"id":"bc04_bank_short_2","kind":"short","no":2,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）血清清蛋白pI＝4.9，血红蛋白pI＝6.8（4.9＋6.8）/2＝5.85。\n在pH5.85时电泳，分离最为有效，点样时样品点在中间，血清清蛋白向阳极移动，而血红蛋白向阴极移\n动。\n（2）肌红蛋白pI＝7.0，胰凝乳蛋白酶原pI＝9.5（7.0＋9.5）/2＝8.25。\n在pH8.25时电泳，分离最为有效，点样时样品点在中间，肌红蛋白向阳极移动，而胰凝乳蛋白酶原向阴极\n移动。\n（3）卵清蛋白pI＝4.6，血清清蛋白pI＝4.9，脲酶pI＝5.0。在pH4.9时电泳，分离最为有效，样品点在中\n间，血清清蛋白留在原点，卵清蛋白向阳极移动，脲酶向阴极移动。","e":"","q":"下列蛋白质的混合物在什么pH时电泳，分离最为有效？\n（1）血清清蛋白和血红蛋白；\n（2）肌红蛋白和胰凝乳蛋白酶原；\n（3）卵清蛋白、血清清蛋白和脲酶。"},{"id":"bc04_bank_short_3","kind":"short","no":3,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）血红蛋白是红细胞内的特殊蛋白质，主要作用是运输O2和CO2。血红蛋白可以与O2结合，形成氧\n合血红蛋白，然后运输到机体需要的组织器官，供机体组织器官产生能量。同时又把组织器官产生的\nCO2，通过血红蛋白结合形成碳氧血红蛋白，运输到肺部排出体外。\n（2）煤气中毒的主要原因是煤气中的一氧化碳与血红蛋白结合的能力远强于氧气，导致一氧化碳和血红蛋\n白结合后，血红蛋白失去了运输氧的功能，使患者因缺氧而死。","e":"","q":"简述煤气中毒的主要原因。"},{"id":"bc04_bank_short_4","kind":"short","no":4,"src":"朱圣庚4版配套题库·第4章·问答题","a":"血红蛋白和肌红蛋白都具有氧合功能，但它们的氧合曲线不同的原因主要有：\n（1）血红蛋白由两条α-链和两条β-链组成。血红蛋白的α-链和β-链与肌红蛋白的构象十分相似，尤其是β-\n链。它们所含的氨基酸种类、数目、氨基酸的排列顺序都有较大的差异，但它们的三级结构十分相似。因\n此它们都具有基本的氧合功能。\n（2）但血红蛋白是一个四聚体，它的分子结构要比肌红蛋白复杂得多。因此除了运输氧以外，还有肌红蛋\n白所没有的功能。如运输质子和CO2。\n（3）血红蛋白的氧合曲线为S形，而肌红蛋白的氧合曲线为双曲线。S形曲线说明血红蛋白与氧的结合具有\n协同性。脱氧血红蛋白分子中，它的四条多肽链的C端都参与了盐桥的形成。由于多个盐桥的存在，使它\n处于受约束的强制状态。当一个氧分子冲破了某种阻力和血红蛋白的一个亚基结合后，这些盐桥被打断，\n使得亚基的构象发生改变，从而引起邻近亚基的构象也发生改变，这种构象的变化就更易于和氧的结合，\n并继续影响第三个、第四个亚基与氧的结合，故表现出S型的氧合曲线。","e":"","q":"血红蛋白和肌红蛋白都具有氧合功能，但它们的氧合曲线不同，为什么？"},{"id":"bc04_bank_short_5","kind":"short","no":5,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）别构效应的定义\n别构效应是指生物体中具有1个以上亚基的蛋白质，在不同生理过程中，当其中一个亚基与小分子物质结合\n后，不仅该亚基的立体结构发生变化，而且随即引起其他亚基在立体结构上发生相应变化，从而最终改变\n蛋白质生物活性的现象。别构效应是生物体代谢调节的重要方式之一。\n（2）以血红蛋白为例说明别构效应与蛋白质功能的关系\n①血红蛋白有四个亚基，它们都是多次折叠卷曲起来的肽链。两个为α-链，两个为β-链，以α2β2表示。\n②脱氧血红蛋白由于分子内可形成八对盐桥，分子的构象受到约束，较为稳定，因而和氧的结合能力弱。\n③当一个α-亚基和O2结合后部分盐桥被破坏，某些氨基酸发生移位，与氧结合点随即暴露出来，使得一个\nβ-亚基构象改变，对O2的亲和力增加。\n④而当这一对αβ-亚基与O2结合后，就增加另一对αβ-亚基构象改变的程度和对氧的亲和力，使得后一对亚\n基与氧反应的平衡常数增加五倍。氧合后，血红蛋白构象发生很大变化，使得氧合能力大大提高。","e":"","q":"什么叫别构效应？以血红蛋白为例说明别构效应与蛋白质功能的关系。"},{"id":"bc04_bank_short_6","kind":"short","no":6,"src":"朱圣庚4版配套题库·第4章·问答题","a":"蛋白质四级结构具有结构和功能上的优越性：\n（1）增强结构稳定性。蛋白质表面与溶剂水相互作用常不利于稳定，亚基缔合使蛋白质表面积与体积的比\n值降低，增强蛋白质结构的稳定性。\n（2）提高遗传经济性和效率。编码一个同多聚蛋白质的单体所需的DNA比编码一条相对分子质量相同的多\n肽链要少，因此蛋白质单体的寡聚体缔合在遗传上是经济的。\n（3）使催化基团汇集在一起。许多寡聚酶可使不同亚基上的催化基团汇集在一起形成完整的催化部位。例\n如，细菌谷氨酰胺合成酶的活性部位是由相邻的亚基对形成的，解离的单体无活性。\n（4）具有协同性和别构效应。大多数寡聚蛋白质借助亚基相互作用调节其生物活性，如酶的催化活性。多\n亚基蛋白质一般具有多个结合部位，配体分子结合到结合部位对其他部位产生的影响（如改变亲和力或催\n化能力）称为别构效应。","e":"","q":"试说明蛋白质四级结构具有结构和功能上的优越性。"},{"id":"bc04_bank_short_7","kind":"short","no":7,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）白蛋白的作用\n①人体血清白蛋白在血液蛋白中的含量极高，约为50%～60%，而且它也是血浆蛋白中相对分子质量较低\n的一种蛋白质。因此，它对血液渗透压的贡献高达80%。\n②此外白蛋白还是机体中的储存蛋白，并且可以和许多种类的疏水性小分子结合，对这些小分子起到负载\n和运输的作用。\n（2）白蛋白含量过低的影响及原因\n①白蛋白在血液中含量过低，最明显的后果是造成患者的休克。因为血液的渗透压由于白蛋白的减少而降\n低。\n②白蛋白含量过低和一些疾病及营养不良密切相关。","e":"","q":"人体血液中的白蛋白主要起什么作用？白蛋白含量过低会造成什么影响？为什么？"},{"id":"bc04_bank_short_8","kind":"short","no":8,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）血红蛋白氧饱和度与氧分压关系曲线的特征\n氧离曲线表示氧分压与血氧饱和度关系的曲线，以氧分压（PO2）值为横坐标，相应的血氧饱和度为纵坐\n标。协同效应、波尔效应和别构效应三者使血红蛋白的氧合曲线呈S形：\n①因为血红蛋白和氧结合的别构效应影响其它底物的结合。血红蛋白有四个亚基，可以结合四个氧分子，\n而由于其结构没有结合氧气的血红蛋白是排斥氧分子的，第一个氧分子结合较困难，所以第一段较平缓。\n②第一个氧分子结合以后和与其结合的亚基相互作用，而此作用力通过此亚基传播到其它亚基，使得其结\n构变得利于氧分子结合，第二三个氧分子结合较易，所以第二段很陡。\n③第四个氧分子的结合又变得困难，但一旦四个氧分子都结合以后，结构反而又趋稳定，所以第三段又平\n缓。所以头尾两段氧气结合难，但一旦结合就不容易脱离；而中间这一段氧气结合容易，但脱离也容易。\n（2）生理意义\n在肺部，p（O2）比较高，血红蛋白被饱和；在组织中，p（O2）降低，S形的氧合曲线加大血红蛋白的卸\n氧量，使血红蛋白的输氧能力达到最高效率，能够更好完成运输氧的功能。","e":"","q":"血红蛋白氧饱和度与氧分压关系曲线的特征如何？有何生理意义？"},{"id":"bc04_bank_short_9","kind":"short","no":9,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）胰岛素分中的A链和B链并不代表两个亚基。\n（2）因为亚基最重要的特征是其本身具有特定的空间构象，而胰岛素的单独的A链或B链都不具有特定的空\n间构象，所以说胰岛素分中的A链和B链并不代表两个亚基。","e":"","q":"胰岛素分子中包含A链和B链，是否代表有两个亚基？为什么？"},{"id":"bc04_bank_short_10","kind":"short","no":10,"src":"朱圣庚4版配套题库·第4章·问答题","a":"Hb亚基分开后不具有协同性的原因主要有：\n（1）血红蛋白是由两条α-链和两条β-链构成的四聚体，分子外形近似球状，4个亚基分别在四面体的四个角\n上，每个亚基都和肌红蛋白类似。血红蛋白是变构蛋白，其氧合曲线是S形曲线，只要氧分压有一个较小\n的变化即可引起氧饱和度的较大改变。\n（2）血红蛋白与氧结合时，α-和β-链都发生了转动，引起4个亚基问的接触点上的变化。两个α-亚基相互接\n近，两个β-亚基则离开。当一个亚基与氧结合后，会引起四级结构的变化，使其他亚基对氧的亲和力增\n加，结合加快；反之，一个亚基与氧分离后，其他亚基也易于解离。这有利于运输氧，肺中的氧分压只需\n比组织中稍微高一些，血红蛋白就可以完成运氧工作。血红蛋白的亚基分开以后就失去了亚基间的协同作\n用。","e":"","q":"Hb亚基分开后不具有协同性的原因是什么？"},{"id":"bc04_bank_short_11","kind":"short","no":11,"src":"朱圣庚4版配套题库·第4章·问答题","a":"胰岛素是在胰岛β-细胞内合成的一种多肽激素。胰岛素原的激活过程如下：\n（1）最初合成的是一个比胰岛素分子大1倍多的单肽链，称为前胰岛素原，它是胰岛素原的前体，而胰岛素\n原是胰岛素的前体。\n（2）胰岛素原是前胰岛素原去掉N端的信号肽形成的，被运送到高尔基体贮存。\n（3）当机体需要活性胰岛素时，在特异的肽酶作用下，去掉多肽链中间的一段称为C肽的片段转变为具有\n活性的胰岛素。","e":"","q":"简述胰岛素原的激活过程。"},{"id":"bc04_bank_short_12","kind":"short","no":12,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）蛋白质的氨基酸排列顺序和核酸的核苷酸排列顺序之间的关系\n①蛋白质的一级结构是由基因编码的。蛋白质的氨基酸排列顺序总体而言是由基因中的核苷酸排列顺序所\n决定的。\n②然而，在有相当数量的基因在转录成mRNA后，以及在翻译为肽链后，在这两个不同水平上还存在着后\n加工，包括转录后加工和翻译后加工，因此成熟蛋白质中的氨基酸顺序和基因中的核苷酸顺序不一定是对\n应的。\n（2）蛋白质的氨基酸排列顺序和立体结构、生物功能之间的关系\n①蛋白质的立体结构在很大程度上由氨基酸序列所决定，但是也不能忽略环境因素对蛋白质立体结构的影\n响，如疯牛病发生时，相同氨基酸顺序的肽链却产生了不同的立体结构。\n②蛋白质的生物功能与蛋白质的立体结构密切相关，在通常的生理条件下，可以认为蛋白质的氨基酸顺序\n决定了蛋白质的立体结构，进而决定了蛋白质的生物学功能。","e":"","q":"蛋白质的氨基酸排列顺序和核酸的核苷酸排列顺序有怎样的关系？蛋白质的氨基酸排列顺序和它们的\n立体结构、生物功能有什么关系？"},{"id":"bc04_bank_short_13","kind":"short","no":13,"src":"朱圣庚4版配套题库·第4章·问答题","a":"（1）氨基酸结构的共性\n除脯氨酸外都是α-氨基酸，即在α-碳原子上有一个氨基，氨基酸结构如图2-4-1所示包含两部分，不同氨基\n酸的区别在于R基团不同。\n图2-4-1\n（2）Val、Glu的生理电荷差异\n①Val的R基团为非极性，Val属于疏水性氨基酸；\n②Glu侧链R基团生理条件下带负电荷，Glu属于亲水性氨基酸。\n（3）蛋白质中保守氨基酸残基的重要性（以镰状细胞贫血病为例）\n①正常的血红蛋白是由两条141个氨基酸残基的α-链和两条146个氨基酸残基的β-链构成的四聚体，但镰状\n细胞贫血症患者血红蛋白分子的β-链第6位的氨基酸残基的谷氨酸被缬氨酸所取代（亲水氨基酸变成了疏水\n氨基酸）。\n②由于带负电的极性亲水谷氨酸被不带电的非极性疏水缬氨酸所代替，致使血红蛋白的溶解度下降。在氧\n张力低的毛细血管区，导致细胞扭曲成镰状。","e":"","q":"氨基酸结构的共性，Val、Glu的生理电荷差异，以镰状细胞贫血病为例讨论蛋白质中保守氨基酸残基\n的重要性。"},{"id":"bc04_bank_mcq_1","kind":"mcq","no":1,"src":"朱圣庚4版配套题库·第4章·选择题","a":"A","e":"正确答案：A．一些侧链基团的暴露。对应知识点：血红蛋白氧合时的T→R构象转变。T态=去氧低亲和，R态=氧合高亲和；O₂→Fe²⁺入平面→His F8/F螺旋移动。","q":"蛋白质变性伴有的结构变化是（  ）。","o":["A．一些侧链基团的暴露","B．肽键的断裂","C．氨基酸排列顺序的改变","D．氨基酸残基的化学修饰"]},{"id":"bc04_bank_mcq_2","kind":"mcq","no":2,"src":"朱圣庚4版配套题库·第4章·选择题","a":"A","e":"正确答案：A．破坏氢键。对应知识点：骨骼肌的相关蛋白质。骨骼肌的相关蛋白质 除骨骼肌的主要蛋白质外，还有多种蛋白质在 维持肌肉结构和调节肌肉收缩方面起着重要的作 用；肌球蛋白和肌动蛋白共占总肌丝蛋白质的 65% ，原肌球蛋白和肌钙蛋白各占5% ，其它的 调节和结构蛋白约占肌丝蛋白质的25%。","q":"蛋白质的热变性主要是（  ）。","o":["A．破坏氢键","B．破坏离子键","C．破坏疏水键","D．破坏水化层"]},{"id":"bc04_bank_mcq_3","kind":"mcq","no":3,"src":"朱圣庚4版配套题库·第4章·选择题","a":"D","e":"正确答案：D．溶解度减小。对应知识点：AI导学：Mb（肌红蛋白）/Hb（血红蛋白）到底在讲什么？。Mb（肌红蛋白） = myoglobin（肌红蛋白）；Hb（血红蛋白） = hemoglobin（血红蛋白）。；一句话：Mb（肌红蛋白）是肌肉里的“氧气瓶”，Hb（血红蛋白）是血液里的“氧气出租车”。。","q":"当蛋白质处于等电点时，可使蛋白质分子的（  ）","o":["A．稳定性增加","B．表面净电荷不变","C．表面净电荷增加","D．溶解度减小"]}]};
